# test "design-model: a model round-trips every modelled field into the block"
public func test_design_model_a_model_round_trips_every_modelled_field_into_the_block(out: Stream) -> bool:
    mut diag = m.Diag(message=b"")
    match m.load(sample(), mut diag):
        case Err(error):
            return ex.eq_str(out, "load", error, "")
        case Ok(model):
            if not ex.eq_bytes(out, "design", model.design, b"demo"):
                return False
            mut b = model.block.copy()
            if not ex.eq_bytes(out, "block", b.name, b"Demo Board"):
                return False
            if not ex.eq_int(out, "instances", len(b.instances), 2):
                return False
            mut reg = b.instances[0].copy()
            if not ex.eq_bytes(out, "ref", reg.ref_des, b"U1"):
                return False
            if not ex.eq_bytes(out, "component", reg.component, b"ldo"):
                return False
            if not ex.eq_bytes(out, "value default", reg.value, b""):
                return False
            if not ex.eq_bytes(out, "id", reg.id, b"a171124e"):
                return False
            if not ex.eq_bytes(out, "property", reg.properties[0].value, b"TLV755"):
                return False
            if not ex.eq_bytes(out, "part pin", reg.parts[0].pins[1].pin, b"5"):
                return False
            mut c1 = b.instances[1].copy()
            if not ex.ok(out, "dnp", c1.dnp):
                return False
            if not ex.eq_bytes(out, "decouple ic", c1.bind.decouple.ic, b"U1"):
                return False
            if not ex.eq_bytes(out, "decouple pin", c1.bind.decouple.pin, b"1"):
                return False
            if not ex.eq_bytes(out, "net pin", b.nets[0].pins[1].ref_des, b"C1"):
                return False
            if not ex.eq_bytes(out, "tie", b.net_ties[0].b, b"ldo/VIN"):
                return False
            mut sec = b.sections[0].copy()
            if not ex.eq_bytes(out, "member", sec.instances[0].ref_des, b"U1"):
                return False
            if not ex.eq_bytes(out, "pin group", sec.pin_groups[0].pins[0].net, b"VIN"):
                return False
            if not ex.ok(out, "signal type", sec.ports[0].signal_type == env_mod.SignalType.power):
                return False
            if not ex.eq_bytes(out, "host", sec.hosts[0], b"ldo"):
                return False
            if not ex.eq_bytes(out, "nested section", sec.sub_sections[0].instances[0].ref_des, b"C1"):
                return False
            mut sub = b.sub_blocks[0].copy()
            if not ex.eq_bytes(out, "sub-block", sub.name, b"ldo"):
                return False
            if not ex.eq_bytes(out, "sub-block name", sub.block.name, b"ldo-module"):
                return False
            return ex.eq_bytes(out, "escaped quote retained", sub.block.instances[0].value, b"0.1\\\"q")


func error_of(result: Result[m.Model, str]) -> str:
    match result:
        case Ok(_):
            return ""
        case Err(error):
            return error.copy()


# test "design-model: a malformed model names the offending line"
public func test_design_model_a_malformed_model_names_the_offending_line(out: Stream) -> bool:
    mut diag = m.Diag(message=b"")
    mut bad = b"(sch-model 1\n  (design \"d\")\n  (block \"b\"\n    (wire \"x\")))\n"
    mut error = error_of(m.load(bad, mut diag))
    if not ex.eq_str(out, "bad form", error, m.err_bad_model):
        return False
    if not ex.eq_int(out, "offending line", diag.line, 4):
        return False
    if not ex.eq_bytes(out, "diagnostic", diag.message, b"unknown block form"):
        return False
    mut error2 = error_of(m.load(b"(sch-model 2 (design \"d\"))", mut diag))
    if not ex.eq_str(out, "unsupported version", error2, m.err_bad_model):
        return False
    mut error3 = error_of(m.load(b"(sch-model 1 (block \"b\"))", mut diag))
    return ex.eq_str(out, "missing design", error3, m.err_bad_model)

import eval_env as env_mod
import render_block_types as rb
import support_strs as strs

# Flattened hierarchical refs belong to their first top-level sub-block; plain
# refs resolve to the first section/top-level member that registered them.
public record Membership:
    ref_to_node: dict[str, int]
    sub_to_node: dict[str, int]


public func membership_resolve(self: Membership, flat_ref: bytes) -> int?:
    mut slash = flat_ref.find(b"/")
    if slash >= 0:
        mut sub_key = strs.text(flat_ref[:slash])
        if sub_key in self.sub_to_node:
            return Some(self.sub_to_node[sub_key])
        return None
    mut key = strs.text(flat_ref)
    if key in self.ref_to_node:
        return Some(self.ref_to_node[key])
    return None


# sec_node/sub_node None suppresses/folds a node; attachments are section ids.
public func build(block: env_mod.DesignBlock, sec_node: int?[], sub_node: int?[], sub_attachments: int?[]) -> Membership:
    mut ref_to_node: dict[str, int] = {}
    mut sub_to_node: dict[str, int] = {}
    mut si = 0
    while si < len(block.sections):
        mut sec = block.sections[si].copy()
        mut nid = sec_node[si]
        if nid is not None:
            add_section_refs(mut ref_to_node, sec, nid)
            for ss in sec.sub_sections:
                add_section_refs(mut ref_to_node, ss, nid)
        si += 1
    mut bi = 0
    while bi < len(block.sub_blocks):
        mut nid2 = node_for_sub(bi, sec_node, sub_node, sub_attachments)
        if nid2 is not None:
            put_if_absent(mut sub_to_node, block.sub_blocks[bi].name, nid2)
        bi += 1
    return Membership(ref_to_node=ref_to_node, sub_to_node=sub_to_node)


func add_section_refs(mut map_: dict[str, int], sec: env_mod.Section, nid: int):
    for inst in sec.instances:
        put_if_absent(mut map_, inst.ref_des, nid)
    for pg in sec.pin_groups:
        put_if_absent(mut map_, pg.ref_des, nid)


func node_for_sub(bi: int, sec_node: int?[], sub_node: int?[], sub_attachments: int?[]) -> int?:
    if bi < len(sub_attachments):
        mut host_sec = sub_attachments[bi]
        if host_sec is not None:
            if host_sec < len(sec_node):
                return sec_node[host_sec]
            return None
    if bi < len(sub_node):
        return sub_node[bi]
    return None


func put_if_absent(mut map_: dict[str, int], key: bytes, nid: int):
    if len(key) == 0:
        return
    mut text = strs.text(key)
    if text not in map_:
        map_[text] = nid


# Attach to the section sharing most signal nets. Explicit hosts override;
# connector sections lose ties to a functional section. Power is excluded.
public func compute_sub_block_attachments(block: env_mod.DesignBlock) -> int?[]:
    mut result: int?[] = []
    for sb in block.sub_blocks:
        result.append(None)
    if len(block.sub_blocks) == 0 or len(block.sections) == 0:
        return result
    mut net_to_subs: dict[str, set[str]] = {}
    for nt in block.net_ties:
        mut a_slash = nt.a.find(b"/")
        mut b_slash = nt.b.find(b"/")
        mut parent = b""
        mut sub = b""
        if a_slash < 0 and b_slash >= 0:
            parent = nt.a.copy()
            sub = nt.b[:b_slash]
        elif b_slash < 0 and a_slash >= 0:
            parent = nt.b.copy()
            sub = nt.a[:a_slash]
        else:
            continue
        mut key = strs.text(parent)
        if key not in net_to_subs:
            net_to_subs[key.copy()] = set()
        net_to_subs[key].add(strs.text(sub))
    mut sb_name_to_idx: dict[str, int] = {}
    mut idx = 0
    while idx < len(block.sub_blocks):
        sb_name_to_idx[strs.text(block.sub_blocks[idx].name)] = idx
        idx += 1
    # First explicit section declaration wins; hosts are authoritative.
    mut explicit_host: dict[str, int] = {}
    mut sec_idx = 0
    while sec_idx < len(block.sections):
        for host_name in block.sections[sec_idx].hosts:
            mut host_key = strs.text(host_name)
            if host_key not in explicit_host:
                explicit_host[host_key] = sec_idx
        sec_idx += 1
    # Collect shared power nets before computing peripheral affinity.
    mut power_nets: set[str] = set()
    for sec in block.sections:
        for port in sec.ports:
            if port.signal_type == env_mod.SignalType.power:
                power_nets.add(strs.text(port.name))
    mut sec_count = len(block.sections)
    mut sb_count = len(block.sub_blocks)
    mut counts: int[] = []
    mut count_idx = 0
    while count_idx < sb_count * sec_count:
        counts.append(0)
        count_idx += 1
    mut sec_idx2 = 0
    while sec_idx2 < sec_count:
        mut sec2 = block.sections[sec_idx2].copy()
        mut sec_nets: set[str] = set()
        for pg in sec2.pin_groups:
            for p in pg.pins:
                sec_nets.add(strs.text(p.net))
        for port2 in sec2.ports:
            sec_nets.add(strs.text(port2.name))
        for net in sec_nets:
            if net in power_nets or net not in net_to_subs:
                continue
            mut subs = net_to_subs[net].copy()
            if len(subs) != 1:
                continue
            for sub_name in subs:
                if sub_name in sb_name_to_idx:
                    mut sb_idx = sb_name_to_idx[sub_name]
                    counts[sb_idx * sec_count + sec_idx2] += 1
        sec_idx2 += 1
    mut sb_idx2 = 0
    while sb_idx2 < sb_count:
        mut sb2 = block.sub_blocks[sb_idx2].copy()
        mut sb_key = strs.text(sb2.name)
        if sb_key in explicit_host:
            result[sb_idx2] = Some(explicit_host[sb_key])
            sb_idx2 += 1
            continue
        mut best_idx: int? = None
        mut best_count = 0
        mut best_is_conn = True
        mut sec_idx3 = 0
        while sec_idx3 < sec_count:
            mut sec3 = block.sections[sec_idx3].copy()
            mut c = counts[sb_idx2 * sec_count + sec_idx3]
            if c > 0:
                mut is_conn = rb.classify_by_name(sec3.name, sec3.instances) == rb.Category.connector
                # A module belongs with its subsystem, not the connector its
                # I/O happens to pass through. Count first, functional tie next.
                mut better = c > best_count or (c == best_count and best_is_conn and not is_conn)
                if better:
                    best_count = c
                    best_idx = Some(sec_idx3)
                    best_is_conn = is_conn
            sec_idx3 += 1
        if best_count >= 1:
            result[sb_idx2] = best_idx
        sb_idx2 += 1
    return result


# Indices are identity: two instances of one module may be equal by value.
# Preserve declaration order and share the same ownership decision everywhere.
public func attached_sub_blocks(block: env_mod.DesignBlock, sub_attachments: int?[], sec_idx: int) -> int[]:
    mut out: int[] = []
    mut sb_idx = 0
    while sb_idx < len(block.sub_blocks):
        if sb_idx >= len(sub_attachments):
            break
        mut host = sub_attachments[sb_idx]
        if host is not None:
            if host == sec_idx:
                out.append(sb_idx)
        sb_idx += 1
    return out

# Port of zig/src/escape.zig: shared HTML/XML/SVG output escaping. Zig's
# `writeXml(w: anytype, s)` writes into any writer; here the writer is a
# `byte_builder.Builder`.
import byte_builder

# Append the entity for one byte, or the byte itself. `apostrophe` is the only
# thing the two public spellings disagree about.
func write_entities(mut w: byte_builder.Builder, s: bytes, apostrophe: bytes):
    for c in s:
        if c == ord("&"):
            byte_builder.append(mut w, b"&amp;")
        elif c == ord("<"):
            byte_builder.append(mut w, b"&lt;")
        elif c == ord(">"):
            byte_builder.append(mut w, b"&gt;")
        elif c == ord("\""):
            byte_builder.append(mut w, b"&quot;")
        elif c == ord("'"):
            byte_builder.append(mut w, apostrophe)
        else:
            _ = byte_builder.append_byte(mut w, c)


# Escape `s` for an XML/HTML text node AND for quoted attribute values:
# `& < > " '` become entities (the apostrophe as `&#39;`).
public func write_xml(mut w: byte_builder.Builder, s: bytes):
    write_entities(mut w, s, b"&#39;")


# `write_xml` with the apostrophe spelled `&#x27;` instead of `&#39;`.
public func write_xml_hex_apos(mut w: byte_builder.Builder, s: bytes):
    write_entities(mut w, s, b"&#x27;")


# Inverse of `write_xml`: expand exactly the entity set it produces. An
# unrecognised `&...;` run is copied through verbatim.
public func decode_xml_alloc(s: bytes) -> bytes:
    mut names = [b"&amp;", b"&lt;", b"&gt;", b"&quot;", b"&#39;"]
    mut chars = [ord("&"), ord("<"), ord(">"), ord("\""), ord("'")]
    mut out = byte_builder.create()
    mut i = 0
    mut n = len(s)
    while i < n:
        if s[i] == ord("&"):
            mut matched = False
            for k in range(len(names)):
                mut name = names[k].copy()
                if s[i:min(i + len(name), n)] == name:
                    _ = byte_builder.append_byte(mut out, chars[k])
                    i += len(name)
                    matched = True
                    break
            if matched:
                continue
        _ = byte_builder.append_byte(mut out, s[i])
        i += 1
    return byte_builder.finish(out)

import sexpr_ast as ast
import eval_env as env_mod

# Parse library pin-function electrical declarations for ERC. Few parts carry
# these fields; absent declarations retain the pin-name heuristic fallback.
# Unknown sub-forms are ignored for forwards compatibility. Malformed values
# of recognised fields are rejected so a typo cannot silently erase metadata.
public func parse(form_children: ast.Node[]) -> env_mod.ElectricalDecl?:
    if len(form_children) < 2:
        return None
    mut pin_name = try ast.as_string(form_children[1])
    if not known_sub_forms_valid(form_children[2:]):
        return None
    mut decl = env_mod.ElectricalDecl(pin=pin_name, domain_=b"")
    parse_sub_forms(mut decl, form_children[2:])
    return Some(decl)


func known_sub_forms_valid(subs: ast.Node[]) -> bool:
    for sub in subs:
        mut items = ast.as_list(sub)
        if items is None:
            continue
        if len(items) == 0:
            continue
        mut head = ast.as_atom(items[0])
        if head is None:
            continue
        if head == b"type":
            if len(items) < 2:
                return False
            mut value = ast.as_atom(items[1])
            if value is None:
                return False
            if parse_electrical_type(value).is_none():
                return False
        elif head == b"drive":
            if len(items) < 2:
                return False
            mut drive_value = ast.as_atom(items[1])
            if drive_value is None:
                return False
            if parse_drive(drive_value).is_none():
                return False
        elif is_numeric_field(head):
            if len(items) < 2:
                return False
            if ast.as_number(items[1]).is_none():
                return False
        elif head == b"domain":
            if len(items) < 2:
                return False
            if ast.as_atom(items[1]).is_none():
                return False
    return True


func is_numeric_field(head: bytes) -> bool:
    mut names: bytes[] = [b"v-ih-min", b"v-il-max", b"v-oh-typ", b"v-ol-typ", b"max-voltage"]
    for name in names:
        if head == name:
            return True
    return False


# Shared with inline electrical clauses on ports. The caller sets the pin
# before passing sub-forms; this function only fills optional electrical slots.
public func parse_sub_forms(mut decl: env_mod.ElectricalDecl, subs: ast.Node[]):
    for sub in subs:
        mut items = ast.as_list(sub)
        if items is None:
            continue
        if len(items) < 2:
            continue
        mut head = ast.as_atom(items[0])
        if head is None:
            continue
        if head == b"type":
            mut v = ast.as_atom(items[1])
            if v is not None:
                decl.electrical_type = parse_electrical_type(v)
        elif head == b"drive":
            mut dv = ast.as_atom(items[1])
            if dv is not None:
                decl.drive = parse_drive(dv)
        elif head == b"v-ih-min":
            decl.v_ih_min = ast.as_number(items[1])
        elif head == b"v-il-max":
            decl.v_il_max = ast.as_number(items[1])
        elif head == b"v-oh-typ":
            decl.v_oh_typ = ast.as_number(items[1])
        elif head == b"v-ol-typ":
            decl.v_ol_typ = ast.as_number(items[1])
        elif head == b"max-voltage":
            decl.max_voltage = ast.as_number(items[1])
        elif head == b"domain":
            mut a = ast.as_atom(items[1])
            if a is not None:
                decl.domain_ = a.copy()


# Unknown sub-forms ignored.
func parse_electrical_type(s: bytes) -> env_mod.ElectricalType?:
    if s == b"input":
        return Some(env_mod.ElectricalType.input)
    if s == b"output":
        return Some(env_mod.ElectricalType.output)
    if s == b"io":
        return Some(env_mod.ElectricalType.io)
    if s == b"power-in":
        return Some(env_mod.ElectricalType.power_in)
    if s == b"power-out":
        return Some(env_mod.ElectricalType.power_out)
    if s == b"passive":
        return Some(env_mod.ElectricalType.passive)
    if s == b"nc":
        return Some(env_mod.ElectricalType.nc)
    return None


func parse_drive(s: bytes) -> env_mod.Drive?:
    if s == b"push-pull":
        return Some(env_mod.Drive.push_pull)
    if s == b"open-drain":
        return Some(env_mod.Drive.open_drain)
    if s == b"open-emitter":
        return Some(env_mod.Drive.open_emitter)
    return None

import eval_electrical as m
import eval_env as env
import sexpr_parser as parser
import sexpr_ast as ast
import support_expect as ex

func form(source: bytes) -> ast.Node[]?:
    match parser.parse(source):
        case Ok(nodes):
            if len(nodes) == 0:
                return None
            return ast.as_list(nodes[0])
        case Err(_):
            return None


func declaration(source: bytes) -> env.ElectricalDecl?:
    mut children = try form(source)
    return m.parse(children)


func near(out: Stream, label: str, got: float?, want: float) -> bool:
    if got is None:
        return ex.ok(out, label, False)
    return ex.near(out, label, got, want, 1e-9)


# test "parse reads pin function name"
public func test_parse_reads_pin_function_name(out: Stream) -> bool:
    mut decl = declaration(b"(electrical \"VDD_1\" (type power-in))")
    if decl is None:
        return ex.ok(out, "decl", False)
    if not ex.eq_bytes(out, "pin", decl.pin, b"VDD_1"):
        return False
    mut electrical_type = decl.electrical_type
    if electrical_type is None:
        return False
    return ex.ok(out, "type", electrical_type == env.ElectricalType.power_in)


# test "parse returns null without pin name"
public func test_parse_returns_null_without_pin_name(out: Stream) -> bool:
    return ex.ok(out, "missing pin", declaration(b"(electrical)").is_none())


# test "parse rejects an unknown electrical type"
public func test_parse_rejects_an_unknown_electrical_type(out: Stream) -> bool:
    return ex.ok(out, "unknown type", declaration(b"(electrical \"VDD\" (type mystery))").is_none())


record TypeCase:
    src: bytes
    expected: env.ElectricalType


# test "parse recognises all electrical types"
public func test_parse_recognises_all_electrical_types(out: Stream) -> bool:
    mut cases = [TypeCase(src=b"(electrical \"P\" (type input))", expected=env.ElectricalType.input), TypeCase(src=b"(electrical \"P\" (type output))", expected=env.ElectricalType.output), TypeCase(src=b"(electrical \"P\" (type io))", expected=env.ElectricalType.io), TypeCase(src=b"(electrical \"P\" (type power-in))", expected=env.ElectricalType.power_in), TypeCase(src=b"(electrical \"P\" (type power-out))", expected=env.ElectricalType.power_out), TypeCase(src=b"(electrical \"P\" (type passive))", expected=env.ElectricalType.passive), TypeCase(src=b"(electrical \"P\" (type nc))", expected=env.ElectricalType.nc)]
    for row in cases:
        mut decl = declaration(row.src)
        if decl is None:
            return ex.ok(out, "decl", False)
        mut electrical_type = decl.electrical_type
        if electrical_type is None:
            return ex.ok(out, "type exists", False)
