import eval_env as env_mod
import net_name
import support_strs as strs

# Shared validator/ERC helpers keep eval-time and on-demand checks in lockstep.
# Every ground vocabulary lives here, below both the optimizer and pin_roles.
# These independent tables deliberately retain their consumers' different
# spellings: merging them would change behaviour and requires a separate test.
public const analog_ground: bytes = b"AGND"


public const digital_ground: bytes = b"DGND"


public const power_ground: bytes = b"PGND"


const signal_ground: bytes = b"SGND"


const analog_ground_suffixed: bytes = b"GNDA"


const digital_ground_suffixed: bytes = b"GNDD"


# Longest first prevents GNDA from being shadowed by GND. Numbered suffixes
# identify ground twins, while signal names such as GND_SENSE remain signals.
public func ground_tokens() -> bytes[]:
    return [analog_ground_suffixed, digital_ground_suffixed, analog_ground, power_ground, digital_ground, b"VSSA", b"GND", b"VSS"]


public func is_ground_name(name: bytes) -> bool:
    for token in ground_tokens():
        if not name.startswith(token):
            continue
        mut rest = name[len(token):]
        if len(rest) == 0:
            return True
        if rest[0] == 95 or rest[0] == 45:
            rest = rest[1:]
        if len(rest) == 0:
            return False
        for c in rest:
            if not strs.is_digit(c):
                return False
        return True
    return False


# Chassis is a DC zero-volt rating reference, but never a ground pour token:
# copper must preserve the intended shield/chassis isolation barrier.
public const chassis_ground: bytes = b"CHASSIS_GND"


public func is_rating_zero_volts(name: bytes) -> bool:
    if is_ground_name(name):
        return True
    if not name.startswith(chassis_ground):
        return False
    mut rest = name[len(chassis_ground):]
    if len(rest) == 0:
        return True
    if rest[0] == 95 or rest[0] == 45:
        rest = rest[1:]
    if len(rest) == 0:
        return False
    for c in rest:
        if not strs.is_digit(c):
            return False
    return True


# Normalised pin-function prefixes uniquely include SGND and accept any suffix.
public func ground_fn_prefixes() -> bytes[]:
    return [b"GND", b"VSS", analog_ground, digital_ground, power_ground, signal_ground]


public func ground_base_names() -> bytes[]:
    return [b"GND", analog_ground, digital_ground, power_ground]


public func ground_stem_prefixes() -> bytes[]:
    return [b"GND_", b"AGND_", b"DGND_", b"PGND_", b"VSS"]


# The schematic intentionally draws PGND as its own labelled node.
public func schematic_ground_names() -> bytes[]:
    return [b"GND", analog_ground, digital_ground]


# A first-dot collapse folds per-pin bypass stub names onto their base rail.
public func base_net_name(name: bytes) -> bytes:
    mut idx = name.find(b".")
    if idx >= 0:
        return name[:idx]
    return name.copy()


public func is_sub_net_name(name: bytes) -> bool:
    return len(base_net_name(name)) != len(name)


# Display-side first-dot rule is intentionally distinct from stub.split's
# last-two-dots structural fold: 3.3V.U1.5 hints 3V here, not U1.
public func sub_net_host_ref(name: bytes) -> bytes?:
    mut rail = base_net_name(name)
    if len(rail) == len(name):
        return None
    mut rest = name[len(rail) + 1:]
    mut host = base_net_name(rest)
    if len(host) == len(rest):
        return None
    return Some(host)


public func ref_des_local_prefix(ref_des: bytes) -> int:
    mut local = net_name.leaf(ref_des)
    if len(local) == 0:
        return 0
    return local[0]


# Walk a sub-block path to count bypassing inside a tied module's power port.
public func sub_block_net_has_cap(block: env_mod.DesignBlock, net_path: bytes) -> bool:
    mut slash = net_path.find(b"/")
    if slash >= 0:
        mut head = net_path[:slash]
        mut rest = net_path[slash + 1:]
        for sb in block.sub_blocks:
            if sb.name == head:
                return sub_block_net_has_cap(sb.block, rest)
        return False
    for n in block.nets:
        if n.name != net_path:
            continue
        for pin in n.pins:
            if len(pin.ref_des) == 0:
                continue
            if ref_des_local_prefix(pin.ref_des) == 67 and cap_bridges_base_to_ground(block, pin.ref_des, base_net_name(n.name)):
                return True
        return False
    return False


# Return each rail with an IC and no cap once, retaining block.nets order.
public func find_missing_decoupling_nets(block: env_mod.DesignBlock) -> bytes[]:
    mut power_nets: set[str] = set()
    for port in block.ports:
        if port.direction != b"in":
            continue
        # Explicit non-power kind overrides rated enable/control input specs.
        if env_mod.port_is_declared_non_power(port):
            continue
        if strs.eql_ignore_case(port.kind, b"power") or env_mod.port_is_power_source(port):
            power_nets.add(strs.text(base_net_name(port.net)))
    for sec in block.sections:
        collect_section_power_inputs(mut power_nets, sec)
    # Fold trunk and per-pin bypass stubs together before judging a rail.
    mut rails_with_ic: set[str] = set()
    mut rails_with_cap: set[str] = set()
    for net in block.nets:
        mut base = base_net_name(net.name)
        mut key = strs.text(base)
        if key not in power_nets:
            continue
        for pin in net.pins:
            if len(pin.ref_des) == 0:
                continue
            mut prefix = ref_des_local_prefix(pin.ref_des)
            if prefix == 85:
                rails_with_ic.add(key.copy())
            elif prefix == 67 and cap_bridges_base_to_ground(block, pin.ref_des, base):
                rails_with_cap.add(key.copy())
    mut missing: bytes[] = []
    mut emitted: set[str] = set()
    for net2 in block.nets:
        mut base2 = base_net_name(net2.name)
        mut key2 = strs.text(base2)
        if key2 not in rails_with_ic or key2 in rails_with_cap or key2 in emitted:
            continue
        if tied_sub_block_has_cap(block, base2):
            continue
        emitted.add(key2)
        missing.append(base2)
    return missing


func collect_section_power_inputs(mut power_nets: set[str], section: env_mod.Section):
    # Concept sections have no wired implementation yet; do not demand bypassing.
    if section.status == env_mod.SectionStatus.concept:
        return
    for port in section.ports:
        if port.signal_type == env_mod.SignalType.power and port.direction == env_mod.PortDirection.in_:
            power_nets.add(strs.text(base_net_name(port.name)))
    for sub in section.sub_sections:
        collect_section_power_inputs(mut power_nets, sub)


# A cap only qualifies if it touches both the rail and a recognised ground.
func cap_bridges_base_to_ground(block: env_mod.DesignBlock, cap_ref: bytes, rail_base: bytes) -> bool:
    mut has_rail = False
    mut has_ground = False
    for net in block.nets:
        mut touches = False
        for pin in net.pins:
            if pin.ref_des == cap_ref:
                touches = True
                break
        if not touches:
            continue
        mut base = base_net_name(net.name)
        if base == rail_base:
            has_rail = True
        if is_ground_base(base):
            has_ground = True
    return has_rail and has_ground


# private in Zig; public for its test counterpart. Unlike other ground tests,
# this eval-layer predicate accepts case straight from an authored design file.
public func is_ground_base(name: bytes) -> bool:
    for ground in ground_base_names():
        if strs.eql_ignore_case(name, ground):
            return True
    if strs.eql_ignore_case(name, b"VSS"):
        return True
    return strs.starts_with_ignore_case(name, b"GND_") or strs.starts_with_ignore_case(name, b"VSS_")


func tied_sub_block_has_cap(block: env_mod.DesignBlock, base: bytes) -> bool:
    for tie in block.net_ties:
        mut other: bytes? = None
        if tie.a == base:
            other = Some(tie.b.copy())
        elif tie.b == base:
            other = Some(tie.a.copy())
        if other is not None:
            if other.find(b"/") >= 0 and sub_block_net_has_cap(block, other):
                return True
    return False


# Union-find shared by rail construction and power budgeting. findRoot reads
# its map, so unlike Zig's pointer spelling the mylang argument is plain.
public func find_root(parent: dict[str, bytes], name: bytes) -> bytes:
    mut cur = name.copy()
    while strs.text(cur) in parent:
        mut p = parent[strs.text(cur)].copy()
        if p == cur:
            return cur
        cur = p
    return cur


func union_nets(mut parent: dict[str, bytes], a: bytes, b: bytes):
    mut ra = find_root(parent, a)
    mut rb = find_root(parent, b)
    if ra == rb:
        return
    parent[strs.text(rb)] = ra


# Preserve pad-1/pad-2 bridge behaviour, including a multi-channel partial
# bridge. A no-1/2 bead bridges by membership only for exactly two base nets;
# a true array touching three or more nets must never be mis-bridged.
public func build_ferrite_bridges(block: env_mod.DesignBlock) -> dict[str, bytes]:
    mut net_parent: dict[str, bytes] = {}
    for inst in block.instances:
        if not inst.component.startswith(b"ferrite"):
            continue
        mut net_a: bytes? = None
        mut net_b: bytes? = None
        mut d0: bytes? = None
        mut d1: bytes? = None
        mut multi = False
        for net in block.nets:
            mut base = base_net_name(net.name)
            mut touches = False
            for p in net.pins:
                if p.ref_des != inst.ref_des:
                    continue
                touches = True
                if p.pin == b"1":
                    net_a = Some(base.copy())
                if p.pin == b"2":
                    net_b = Some(base.copy())
            if not touches:
                continue
            if d0 is None:
                d0 = Some(base.copy())
            elif d0 != base:
                if d1 is None:
                    d1 = Some(base.copy())
                elif d1 != base:
                    multi = True
        if net_a is not None and net_b is not None:
            union_nets(mut net_parent, net_a, net_b)
        elif not multi:
            if d0 is not None and d1 is not None:
                union_nets(mut net_parent, d0, d1)
    return net_parent

import eval_net_analysis as m
import eval_env as env
import support_expect as ex

# Independent witness tables are literal former consumer vocabularies. Deriving
# them from the production tables would make the assertions circular.
# test "the ground-net vocabulary tables keep the spellings their consumers had"
public func test_the_ground_net_vocabulary_tables_keep_the_spellings_their_consumers_had(out: Stream) -> bool:
    mut tokens: bytes[] = [b"GNDA", b"GNDD", b"AGND", b"PGND", b"DGND", b"VSSA", b"GND", b"VSS"]
    mut functions: bytes[] = [b"GND", b"VSS", b"AGND", b"DGND", b"PGND", b"SGND"]
    mut bases: bytes[] = [b"GND", b"AGND", b"DGND", b"PGND"]
    mut stems: bytes[] = [b"GND_", b"AGND_", b"DGND_", b"PGND_", b"VSS"]
    mut schematic: bytes[] = [b"GND", b"AGND", b"DGND"]
    if not ex.ok(out, "ground tokens", m.ground_tokens() == tokens):
        return False
    if not ex.ok(out, "function prefixes", m.ground_fn_prefixes() == functions):
        return False
    if not ex.ok(out, "base names", m.ground_base_names() == bases):
        return False
    if not ex.ok(out, "stem prefixes", m.ground_stem_prefixes() == stems):
        return False
    if not ex.ok(out, "schematic names", m.schematic_ground_names() == schematic):
        return False
    if not ex.eq_bytes(out, "analog", m.analog_ground, b"AGND"):
        return False
    if not ex.eq_bytes(out, "digital", m.digital_ground, b"DGND"):
        return False
    return ex.eq_bytes(out, "power", m.power_ground, b"PGND")


# test "isRatingZeroVolts adds only the chassis node to the ground tokens"
public func test_isratingzerovolts_adds_only_the_chassis_node_to_the_ground_tokens(out: Stream) -> bool:
    if not ex.ok(out, "chassis", m.is_rating_zero_volts(b"CHASSIS_GND")):
        return False
    if not ex.ok(out, "numbered chassis", m.is_rating_zero_volts(b"CHASSIS_GND2")):
        return False
    if not ex.ok(out, "ground", m.is_rating_zero_volts(b"GND")):
        return False
    if not ex.ok(out, "analog", m.is_rating_zero_volts(b"AGND3")):
        return False
    # Named chassis derivative is distinct from a numbered twin.
    if not ex.ok(out, "isolated chassis", not m.is_rating_zero_volts(b"CHASSIS_GND_ISO")):
        return False
    if not ex.ok(out, "rail", not m.is_rating_zero_volts(b"V_12V")):
        return False
    # Keep the barrier open to pour, plane stitcher, and DRC.
    if not ex.ok(out, "no chassis pour", not m.is_ground_name(m.chassis_ground)):
        return False
    for token in m.ground_tokens():
        if not ex.ok(out, "not a chassis token", token != m.chassis_ground):
            return False
    return True


# test "isGroundBase accepts the base names in any case and only those"
public func test_isgroundbase_accepts_the_base_names_in_any_case_and_only_those(out: Stream) -> bool:
    mut yes: bytes[] = [b"GND", b"gnd", b"AGND", b"dgnd", b"PGND", b"VSS", b"GND_ISO", b"vss_a"]
    for name in yes:
        if not ex.ok(out, "accepted", m.is_ground_base(name)):
            return False
    # The suffix spellings are deliberately omitted from this table.
    mut no: bytes[] = [b"GNDA", b"GNDSW", b"VDD"]
    for name2 in no:
        if not ex.ok(out, "rejected", not m.is_ground_base(name2)):
            return False
    return True


func input_port() -> env.Port:
    mut port = env.port_default(b"VIN", b"VDD", b"in")
    port.kind = b"power"
    return port


func ic() -> env.Instance:
    mut part = env.instance_default(b"U1")
    part.component = b"ic"
    part.value = b"ic"
    part.footprint = b"x"
    part.symbol = b"ic"
    return part


# test "top-level input power ports require decoupling"
public func test_top_level_input_power_ports_require_decoupling(out: Stream) -> bool:
    mut block = env.design_block_default(b"top power port")
    block.instances = [ic()]
    block.nets = [env.Net(name=b"VDD", pins=[env.pin_ref_default(b"U1", b"1")])]
    block.ports = [input_port()]
    mut missing = m.find_missing_decoupling_nets(block)
    if not ex.eq_int(out, "missing count", len(missing), 1):
        return False
    return ex.eq_bytes(out, "missing rail", missing[0], b"VDD")


# test "supply capacitor without a ground leg is not decoupling"
public func test_supply_capacitor_without_a_ground_leg_is_not_decoupling(out: Stream) -> bool:
    mut cap = env.instance_default(b"C1")
    cap.component = b"cap"
    cap.value = b"100nF"
    cap.footprint = b"x"
    cap.symbol = b"cap"
    mut wrong_nets = [env.Net(name=b"VDD", pins=[env.pin_ref_default(b"U1", b"1"), env.pin_ref_default(b"C1", b"1")]), env.Net(name=b"SENSE", pins=[env.pin_ref_default(b"C1", b"2")])]
    mut block = env.design_block_default(b"wrong return")
    block.instances = [ic(), cap]
    block.nets = wrong_nets
    block.ports = [input_port()]
    mut missing = m.find_missing_decoupling_nets(block)
    if not ex.eq_int(out, "missing count", len(missing), 1):
        return False
    mut valid_nets = [env.Net(name=b"VDD", pins=[env.pin_ref_default(b"U1", b"1"), env.pin_ref_default(b"C1", b"1")]), env.Net(name=b"GND", pins=[env.pin_ref_default(b"C1", b"2")])]
    block.nets = valid_nets
    mut satisfied = m.find_missing_decoupling_nets(block)
    return ex.eq_int(out, "satisfied", len(satisfied), 0)

import eval_env as env_mod
import eval_net_analysis as na
import support_strs as strs
import support_sort as srt

const gnd_name: bytes = b"GND"


const sub_path_buf_len: int = 256


# Derive sources, union ferrite-connected DC rails, then resolve voltage from
# sub-block nominal, section voltage, and top-level nominal/rated midpoint.
# Higher source capacity wins independently of declaration order.
public func build(block: env_mod.DesignBlock) -> env_mod.PowerRail[]:
    # A ferrite is a DC conductor; downstream loads belong to the upstream rail.
    mut net_parent = na.build_ferrite_bridges(block)
    mut by_root: dict[str, env_mod.PowerRail] = {}
    for sb in block.sub_blocks:
        for port in sb.block.ports:
            if port.direction != b"out":
                continue
            mut path_temp = sb.name + b"/" + port.name
            if len(path_temp) > sub_path_buf_len:
                continue
            mut top_net = find_top_net(block, path_temp)
            if top_net is None:
                continue
            mut base = na.base_net_name(top_net)
            if base == gnd_name:
                continue
            mut root = na.find_root(net_parent, base)
            if root == gnd_name:
                continue
            # Bare regulator VOUT is a source when its tied net reads as power;
            # declared specs enrich the budget but do not gate recognition.
            if not env_mod.port_is_power_source(port) and not looks_like_rail(base):
                continue
            mut nominal = port.nominal
            if nominal is None:
                nominal = resolve_rail_voltage(block, base)
            mut root_key = strs.text(root)
            mut existing_cap = -1.0
            if root_key in by_root:
                existing_cap = by_root[root_key].capacity_max.unwrap_or(by_root[root_key].capacity_typ.unwrap_or(0.0))
            mut incoming_cap = port.current_max.unwrap_or(port.current_typ.unwrap_or(0.0))
            if incoming_cap <= existing_cap:
                continue
            mut incoming = env_mod.PowerRail(name=base.copy(), aliases=[], nominal=nominal, rated_voltage=resolve_rail_rated_voltage(block, base, port), source_ref_des=sb.name.copy(), source_port=port.name.copy(), source_path=path_temp, capacity_typ=port.current_typ, capacity_max=port.current_max, enable_net=port.enable_net.copy())
            by_root[root_key] = incoming
    # External board-edge inputs are sources when no on-board source won root.
    for port2 in block.ports:
        if port2.direction != b"in":
            continue
        if env_mod.port_is_declared_non_power(port2) or not env_mod.port_is_power_source(port2):
            continue
        mut port_name = port2.name.copy()
        if len(port2.net) > 0:
            port_name = port2.net.copy()
        mut base2 = na.base_net_name(port_name)
        if base2 == gnd_name:
            continue
        mut root2 = na.find_root(net_parent, base2)
        mut root_key2 = strs.text(root2)
        if root_key2 in by_root:
            continue
        mut nominal2 = port2.nominal
        if nominal2 is None:
            nominal2 = midpoint(port2.rated_min, port2.rated_max)
        by_root[root_key2] = env_mod.PowerRail(name=base2, aliases=[], nominal=nominal2, rated_voltage=env_mod.PowerRailRatedVoltage(min=port2.rated_min, max=port2.rated_max), source_ref_des=b"", source_port=port2.name.copy(), source_path=b"@external/" + port2.name, capacity_typ=port2.current_typ, capacity_max=port2.current_max, enable_net=b"")
    # Group ferrite child names by root, then attach the aliases to that source.
    mut aliases_by_root: dict[str, bytes[]] = {}
    for child in net_parent:
        mut child_name = child.encode()
        mut child_root = na.find_root(net_parent, child_name)
        if child_name == child_root:
            continue
        mut key = strs.text(child_root)
        if key not in aliases_by_root:
            aliases_by_root[key.copy()] = []
        aliases_by_root[key].append(child_name)
    # Replace owned rail snapshots; indexed records remain borrowed for reads.
    mut rail_keys = list(by_root.keys()).copy()
    mut rail_idx = 0
    while rail_idx < len(rail_keys):
        mut key2 = rail_keys[rail_idx].copy()
        if key2 in aliases_by_root:
            mut aliases = aliases_by_root[key2].copy()
            mut rail = by_root[key2].copy()
            rail.aliases = aliases
            by_root[key2] = rail
        rail_idx += 1
    # Stable bytewise name sorting makes builds deterministic.
    mut out = list(by_root.values())
    srt.sort_by(mut out, less_than_rail)
    return out


func less_than_rail(a: env_mod.PowerRail, b: env_mod.PowerRail) -> bool:
    return strs.bytes_order(a.name, b.name) == -1


# Narrow V+prefix or V+digit heuristic excludes signal outputs like VSYNC.
public func looks_like_rail(name: bytes) -> bool:
    if len(name) >= 2 and name[0] == 86 and name[1] >= 48 and name[1] <= 57:
        return True
    for p in rail_prefixes():
        if name.startswith(p):
            return True
    return False


# Separate authoritative vocabularies preserve their consumers' different
# questions: only diagram lists VLX, module lists VEXT/VANA, schematic lists VSS.
public const analog_supply: bytes = b"AVDD"


public const digital_supply: bytes = b"DVDD"


public const system_rail: bytes = b"VSYS"


const power_stage_supply: bytes = b"PVDD"


const regulated_rail: bytes = b"VREG"


const bulk_rail: bytes = b"VPWR"


const raw_rail: bytes = b"VRAW"


const power_stage_input: bytes = b"PVIN"


const dc_input_rail: bytes = b"VDCIN"


const high_voltage_input: bytes = b"HVIN"


# private in Zig; public for its independent vocabulary test.
public func rail_prefixes() -> bytes[]:
    return [b"VDD", b"VCC", b"VOUT", b"VBUS", bulk_rail, regulated_rail, b"VBAT", system_rail, raw_rail, b"V_"]


public func input_rail_prefixes() -> bytes[]:
    return [b"VIN", power_stage_input, b"VBUS", b"VBAT", system_rail, dc_input_rail, high_voltage_input]


public func supply_pad_prefixes() -> bytes[]:
    return [b"VCC", b"VDD", analog_supply, digital_supply, power_stage_supply, b"VBAT", b"VBUS", b"VIN", b"VOUT", b"VEE", b"VPP", b"VREF"]


# VSS is ground but answers yes to "power-ish rather than functional signal".
public func schematic_supply_prefixes() -> bytes[]:
    return [b"VDD", b"VCC", b"VSS", b"VIN", b"VBAT", analog_supply, digital_supply, power_stage_supply, b"V_"]


public func diagram_supply_prefixes() -> bytes[]:
    return [b"VDD", b"VCC", analog_supply, digital_supply, b"VBAT", regulated_rail, b"VPOS", b"VBUS", b"VLX", b"V_"]


public func module_supply_prefixes() -> bytes[]:
    return [b"VDD", b"VCC", analog_supply, digital_supply, regulated_rail, b"VPOS", b"VOUT", b"VEXT", b"VANA", b"VREF", b"VPP", b"V_"]


# Find the first top-level net tied to this sub-block path.
func find_top_net(block: env_mod.DesignBlock, path: bytes) -> bytes?:
    for nt in block.net_ties:
        if nt.a == path:
            return Some(nt.b.copy())
        if nt.b == path:
            return Some(nt.a.copy())
    return None


func resolve_rail_voltage(block: env_mod.DesignBlock, rail_name: bytes) -> float?:
    # Second tier: section-level port (sub-block nominal is handled by build).
    for sec in block.sections:
        mut v = section_voltage(sec, rail_name)
        if v is not None:
            return Some(v)
    # Third tier: top-level nominal, then the midpoint of a complete rating.
    for p in block.ports:
        if not port_matches_rail(p, rail_name):
            continue
        mut nominal = p.nominal
        if nominal is not None:
            return Some(nominal)
        mut min_v = p.rated_min
        mut max_v = p.rated_max
        if min_v is not None and max_v is not None:
            return Some((min_v + max_v) * 0.5)
    return None


func midpoint(min_: float?, max_: float?) -> float?:
    if min_ is not None and max_ is not None:
        return Some((min_ + max_) * 0.5)
    if max_ is not None:
        return Some(max_)
    return min_


func resolve_rail_rated_voltage(block: env_mod.DesignBlock, rail_name: bytes, source: env_mod.Port) -> env_mod.PowerRailRatedVoltage:
    if source.rated_min is not None or source.rated_max is not None:
        return env_mod.PowerRailRatedVoltage(min=source.rated_min, max=source.rated_max)
    for port in block.ports:
        if port_matches_rail(port, rail_name):
            return env_mod.PowerRailRatedVoltage(min=port.rated_min, max=port.rated_max)
    return env_mod.PowerRailRatedVoltage()


# The selected port name is only compared; borrow the fields without a snapshot.
func port_matches_rail(port: env_mod.Port, rail_name: bytes) -> bool:
    if len(port.net) > 0:
        return port.net == rail_name
    return port.name == rail_name


func section_voltage(sec: env_mod.Section, rail_name: bytes) -> float?:
    for sp in sec.ports:
        if sp.name != rail_name:
            continue
        mut voltage = sp.voltage
        if voltage is not None:
            return Some(voltage)
    for sub in sec.sub_sections:
        mut v = section_voltage(sub, rail_name)
        if v is not None:
            return Some(v)
    return None

