func builder_init(block: env_mod.DesignBlock, project_dir: str, design: bytes, opts: Options, instances: flat_netlist.FlatInstance[], nets: flat_netlist.FlatNet[], sym_lib: sym_library.Library?) -> Builder:
    return Builder(block=block.copy(), project_dir=project_dir.copy(), design=design.copy(), opts=opts.copy(), instances=instances.copy(), nets=nets.copy(), pin_net={}, binds={}, net_pins={}, labels={}, ref_inst={}, fp={}, comps={}, shapes=[], src=[], keys=[], sec_of_ref={}, owners=[], attach=[], captions={}, stats=Stats(), sym_lib=sym_lib.copy())


func build(fs: Filesystem, err: Stream, mut self: Builder) -> Result[SchFile[], str]:
    index_nets(err, mut self)
    load_footprints(fs, mut self)
    index_groups(mut self)
    index_wiring(mut self)
    build_components(fs, err, mut self)
    mut sheets = partition(self)
    mut files: SchFile[] = []
    if self.opts.flat or len(sheets) < 2 or len(self.instances) <= flat_max_parts:
        files = try build_flat(err, mut self)
    else:
        files = try build_hierarchy(err, mut self, sheets)
    if self.overlaps > 0:
        log.progress(err, b"export-kicad-sch: " + self.design + f": {self.overlaps} overlapping text pairs across {len(files)} sheets".encode())
    return Ok(files)


func index_nets(err: Stream, mut self: Builder):
    for i in range(len(self.instances)):
        mut inst = self.instances[i].copy()
        mut key = strs.text(inst.ref_des)
        if key not in self.ref_inst:
            self.ref_inst[key] = i
    mut pin_net = self.pin_net.copy()
    for net in self.nets:
        for pin in net.pins:
            mut pk = pin_key(pin.ref_des, pin.pin)
            if pk not in pin_net:
                pin_net[pk] = net.name.copy()
    self.pin_net = pin_net
    mut labels = self.labels.copy()
    mut n = stub.collapse(self.nets, self.ref_inst, mut labels)
    self.labels = labels
    if n > 0:
        log.progress(err, b"export-kicad-sch: " + self.design + f": {n} per-pin bypass-stub nets labelled as their base rail".encode())


func label_of(self: Builder, net: bytes) -> bytes:
    return self.labels.get(strs.text(net), net).copy()


func index_wiring(mut self: Builder):
    for i in range(len(self.instances)):
        mut inst = self.instances[i].copy()
        mut bind = bind_of(self, inst, self.src[i])
        if bind is not None:
            self.binds[strs.text(inst.ref_des)] = bind.copy()
    mut net_pins = self.net_pins.copy()
    for net in self.nets:
        net_pins[strs.text(net.name)] = len(net.pins)
    self.net_pins = net_pins


func bind_of(self: Builder, inst: flat_netlist.FlatInstance, src: env_mod.Instance) -> compose.Bind?:
    if len(src.bind.decouple.pin) > 0 and len(src.bind.decouple.ic) > 0:
        return Some(compose.Bind(ref=qualify(inst.ref_des, src.bind.decouple.ic), pad=src.bind.decouple.pin.copy()))
    mut pad = try decouple_key.pin_from_origin(inst.origin_key)
    return hub_on_supply_net(self, inst.ref_des, pad)


func hub_on_supply_net(self: Builder, ref: bytes, pad: bytes) -> compose.Bind?:
    for net in self.nets:
        if compose.is_rail_net(net.name) or not net_touches(net, ref):
            continue
        for pin in net.pins:
            if plan.is_passive_ref(pin.ref_des) or pin.pin != pad:
                continue
            return Some(compose.Bind(ref=pin.ref_des.copy(), pad=pad.copy()))
    return None


func net_facts(self: Builder) -> compose.NetFacts:
    return compose.NetFacts(binds=Some(self.binds.copy()), net_pins=Some(self.net_pins.copy()), labels=Some(self.labels.copy()))


func load_footprints(fs: Filesystem, mut self: Builder):
    mut fp = self.fp.copy()
    for inst in self.instances:
        mut key = strs.text(inst.footprint)
        if len(inst.footprint) == 0 or key in fp:
            continue
        mut info = FpInfo(kicad_name=inst.footprint.copy(), pads=[])
        mut src = stdlib.read(fs, self.project_dir, "lib/footprints/" + key + ".sexp", lib_limits.max_footprint_bytes)
        if src is not None:
            match netlist.extract_footprint_name(src):
                case Ok(name):
                    info.kicad_name = name
                case Err(_):
                    pass
            match netlist.extract_pad_names(src):
                case Ok(pads):
                    info.pads = pads
                case Err(_):
                    pass
        fp[key] = info.copy()
    self.fp = fp


func build_components(fs: Filesystem, err: Stream, mut self: Builder):
    for i in range(len(self.instances)):
        mut inst = self.instances[i].copy()
        mut src = self.src[i].copy()
        mut key = component_key(inst, src)
        mut lookup = strs.text(key)
        self.keys.append(key)
        if lookup not in self.comps:
            self.comps[lookup] = Comp(names=shape_mod.Names(component=base_name(inst), symbol=inst.symbol.copy(), pinout=inst.pinout.copy()), footprint=inst.footprint.copy(), glyph=shape_mod.classify(base_name(inst), inst.symbol, inst.ref_des), parts=part_specs(src), pins=PadNets(ref=inst.ref_des.copy(), net={}), used=[], seen=set())
    mut comps = self.comps.copy()
    for net in self.nets:
        for pin in net.pins:
            mut ref = strs.text(pin.ref_des)
            if ref not in self.ref_inst:
                continue
            mut inst_i = self.ref_inst[ref]
            mut comp_key = strs.text(self.keys[inst_i])
            mut comp = comps[comp_key].copy()
            note_pad_net(self, mut comp, pin, net.name)
            mut pad = strs.text(pin.pin)
            if pad not in comp.seen:
                comp.seen.add(pad)
                comp.used.append(pin.pin.copy())
            comps[comp_key] = comp
    self.comps = comps
    synth_shapes(fs, err, mut self)


func note_pad_net(self: Builder, mut comp: Comp, pin: flat_netlist.FlatPin, net: bytes):
    if comp.pins.ref != pin.ref_des:
        return
    mut key = strs.text(pin.pin)
    if key not in comp.pins.net:
        comp.pins.net[key] = label_of(self, net)


func component_key(inst: flat_netlist.FlatInstance, src: env_mod.Instance) -> bytes:
    mut base = base_name(inst)
    if len(src.parts) == 0:
        return base
    mut sig = byte_builder.create()
    byte_builder.append(mut sig, base)
    for part in src.parts:
        byte_builder.append(mut sig, b"#" + part.name)
        for p in part.pins:
            byte_builder.append(mut sig, b"," + p.pin)
    return byte_builder.finish(sig)


func part_specs(src: env_mod.Instance) -> shape_mod.PartSpec[]:
    return [for part in src.parts yield shape_mod.PartSpec(title=part.name.copy(), pads=[for p in part.pins yield p.pin.copy()])]


func synth_shapes(fs: Filesystem, err: Stream, mut self: Builder):
    mut names: set[str] = set()
    mut drawn = 0
    mut comp_keys = list(self.comps.keys())
    for i in range(len(comp_keys)):
        mut key = comp_keys[i].copy()
        mut comp = self.comps[key].copy()
        mut pads: bytes[] = []
        mut fpkey = strs.text(comp.footprint)
        if fpkey in self.fp:
            pads = self.fp[fpkey].pads.copy()
        mut req = shape_mod.Request(names=comp.names.copy(), project_dir=self.project_dir.copy(), fp_pads=pads, used=comp.used.copy(), parts=comp.parts.copy(), glyph=comp.glyph, nets=Some(comp.pins.net.copy()))
        mut body = vendor.synth(fs, err, self.sym_lib, req)
        mut s = stagger.spread(body, Some(comp.pins.net.copy()))
        if s.vendor:
            drawn += 1
        mut suffix = 1
        while strs.text(s.lib_name) in names:
            s.lib_name = s.lib_name + b"_" + str(suffix).encode()
            suffix += 1
        names.add(strs.text(s.lib_name))
        comp.shape = i
        self.comps[key] = comp
        self.shapes.append(s)
    self.stats = Stats(components=len(self.comps), vendor_bodies=drawn, instances=len(self.instances))
    mut lib = self.sym_lib.copy()
    if lib is not None:
        if lib.files > 0:
            log.progress(err, b"export-kicad-sch: " + self.design + f": {drawn}/{len(self.comps)} components drawn from vendor symbols ({lib.files} libraries indexed)".encode())


func shape_of(self: Builder, idx: int) -> int:
    mut key = strs.text(self.keys[idx])
    if key not in self.comps:
        return 0
    return self.comps[key].shape


func index_groups(mut self: Builder):
    for i in range(len(self.block.sections)):
        const section = self.block.sections[i].copy()
        index_section(mut self, section, i)
    mut owners = self.owners.copy()
    mut src = self.src.copy()
    walk_tree(self.block, None, mut owners, mut src)
    self.owners = owners
    self.src = src
    self.attach = membership.compute_sub_block_attachments(self.block)


func index_section(mut self: Builder, sec: env_mod.Section, index: int):
    for inst in sec.instances:
        mut key = strs.text(inst.ref_des)
        if key not in self.sec_of_ref:
            self.sec_of_ref[key] = index
    for pg in sec.pin_groups:
        mut pkey = strs.text(pg.ref_des)
        if pkey not in self.sec_of_ref:
            self.sec_of_ref[pkey] = index
    for sub in sec.sub_sections:
        index_section(mut self, sub, index)


func sheet_key_of(self: Builder, idx: int) -> int:
    mut owner: int? = None
    if idx < len(self.owners):
        owner = self.owners[idx]
    if owner is not None:
        mut sec: int? = None
        if owner < len(self.attach):
            sec = self.attach[owner]
        if sec is not None:
            return sheet_key(SheetKind.section, sec)
        return sheet_key(SheetKind.module_, owner)
    mut key = strs.text(self.instances[idx].ref_des)
    if key in self.sec_of_ref:
        return sheet_key(SheetKind.section, self.sec_of_ref[key])
    return sheet_key(SheetKind.unsectioned, 0)


func group_of(self: Builder, idx: int) -> int:
    mut n_sec = len(self.block.sections)
    mut owner: int? = None
    if idx < len(self.owners):
        owner = self.owners[idx]
    if owner is not None:
        mut sec: int? = None
        if owner < len(self.attach):
            sec = self.attach[owner]
        mut high = n_sec
        if sec is not None:
            high = sec
        return high * 4294967296 + owner + 1
    mut key = strs.text(self.instances[idx].ref_des)
    mut high2 = n_sec + 1
    if key in self.sec_of_ref:
        high2 = self.sec_of_ref[key]
    return high2 * 4294967296


func caption_for(mut self: Builder, key: int) -> bytes:
    if key in self.captions:
        return self.captions[key].copy()
    mut n_sec = len(self.block.sections)
    mut sec = key // 4294967296
    mut sub = key % 4294967296
    mut sec_name = b""
    if sec < n_sec:
        sec_name = self.block.sections[sec].name.copy()
    mut text = b"Unsectioned"
    if sub > 0:
        mut sb_name = self.block.sub_blocks[sub - 1].name.copy()
        if len(sec_name) > 0:
            text = sec_name + b" / " + sb_name
        else:
            text = b"sub-block " + sb_name
    elif len(sec_name) > 0:
        text = sec_name
    self.captions[key] = text.copy()
    return text


func partition(self: Builder) -> SheetPlan[]:
    mut order: int[] = []
    mut members: dict[int, int[]] = {}
    for i in range(len(self.instances)):
        mut key = sheet_key_of(self, i)
        if key not in members:
            members[key] = []
            order.append(key)
        members[key].append(i)
    order.sort()
    mut seen: set[str] = set()
    mut result: SheetPlan[] = []
    for key2 in order:
        mut title = sheet_title(self, key2)
        mut stem = plan.unique_name(plan.slugify(title, b"sheet"), mut seen)
        result.append(SheetPlan(title=title, file=self.design + b"-" + stem + b".kicad_sch", uuid=emit.element_uuid(self.design, b"sheet", stem), members=members[key2].copy()))
    return result


func sheet_title(self: Builder, key: int) -> bytes:
    mut idx = key % 4294967296
    mut kind = key // 4294967296
    if kind == 0:
        if idx < len(self.block.sections) and len(self.block.sections[idx].name) > 0:
            return self.block.sections[idx].name.copy()
        return f"Section {idx + 1}".encode()
    if kind == 1:
        return b"sub-block " + self.block.sub_blocks[idx].name
    return b"Unsectioned"


func rail_nets(self: Builder) -> bytes[]:
    mut seen: set[str] = set()
    mut result: bytes[] = []
    for net in self.nets:
        mut name = label_of(self, net.name)
        if not compose.is_rail_net(name) or not draws_any_pin(self, net):
            continue
        mut key = strs.text(name)
        if key in seen:
            continue
        seen.add(key)
        result.append(name)
    return result


func project_sidecars(self: Builder) -> SchFile[]:
    mut rails = [for net in rail_nets(self) yield compose.rail_for(net)]
    mut side = project.sidecars(self.design, self.shapes, rails)
    return [for s in side yield SchFile(name=s.name.copy(), bytes=s.bytes.copy())]


func draws_any_pin(self: Builder, net: flat_netlist.FlatNet) -> bool:
    for pin in net.pins:
        if strs.text(pin.ref_des) in self.ref_inst:
            return True
    return False


func build_flat(err: Stream, mut self: Builder) -> Result[SchFile[], str]:
    mut all_ = [for i in range(len(self.instances)) yield i]
    mut root_uuid = emit.element_uuid(self.design, b"root", b"")
    mut flat_items = sheet_items(mut self, all_)
    mut req = compose.Request(sheet=emit.Sheet(design=self.design.copy(), title=b"", root_uuid=root_uuid.copy(), sheet_uuid=root_uuid.copy(), page_w=0, page_h=0, is_root=True), shapes=flat_items.shapes.copy(), items=flat_items.items.copy(), children=[], flag_nets=rail_nets(self), seq=self.seq, facts=net_facts(self))
    mut data = try render_sheet(err, mut self, req)
    try check_coverage(err, self, all_)
    return Ok([SchFile(name=self.design + b".kicad_sch", bytes=data)])


func build_hierarchy(err: Stream, mut self: Builder, sheets: SheetPlan[]) -> Result[SchFile[], str]:
    mut root_uuid = emit.element_uuid(self.design, b"root", b"")
    mut files = [SchFile(name=b"", bytes=b"")]
    mut children: emit.SheetRef[] = []
    for i in range(len(sheets)):
        mut s = sheets[i].copy()
        mut drawn = sheet_items(mut self, s.members)
        children.append(emit.SheetRef(name=s.title.copy(), file=s.file.copy(), uuid=s.uuid.copy(), page=i + 2, at=emit.Rect(x=0, y=0, w=0, h=0)))
        mut req = compose.Request(sheet=emit.Sheet(design=self.design.copy(), title=s.title.copy(), root_uuid=root_uuid.copy(), sheet_uuid=s.uuid.copy(), page_w=0, page_h=0, is_root=False), shapes=drawn.shapes.copy(), items=drawn.items.copy(), children=[], flag_nets=[], seq=self.seq, facts=net_facts(self))
        mut data = try render_sheet(err, mut self, req)
        files.append(SchFile(name=s.file.copy(), bytes=data))
    mut root_req = compose.Request(sheet=emit.Sheet(design=self.design.copy(), title=self.block.name.copy(), root_uuid=root_uuid.copy(), sheet_uuid=root_uuid.copy(), page_w=0, page_h=0, is_root=True), shapes=[], items=[], children=children, flag_nets=rail_nets(self), seq=self.seq, facts=compose.NetFacts())
    mut root = try render_sheet(err, mut self, root_req)
    files[0] = SchFile(name=self.design + b".kicad_sch", bytes=root)
    mut all_ = [for j in range(len(self.instances)) yield j]
    try check_coverage(err, self, all_)
    return Ok(files)


func render_sheet(err: Stream, mut self: Builder, req: compose.Request) -> Result[bytes, str]:
    mut request = req.copy()
    mut result = compose.compose(mut request)
    self.seq = request.seq
    mut data = emit.render(result.doc)
    mut report = try verify.check(data, result.expect)
    note_overlaps(err, mut self, req.sheet.title, report)
    return Ok(data)


func div_trunc(x: int, y: int) -> int:
    if x < 0:
        return -((-x) // y)
    return x // y


func kind_name(kind: textbox.Kind) -> bytes:
    if kind == textbox.Kind.caption:
        return b"caption"
    if kind == textbox.Kind.label:
        return b"label"
    if kind == textbox.Kind.field:
        return b"field"
    if kind == textbox.Kind.pin_name:
        return b"pin_name"
    return b"pin_number"


func note_overlaps(err: Stream, mut self: Builder, title: bytes, report: textbox.Report):
    self.overlaps += report.overlaps
    mut pair = report.first.copy()
    if pair is None:
        return
    mut label = title.copy()
    if len(label) == 0:
        label = b"root"
    mut message = b"export-kicad-sch: " + self.design + b": " + label
    message += f": {report.overlaps} overlapping text pairs of {report.texts} drawn texts".encode()
    message += b" (e.g. " + kind_name(pair.kind_a) + b" \"" + pair.a + b"\" over " + kind_name(pair.kind_b) + b" \"" + pair.b
    message += f"\" at {div_trunc(pair.x, 100)},{div_trunc(pair.y, 100)})".encode()
    log.progress(err, message)


func placeables(mut self: Builder, members: int[]) -> compose.Placeable[]:
    mut raw: compose.Placeable[] = []
    for m in members:
        units_of(mut self, m, mut raw)
    mut buckets: dict[int, compose.Placeable[]] = {}
    mut order: int[] = []
    for it in raw:
        if it.group not in buckets:
            buckets[it.group] = []
            order.append(it.group)
        buckets[it.group].append(it.copy())
    order.sort()
    mut result: compose.Placeable[] = []
    for g in order:
        cluster_group(self, buckets[g], mut result)
    return result


func sheet_items(mut self: Builder, members: int[]) -> SheetItems:
    mut items = placeables(mut self, members)
    mut shapes = subset_shapes(self, mut items)
    return SheetItems(items=items, shapes=shapes)


func subset_shapes(self: Builder, mut items: compose.Placeable[]) -> shape_mod.Shape[]:
    mut index: dict[int, int] = {}
    mut used: shape_mod.Shape[] = []
    for i in range(len(items)):
        mut it = items[i].copy()
        if it.shape not in index:
            index[it.shape] = len(used)
            used.append(self.shapes[it.shape].copy())
        it.shape = index[it.shape]
        items[i] = it
    return used


func cluster_group(self: Builder, group: compose.Placeable[], mut out: compose.Placeable[]):
    mut members = [for it in group yield member_of(self, it)]
    mut placement = plan.cluster(members)
    for k in range(len(placement.order)):
        mut i = placement.order[k]
        mut it = group[i].copy()
        it.cluster = placement.cluster[k]
        out.append(it)


func member_of(self: Builder, it: compose.Placeable) -> plan.Member:
    mut idx = self.ref_inst.get(strs.text(it.id.ref), 0)
    mut src: env_mod.Instance? = None
    if idx < len(self.src):
        src = Some(self.src[idx].copy())
    mut nets: bytes[] = []
    for n in it.nets:
        if len(n) == 0 or compose.is_rail_net(n):
            continue
        nets.append(n.copy())
    mut bound_ref = b""
    mut order = b""
    if src is not None:
        bound_ref = qualify(it.id.ref, src.bind.decouple.ic)
        order = src.bind.decouple.pin.copy()
    return plan.Member(hub=not plan.is_passive_ref(it.id.ref), ref=it.id.ref.copy(), bound_ref=bound_ref, order=order, nets=nets)


func units_of(mut self: Builder, idx: int, mut out: compose.Placeable[]):
    mut inst = self.instances[idx].copy()
    mut shape_idx = shape_of(self, idx)
    mut group = group_of(self, idx)
    mut caption = caption_for(mut self, group)
    mut id = identity_of(self, inst)
    mut units = self.shapes[shape_idx].units.copy()
    for ui in range(len(units)):
        mut u = units[ui].copy()
        mut nets = [for pin in u.pins yield net_of(self, inst.ref_des, pin.pad)]
        mut unit_id = id.copy()
        if ui > 0:
            unit_id.uuid = unit_uuid(self, inst.ref_des, u.number)
        out.append(compose.Placeable(id=unit_id, shape=shape_idx, unit=ui, group=group, caption=caption.copy(), nets=nets, cluster=0))


func identity_of(self: Builder, inst: flat_netlist.FlatInstance) -> emit.Identity:
    mut uuid = inst.uuid.copy()
    if len(uuid) == 0:
        uuid = emit.element_uuid(self.design, b"sym", inst.ref_des)
    return emit.Identity(ref=inst.ref_des.copy(), value=inst.value.copy(), footprint=footprint_field(self, inst), properties=inst.properties.copy(), uuid=uuid, dnp=inst.dnp)


func unit_uuid(self: Builder, ref: bytes, number: int) -> bytes:
    return emit.element_uuid(self.design, b"unit", ref + b":" + str(number).encode())


func net_of(self: Builder, ref: bytes, pad: bytes) -> bytes:
    return self.pin_net.get(pin_key(ref, pad), b"").copy()


func footprint_field(self: Builder, inst: flat_netlist.FlatInstance) -> bytes:
    if len(inst.footprint) == 0:
        return b""
    mut key = strs.text(inst.footprint)
    mut name = inst.footprint.copy()
    if key in self.fp:
        name = self.fp[key].kicad_name.copy()
    return b"footprints:" + name


func check_coverage(err: Stream, self: Builder, members: int[]) -> Result[Unit, str]:
    mut drawn: set[str] = set()
    for m in members:
        mut inst = self.instances[m].copy()
        for u in self.shapes[shape_of(self, m)].units:
            for pin in u.pins:
                drawn.add(pin_key(inst.ref_des, pin.pad))
    warn_orphan_pins(err, self)
    mut missing = first_undrawn(self.nets, self.ref_inst, drawn)
    if missing is not None:
        log.warn(err, b"export-kicad-sch: pin " + missing.ref_des + b"." + missing.pin + b" is on a net but has no symbol pin")
        return Err(err_pin_not_drawn)
    return Ok(())


func warn_orphan_pins(err: Stream, self: Builder):
    mut seen: set[str] = set()
    for net in self.nets:
        for pin in net.pins:
            mut key = strs.text(pin.ref_des)
            if key in self.ref_inst or key in seen:
                continue
            seen.add(key)
            log.warn(err, b"export-kicad-sch: net '" + net.name + b"' references '" + pin.ref_des + b"' which has no instance \xe2\x80\x94 pin not drawn")


# Private Zig helpers are public solely for their original sibling counterparts.
public func first_undrawn(nets: flat_netlist.FlatNet[], known: dict[str, int], drawn: set[str]) -> flat_netlist.FlatPin?:
    for net in nets:
        for pin in net.pins:
            if strs.text(pin.ref_des) not in known or pin_key(pin.ref_des, pin.pin) in drawn:
                continue
            return Some(pin.copy())
    return None


public func sheet_key(kind: SheetKind, index: int) -> int:
    mut high = 2
    if kind == SheetKind.section:
        high = 0
    elif kind == SheetKind.module_:
        high = 1
    return high * 4294967296 + index


public func pin_key(ref: bytes, pad: bytes) -> str:
    return strs.text(ref + b"\x00" + pad)


func base_name(inst: flat_netlist.FlatInstance) -> bytes:
    if len(inst.component) > 0:
        return inst.component.copy()
    if len(inst.symbol) > 0:
        return inst.symbol.copy()
    return b"unnamed-part"


func net_touches(net: flat_netlist.FlatNet, ref: bytes) -> bool:
    for pin in net.pins:
        if pin.ref_des == ref:
            return True
    return False


public func qualify(ref: bytes, local: bytes) -> bytes:
    if len(local) == 0:
        return b""
    mut path = net_name.parent(ref)
    if path is None:
        return local.copy()
    return path + b"/" + local


func walk_tree(block: env_mod.DesignBlock, top: int?, mut owners: int?[], mut src: env_mod.Instance[]):
    for inst in block.instances:
        owners.append(top)
        src.append(inst.copy())
    for i in range(len(block.sub_blocks)):
        mut sb = block.sub_blocks[i].copy()
        mut next_top = top.copy()
        if next_top is None:
            next_top = Some(i)
        walk_tree(sb.block, next_top, mut owners, mut src)

import eval_env as env_mod
import eval_net_analysis as na
import support_strs as strs
import support_sha256 as sha256
import uuid

# Neutral flattened-netlist currency used by export and placement layers.
# Ref-des, net names, and references inside placement bindings are prefixed
# together; a pad number alone never identifies the part that owns it.
public record FlatInstance:
    ref_des: bytes
    component: bytes
    symbol: bytes
    pinout: bytes
    origin_key: bytes
    value: bytes
    footprint: bytes
    properties: env_mod.Property[]
    uuid: bytes
    variants: env_mod.InstanceVariants
    bind: env_mod.InstanceBinds
    distance_rules: env_mod.DistanceRule[]
    dnp: bool = False


public record FlatNet:
    name: bytes
    pins: FlatPin[]


public record FlatPin:
    ref_des: bytes
    pin: bytes


public record FlatTie:
    a: bytes
    b: bytes


# CanonicalNetMap is dict[str, bytes]: decoded keys and byte-exact names.
public func uuid_from_id(id: bytes) -> bytes:
    mut hash = sha256.sha256(b"canopy:" + id)
    return uuid.format(hash[:16], uuid.Version.name_v5)


func prefixed(prefix: bytes, name: bytes) -> bytes:
    if len(prefix) == 0:
        return name.copy()
    return prefix + b"/" + name


# A binding that names nothing must never become the bare sub-block prefix.
func prefixed_or_empty(prefix: bytes, name: bytes) -> bytes:
    if len(name) == 0:
        return b""
    return prefixed(prefix, name)


# Every candidate is a sibling in the naming part's own block.
func prefixed_distance_rules(prefix: bytes, rules: env_mod.DistanceRule[]) -> env_mod.DistanceRule[]:
    if len(rules) == 0 or len(prefix) == 0:
        return rules.copy()
    mut result: env_mod.DistanceRule[] = []
    for rule in rules:
        mut refs: bytes[] = []
        for ref in rule.candidates:
            refs.append(prefixed(prefix, ref))
        mut slot = rule.copy()
        slot.candidates = refs
        result.append(slot)
    return result


public func flat_instance_default(ref_des: bytes, component: bytes, value: bytes, footprint: bytes, properties: env_mod.Property[], uuid_: bytes) -> FlatInstance:
    return FlatInstance(ref_des=ref_des.copy(), component=component.copy(), value=value.copy(), footprint=footprint.copy(), properties=properties.copy(), uuid=uuid_.copy(), symbol=b"", pinout=b"", origin_key=b"", variants=env_mod.InstanceVariants(rules=[], base_value=b""), bind=env_mod.InstanceBinds(decouple=env_mod.DecoupleBind(ic=b"", pin=b""), near=env_mod.NearBind(ref=b"", pin=b"", own=b"")), distance_rules=[])


# BOM-assigned identity wins; otherwise derive it from the stable source id.
public func collect_instances(block: env_mod.DesignBlock, prefix: bytes, mut list_: FlatInstance[]):
    for inst in block.instances:
        mut ref = prefixed(prefix, inst.ref_des)
        mut effective_uuid = b""
        if len(inst.uuid) > 0:
            effective_uuid = inst.uuid.copy()
        elif len(inst.id) > 0:
            effective_uuid = uuid_from_id(inst.id)
        list_.append(FlatInstance(ref_des=ref, component=inst.component.copy(), symbol=inst.symbol.copy(), pinout=inst.pinout.copy(), origin_key=inst.origin_key.copy(), value=inst.value.copy(), footprint=inst.footprint.copy(), properties=inst.properties.copy(), uuid=effective_uuid, dnp=inst.dnp, variants=inst.variants.copy(), bind=env_mod.InstanceBinds(decouple=env_mod.DecoupleBind(pin=inst.bind.decouple.pin.copy(), ic=prefixed_or_empty(prefix, inst.bind.decouple.ic), rail=inst.bind.decouple.rail), near=env_mod.NearBind(ref=prefixed_or_empty(prefix, inst.bind.near.ref), pin=inst.bind.near.pin.copy(), own=inst.bind.near.own.copy())), distance_rules=prefixed_distance_rules(prefix, inst.distance_rules)))
    for sb in block.sub_blocks:
        mut sub_prefix = prefixed(prefix, sb.name)
        collect_instances(sb.block, sub_prefix, mut list_)


public func collect_nets(block: env_mod.DesignBlock, prefix: bytes, mut list_: FlatNet[]):
    for net in block.nets:
        mut net_name = prefixed(prefix, net.name)
        mut pins: FlatPin[] = []
        for pin in net.pins:
            pins.append(FlatPin(ref_des=prefixed(prefix, pin.ref_des), pin=pin.pin.copy()))
        list_.append(FlatNet(name=net_name, pins=pins))
    for sb in block.sub_blocks:
        mut sub_prefix = prefixed(prefix, sb.name)
        collect_nets(sb.block, sub_prefix, mut list_)


public func collect_net_ties(block: env_mod.DesignBlock, prefix: bytes, mut list_: FlatTie[]):
    for tie in block.net_ties:
        list_.append(FlatTie(a=prefixed(prefix, tie.a), b=prefixed(prefix, tie.b)))
    for sb in block.sub_blocks:
        mut sub_prefix = prefixed(prefix, sb.name)
        collect_net_ties(sb.block, sub_prefix, mut list_)


# Prefer topmost (fewest slashes), then shortest, then lexicographic.
func prefer_name(candidate: bytes, incumbent: bytes) -> bool:
    mut cs = candidate.count(b"/")
    mut incumbent_slashes = incumbent.count(b"/")
    if cs != incumbent_slashes:
        return cs < incumbent_slashes
    if len(candidate) != len(incumbent):
        return len(candidate) < len(incumbent)
    return strs.bytes_less(candidate, incumbent)


record NetTieSets:
    index: dict[str, int]
    names: bytes[]
    parent: int[]


func net_tie_sets_get_or_add(mut self: NetTieSets, name: bytes) -> int:
    mut key = strs.text(name)
    if key in self.index:
        return self.index[key]
    mut i = len(self.names)
    self.names.append(name.copy())
    self.parent.append(i)
    self.index[key] = i
    return i


func net_tie_sets_find(mut self: NetTieSets, idx: int) -> int:
    mut i = idx
    while self.parent[i] != i:
        i = self.parent[i]
    mut j = idx
    while self.parent[j] != i:
        mut next_ = self.parent[j]
        self.parent[j] = i
        j = next_
    return i


func write_canonical_aliases(mut out: dict[str, bytes], mut sets: NetTieSets, canonical: dict[int, int], nets: FlatNet[], per_pin: dict[str, bytes]):
    mut i = 0
    while i < len(sets.names):
        mut name = sets.names[i].copy()
        mut root = net_tie_sets_find(mut sets, i)
        if root in canonical:
            out[strs.text(name)] = sets.names[canonical[root]].copy()
        i += 1
    for net in nets:
        mut key = strs.text(net.name)
        if key in per_pin:
            out[key] = per_pin[key].copy()


# Merge electrical aliases while keeping per-pin micro-nets separate and
# renaming their base: buck/VIN.U12.VIN_1 follows buck/VIN -> VBATT.
public func apply_net_ties(mut nets: FlatNet[], ties: FlatTie[]):
    mut aliases: dict[str, bytes] = {}
    apply_net_ties_mapped(mut nets, ties, mut aliases)


# A supplied map receives unchanged names too. Plain wrappers discard a local
# map instead of passing Zig's optional pointer (value-semantics adaptation).
public func apply_net_ties_mapped(mut nets: FlatNet[], ties: FlatTie[], mut aliases: dict[str, bytes]):
    if len(ties) == 0 and len(nets) == 0:
        return
    mut sets = NetTieSets(index={}, names=[], parent=[])
    # All listed nets and the LHS of each tie are eligible preferred names.
    # RHS-only names from pin-function aliases ("1", "5") must not hijack them.
    mut live_names: set[str] = set()
    for net in nets:
        _ = net_tie_sets_get_or_add(mut sets, net.name)
        live_names.add(strs.text(net.name))
    for tie in ties:
        mut ai = net_tie_sets_get_or_add(mut sets, tie.a)
        mut bi = net_tie_sets_get_or_add(mut sets, tie.b)
        live_names.add(strs.text(tie.a))
        mut ra = net_tie_sets_find(mut sets, ai)
        mut rb = net_tie_sets_find(mut sets, bi)
        if ra != rb:
            sets.parent[rb] = ra
    # Canonical live name per root.
    mut canonical: dict[int, int] = {}
    mut i = 0
    while i < len(sets.names):
        mut nm = sets.names[i].copy()
        if strs.text(nm) in live_names:
            mut root = net_tie_sets_find(mut sets, i)
            if root in canonical:
                mut best_i = canonical[root]
                if prefer_name(nm, sets.names[best_i]):
                    canonical[root] = i
            else:
                canonical[root] = i
        i += 1
    # Only differing names are in the rename map; skip roots with no live name.
    mut rename_map: dict[str, bytes] = {}
    mut j = 0
    while j < len(sets.names):
        mut nm2 = sets.names[j].copy()
        mut root2 = net_tie_sets_find(mut sets, j)
        if root2 in canonical:
            mut canon_name = sets.names[canonical[root2]].copy()
            if nm2 != canon_name:
                rename_map[strs.text(nm2)] = canon_name
        j += 1
    mut per_pin_renames: dict[str, bytes] = {}
    for net2 in nets:
        mut base = na.base_net_name(net2.name)
        if len(base) == len(net2.name):
            continue
        mut suffix = net2.name[len(base):]
        mut base_key = strs.text(base)
        if base_key not in rename_map:
            continue
        per_pin_renames[strs.text(net2.name)] = rename_map[base_key] + suffix
    write_canonical_aliases(mut aliases, mut sets, canonical, nets, per_pin_renames)
    # Ordered-map rebuilding retains first-seen net order and all pin order.
    mut merged: dict[str, FlatPin[]] = {}
    for net3 in nets:
        mut key3 = strs.text(net3.name)
        mut canon = net3.name.copy()
        if key3 in per_pin_renames:
            canon = per_pin_renames[key3].copy()
        elif key3 in rename_map:
            canon = rename_map[key3].copy()
        mut canon_key = strs.text(canon)
        if canon_key not in merged:
            merged[canon_key.copy()] = []
        for p in net3.pins:
            merged[canon_key].append(p.copy())
    nets.clear()
    for name3 in merged:
        nets.append(FlatNet(name=name3.encode(), pins=merged[name3].copy()))


public func flatten_and_merge_nets(block: env_mod.DesignBlock, mut nets: FlatNet[]):
    mut aliases: dict[str, bytes] = {}
    flatten_and_merge_nets_mapped(block, mut nets, mut aliases)


public func flatten_and_merge_nets_mapped(block: env_mod.DesignBlock, mut nets: FlatNet[], mut aliases: dict[str, bytes]):
    collect_nets(block, b"", mut nets)
    mut ties: FlatTie[] = []
    collect_net_ties(block, b"", mut ties)
    apply_net_ties_mapped(mut nets, ties, mut aliases)

import flat_netlist as m
import support_expect as ex

# test "uuidFromId pins the identity KiCad sync keys on"
public func test_uuidfromid_pins_the_identity_kicad_sync_keys_on(out: Stream) -> bool:
    # Frozen identity: digest prefix and text spelling must never drift.
    return ex.eq_bytes(out, "stable identity", m.uuid_from_id(b"aa000001"), b"11d1e8b6-ab30-561d-9ee4-8da03a84febb")


# test "flatten currency types default their optional fields"
public func test_flatten_currency_types_default_their_optional_fields(out: Stream) -> bool:
    mut pin = m.FlatPin(ref_des=b"U1", pin=b"3")
    if not ex.eq_bytes(out, "pin ref", pin.ref_des, b"U1"):
        return False
    if not ex.eq_bytes(out, "pin id", pin.pin, b"3"):
        return False
    mut net = m.FlatNet(name=b"VDD", pins=[pin])
    if not ex.eq_int(out, "net pins", len(net.pins), 1):
        return False
    # The constructor explicitly supplies aggregate defaults prohibited as
    # record defaults in mylang; it preserves all documented literal defaults.
    mut inst = m.flat_instance_default(b"C1", b"cap-0402", b"100nF", b"c-0402", [], b"")
    if not ex.eq_bytes(out, "symbol", inst.symbol, b""):
        return False
    if not ex.eq_bytes(out, "pinout", inst.pinout, b""):
        return False
    if not ex.eq_bytes(out, "origin", inst.origin_key, b""):
        return False
    if not ex.ok(out, "dnp", not inst.dnp):
        return False
    if not ex.eq_bytes(out, "decouple pin", inst.bind.decouple.pin, b""):
        return False
    if not ex.eq_bytes(out, "decouple ic", inst.bind.decouple.ic, b""):
        return False
    if not ex.ok(out, "rail", not inst.bind.decouple.rail):
        return False
    if not ex.eq_bytes(out, "near ref", inst.bind.near.ref, b""):
        return False
    if not ex.eq_bytes(out, "near pin", inst.bind.near.pin, b""):
        return False
    return ex.eq_bytes(out, "near own", inst.bind.near.own, b"")

import byte_builder
import sexpr_ast as ast
import math
import support_float_fmt as ff

public record Aperture:
    x: float
    y: float
    w: float
    h: float


public const err_invalid_paste: str = "InvalidPaste"


public func parse(pad: ast.Node) -> Result[Aperture[]?, str]:
    mut items = ast.as_list(pad)
    if items is None:
        return Ok(None)
    for item in items:
        if not ast.is_form(item, b"paste"):
            continue
        mut forms = ast.as_list(item)
        if forms is None:
            return Err(err_invalid_paste)
        if len(forms) > 257:
            return Err(err_invalid_paste)
        mut windows: Aperture[] = []
        for form in forms[1:len(forms)]:
            if not ast.is_form(form, b"rect"):
                return Err(err_invalid_paste)
            mut v = ast.as_list(form)
            if v is None:
                return Err(err_invalid_paste)
            if len(v) != 5:
                return Err(err_invalid_paste)
            mut x = ast.as_number(v[1])
            mut y = ast.as_number(v[2])
            mut w_ = ast.as_number(v[3])
            mut h = ast.as_number(v[4])
            if x is None or y is None or w_ is None or h is None:
                return Err(err_invalid_paste)
            mut rect = Aperture(x=x, y=y, w=w_, h=h)
            for n in [rect.x, rect.y, rect.w, rect.h]:
                if not math.is_finite(n) or abs(n) > 1000.0:
                    return Err(err_invalid_paste)
            if rect.w <= 0.0 or rect.h <= 0.0:
                return Err(err_invalid_paste)
            windows.append(rect)
        return Ok(Some(windows))
    return Ok(None)


public func write(mut w: byte_builder.Builder, windows: Aperture[]):
    byte_builder.append(mut w, b" (paste")
    for v in windows:
        byte_builder.append_text(mut w, " (rect " + ff.fmt_float_prec(v.x, 6) + " " + ff.fmt_float_prec(v.y, 6) + " " + ff.fmt_float_prec(v.w, 6) + " " + ff.fmt_float_prec(v.h, 6) + ")")
    _ = byte_builder.append_byte(mut w, 41)


public func valid(windows: Aperture[], width: float, height: float) -> bool:
    if len(windows) > 256:
        return False
    mut i = 0
    for v in windows:
        for n in [v.x, v.y, v.w, v.h]:
            if not math.is_finite(n) or abs(n) > 1000.0:
                return False
        if v.w <= 0.0 or v.h <= 0.0:
            return False
        if abs(v.x) + v.w / 2.0 > width / 2.0 + 1e-8 or abs(v.y) + v.h / 2.0 > height / 2.0 + 1e-8:
            return False
        for q in windows[0:i]:
            if abs(v.x - q.x) < (v.w + q.w) / 2.0 - 1e-8 and abs(v.y - q.y) < (v.h + q.h) / 2.0 - 1e-8:
                return False
        i += 1
    return True

import support_sha256 as sha
import byte_builder

# D4: Filesystem has whole-file byte I/O, directory listing and creation,
# but no stat/entry kinds, thread-local state, locks, symlink queries or atomic
# rename. The slice's used API is expressed directly below. ReadTrace and
# CacheProbe are caller-owned values, with single-threaded test counterparts.
# SecureWalker, Mutex/Condition and atomic ABA guarantees have no host support.
public record ReadTrace:
    reads: dict[str, bytes]
    states: dict[str, bool]
    directories: dict[str, str[]]
    active: bool = False
    consistent: bool = True


public record CacheProbe:
    active: bool = False
    hidden_active: bool = False


public func make_path(fs: Filesystem, path: str) -> Result[Unit, str]:
    mut prefix = ""
    for part in path.split("/"):
        if len(part) == 0:
            prefix = prefix + "/"
            continue
        if len(prefix) > 0 and prefix[len(prefix) - 1] != "/":
            prefix = prefix + "/"
        prefix = prefix + part
        if not fs.exists(prefix):
            try fs.mkdir(prefix)
    return Ok(())


public func read_file_alloc(fs: Filesystem, path: str, max_: int) -> Result[bytes, str]:
    mut data = try fs.read_file(path)
    if len(data) > max_:
        return Err("FileTooBig")
    return Ok(data)


public func access(fs: Filesystem, path: str) -> Result[Unit, str]:
    if not fs.exists(path):
        return Err("FileNotFound")
    return Ok(())


public func list_dir(fs: Filesystem, path: str) -> Result[str[], str]:
    mut names = try fs.listdir(path)
    names.sort()
    return Ok(names)


public func write_file(fs: Filesystem, path: str, data: bytes) -> Result[Unit, str]:
    return fs.write_file(path, data)


public func copy_file(fs: Filesystem, source: str, dest: str) -> Result[Unit, str]:
    mut data = try fs.read_file(source)
    return fs.write_file(dest, data)


public func read_trace_init() -> ReadTrace:
    return ReadTrace(reads={}, states={}, directories={})


public func read_trace_begin(mut self: ReadTrace):
    if self.active:
        self.consistent = False
        return
    self.active = True


# D9: no ambient trace pointer. A nested scope explicitly names its parent;
# invalidate both scopes while retaining the outer one's ownership of reads.
public func read_trace_begin_nested(mut parent: ReadTrace, mut child: ReadTrace):
    if parent.active or child.active:
        parent.consistent = False
        child.consistent = False
        return
    child.active = True


public func read_trace_end(mut self: ReadTrace):
    self.active = False


# D4: the single-threaded capability model uses an explicit ownership check
# in place of Thread.Id. This tests the same refusal/retained-scope invariant.
public func read_trace_end_with_owner(mut self: ReadTrace, owns_scope: bool):
    if not owns_scope:
        self.consistent = False
        return
    read_trace_end(mut self)


public func has_active_read_trace(trace: ReadTrace) -> bool:
    return trace.active


# private in Zig; public for the split-file digest and retained-size tests.
public func read_trace_record(mut self: ReadTrace, path: str, data: bytes):
    if path in self.states and not self.states[path]:
        self.consistent = False
    if path in self.reads:
        if self.reads[path] != data:
            self.consistent = False
        return
    self.reads[path.copy()] = data.copy()
    self.states[path.copy()] = True


public func read_trace_retained_bytes(self: ReadTrace) -> int:
    mut total = 0
    for path in self.reads:
        total += len(path.encode()) + len(self.reads[path]) + 64
    for path2 in self.states:
        total += len(path2.encode()) + 32
    for path3 in self.directories:
        total += len(path3.encode()) + 32
        for member in self.directories[path3]:
            total += len(member.encode()) + 32
    return total


func record_state(mut self: ReadTrace, path: str, present: bool):
    if path in self.states:
        if self.states[path] != present:
            self.consistent = False
        return
    self.states[path.copy()] = present


public func read_file_alloc_traced(fs: Filesystem, mut trace: ReadTrace, path: str, max_: int) -> Result[bytes, str]:
    match read_file_alloc(fs, path, max_):
        case Ok(data):
            if trace.active:
                read_trace_record(mut trace, path, data)
            return Ok(data)
        case Err(e):
            if trace.active:
                if not fs.exists(path):
                    record_state(mut trace, path, False)
                else:
                    trace.consistent = False
            return Err(e)


public func access_traced(fs: Filesystem, mut trace: ReadTrace, path: str) -> Result[Unit, str]:
    mut present = fs.exists(path)
    if trace.active:
        record_state(mut trace, path, present)
    if not present:
        return Err("FileNotFound")
    return Ok(())


public func list_dir_traced(fs: Filesystem, mut trace: ReadTrace, path: str) -> Result[str[], str]:
    mut names = try list_dir(fs, path)
    if trace.active:
        if path in trace.directories and trace.directories[path] != names:
            trace.consistent = False
        else:
            trace.directories[path.copy()] = names.copy()
    return Ok(names)


public func read_trace_verify(fs: Filesystem, self: ReadTrace) -> bool:
    if not self.consistent:
        return False
    for path in self.states:
        if fs.exists(path) != self.states[path]:
            return False
    for path2 in self.reads:
        match fs.read_file(path2):
            case Err(_):
                return False
            case Ok(data):
                if data != self.reads[path2]:
                    return False
    for path3 in self.directories:
        match list_dir(fs, path3):
            case Err(_):
                return False
            case Ok(names):
                if names != self.directories[path3]:
                    return False
    return True


# Canonical path order is independent of insertion/read order. Each bytes
# entry uses the same u64-little path length, path, state name, SHA256 shape.
public func read_trace_digest(self: ReadTrace) -> bytes:
    mut w = byte_builder.create()
    mut paths = list(self.states.keys())
    paths.sort()
    for path in paths:
        mut data = path.encode()
        append_length(mut w, len(data))
        byte_builder.append(mut w, data)
        if path in self.reads:
            byte_builder.append(mut w, b"bytes")
            byte_builder.append(mut w, sha.sha256(self.reads[path]))
        else:
            if self.states[path]:
                byte_builder.append(mut w, b"exists")
            else:
                byte_builder.append(mut w, b"absent")
            for i in range(32):
                _ = byte_builder.append_byte(mut w, 0)
    mut directories = list(self.directories.keys())
    directories.sort()
    for path2 in directories:
        byte_builder.append(mut w, b"directory")
        byte_builder.append_text(mut w, path2)
        for member in self.directories[path2]:
            byte_builder.append_text(mut w, member)
            # Entry kinds are unavailable under D4; only names are retained.
    return sha.sha256(byte_builder.finish(w)).hex().encode()


public func read_trace_digest_for_path(self: ReadTrace, path: str) -> bytes?:
    if path not in self.reads:
        return None
    return Some(sha.sha256(self.reads[path]).hex().encode())


public func read_trace_closure_digest(self: ReadTrace, paths: str[]) -> bytes:
    mut selected = read_trace_init()
    for path in paths:
        if path in self.reads:
            read_trace_record(mut selected, path, self.reads[path])
    return read_trace_digest(selected)


func append_length(mut w: byte_builder.Builder, value: int):
    mut n = value
    for i in range(8):
        _ = byte_builder.append_byte(mut w, n % 256)
        n = n // 256


public func begin_cache_probe(mut trace: ReadTrace) -> CacheProbe:
    mut probe = CacheProbe(active=True, hidden_active=trace.active)
    trace.active = False
    return probe


public func cache_probe_end(mut self: CacheProbe, mut trace: ReadTrace):
    if not self.active:
        return
    if trace.active:
        trace.consistent = False
    trace.active = self.hidden_active
    self.active = False


public func cache_probe_end_with_owner(mut self: CacheProbe, mut trace: ReadTrace, owns_scope: bool):
    if not owns_scope:
        trace.consistent = False
        return
    cache_probe_end(mut self, mut trace)

public func progress(err: Stream, msg: bytes):
    emit_line(err, b"[I] " + msg + b"\n")


public func warn(err: Stream, msg: bytes):
    emit_line(err, b"[W] " + msg + b"\n")


public func emit_line(err: Stream, msg: bytes):
    if len(msg) <= 4096:
        _ = err.write(msg)
    else:
        _ = err.write(msg[0:4092] + b"\xe2\x80\xa6\n")

import byte_builder
import support_strs as strs

public func write_escaped(mut w: byte_builder.Builder, s: bytes):
    for c in s:
        if c == 34:
            byte_builder.append(mut w, b"\\\"")
        elif c == 92:
            byte_builder.append(mut w, b"\\\\")
        elif c == 10:
            byte_builder.append(mut w, b"\\n")
        elif c == 13:
            byte_builder.append(mut w, b"\\r")
        elif c == 9:
            byte_builder.append(mut w, b"\\t")
        elif c < 32:
            byte_builder.append_text(mut w, "\\u" + strs.hex_pad(c, 4))
        else:
            _ = byte_builder.append_byte(mut w, c)


public func write_string(mut w: byte_builder.Builder, s: bytes):
    _ = byte_builder.append_byte(mut w, 34)
    write_escaped(mut w, s)
    _ = byte_builder.append_byte(mut w, 34)


public func write_script_string(mut w: byte_builder.Builder, s: bytes):
    _ = byte_builder.append_byte(mut w, 34)
    mut i = 0
    while i < len(s):
        mut c = s[i]
        if c == 60:
            byte_builder.append(mut w, b"\\u003c")
        elif c == 226 and i + 2 < len(s) and s[i + 1] == 128 and (s[i + 2] == 168 or s[i + 2] == 169):
            if s[i + 2] == 168:
                byte_builder.append(mut w, b"\\u2028")
            else:
                byte_builder.append(mut w, b"\\u2029")
            i += 2
        else:
            write_escaped(mut w, s[i:i + 1])
        i += 1
    _ = byte_builder.append_byte(mut w, 34)


public func write_string_oom(mut w: byte_builder.Builder, value: bytes):
    write_string(mut w, value)


public func write_field(mut w: byte_builder.Builder, key: bytes, value: bytes):
    _ = byte_builder.append_byte(mut w, 34)
    byte_builder.append(mut w, key)
    byte_builder.append(mut w, b"\":")
    write_string(mut w, value)

