    return ex.ok(out, "non-stubs preserved", "3.3V_SENSE" not in map_ and "V1P8.U10.7" not in map_ and "V08CAP.U10.16" not in map_ and "V1P8" not in map_)


# test "kicad-sch: split reads the last two dots and rejects a name without both"
public func test_kicad_sch_split_reads_the_last_two_dots_and_rejects_a_name_without_both(out: Stream) -> bool:
    mut s = m.split(b"buck/VIN.U12.VIN_1")
    if s is None:
        return ex.ok(out, "stub split", False)
    if not ex.eq_bytes(out, "base", s.base, b"buck/VIN") or not ex.eq_bytes(out, "ref", s.ref, b"U12") or not ex.eq_bytes(out, "pad", s.pad, b"VIN_1"):
        return False
    mut dotted = m.split(b"3.3V.U1.5")
    if dotted is None:
        return ex.ok(out, "dotted rail", False)
    if not ex.eq_bytes(out, "dotted base", dotted.base, b"3.3V"):
        return False
    for bad in [b"3.3V_SENSE", b"VDD3V3", b"VDD..5", b".U1.5", b"VDD.U1."]:
        if not ex.ok(out, "reject malformed name", m.split(bad).is_none()):
            return False
    return True

import sexpr_ast as ast
import numeric
import math
import support_sort as srt
import support_parse as parse_mod
import support_strs as strs

public record Box:
    x0: int
    y0: int
    x1: int
    y1: int


public enum Kind:
    caption
    label
    field
    pin_name
    pin_number


public record Item:
    box: Box
    kind: Kind
    text: bytes


public record Pair:
    a: bytes
    b: bytes
    kind_a: Kind
    kind_b: Kind
    x: int = 0
    y: int = 0


public record Report:
    texts: int = 0
    overlaps: int = 0
    first: Pair? = None


# Extents are an approximation, never a structural export failure. A character
# advances one font size; global labels start 9/8 sizes beyond their anchor.
public func scan(root: ast.Node) -> Report:
    mut items: Item[] = []
    mut libs: LibSymbol[] = []
    mut cl = ast.as_list(root)
    if cl is None:
        return Report()
    for child in cl[1:len(cl)]:
        if ast.is_form(child, b"lib_symbols"):
            read_lib_symbols(child, mut libs)
    for child2 in cl[1:len(cl)]:
        read_top(child2, libs, mut items)
    return overlaps_of(items)


# private in Zig; split-file tests exercise the same box calculation.
public enum Just:
    start
    middle
    end


public enum Cross:
    center
    above
    below


public record Placement:
    x: int
    y: int
    dir: int
    w: int
    h: int
    just: Just
    cross: Cross
    lead: int = 0


record Span:
    u0: int
    u1: int
    v0: int
    v1: int


public func box_of(p: Placement) -> Box:
    mut u0 = p.lead
    if p.just == Just.middle:
        u0 = -divtrunc(p.w, 2)
    elif p.just == Just.end:
        u0 = -p.lead - p.w
    mut v0 = 0
    if p.cross == Cross.center:
        v0 = -divtrunc(p.h, 2)
    elif p.cross == Cross.above:
        v0 = -p.h - number_gap(p.h)
    mut span = Span(u0=u0, u1=u0 + p.w, v0=v0, v1=v0 + p.h)
    # Opposite reading directions mirror along the advance axis.
    if p.dir == 180 or p.dir == 270:
        mut start = span.u0
        span.u0 = -span.u1
        span.u1 = -start
    if p.dir == 90 or p.dir == 270:
        return Box(x0=p.x + span.v0, y0=p.y - span.u1, x1=p.x + span.v1, y1=p.y - span.u0)
    return Box(x0=p.x + span.u0, y0=p.y + span.v0, x1=p.x + span.u1, y1=p.y + span.v1)


func number_gap(h: int) -> int:
    return divtrunc(h, 5)


func label_lead(h: int) -> int:
    return divtrunc(h * 9, 8)


# UTF-8 code points, not byte count: an em dash advances one character.
func advance(text: bytes, size: int) -> int:
    mut chars = 0
    for c in text:
        if bit_and(c, 192) != 128:
            chars += 1
    return chars * size


func overlaps_of(items: Item[]) -> Report:
    mut ordered = items.copy()
    srt.sort_by(mut ordered, left_of)
    mut out = Report(texts=len(ordered))
    mut i = 0
    for a in ordered:
        for b in ordered[i + 1:len(ordered)]:
            if b.box.x0 >= a.box.x1 - 10:
                break
            if not hits(a.box, b.box):
                continue
            out.overlaps += 1
            if out.first.is_none():
                out.first = Some(Pair(a=a.text.copy(), b=b.text.copy(), kind_a=a.kind, kind_b=b.kind, x=max(a.box.x0, b.box.x0), y=max(a.box.y0, b.box.y0)))
        i += 1
    return out


func left_of(a: Item, b: Item) -> bool:
    if a.box.x0 != b.box.x0:
        return a.box.x0 < b.box.x0
    return a.box.y0 < b.box.y0


func hits(a: Box, b: Box) -> bool:
    if min(a.x1, b.x1) - max(a.x0, b.x0) <= 10:
        return False
    return min(a.y1, b.y1) - max(a.y0, b.y0) > 10


record LibPin:
    unit: int
    x: int
    y: int
    angle: int
    len: int
    name: bytes
    name_size: int
    number: bytes
    number_size: int


record LibSymbol:
    name: bytes
    pins: LibPin[]
    show_names: bool = True
    show_numbers: bool = True
    name_offset: int = 0


func libraries_find(self: LibSymbol[], id_: bytes) -> LibSymbol?:
    for entry in self:
        if entry.name == id_:
            return Some(entry.copy())
    return None


func read_lib_symbols(node: ast.Node, mut libs: LibSymbol[]):
    mut cl = ast.as_list(node)
    if cl is None:
        return
    for sym in cl[1:len(cl)]:
        if not ast.is_form(sym, b"symbol"):
            continue
        mut sl = ast.as_list(sym)
        if sl is None:
            continue
        if len(sl) < 2:
            continue
        mut name = ast.as_text(sl[1])
        if name is None:
            continue
        mut entry = LibSymbol(name=name.copy(), pins=[])
        read_pin_policy(sym, mut entry)
        for sub in sl[2:len(sl)]:
            read_lib_unit(sub, mut entry)
        libs.append(entry)


func read_pin_policy(sym: ast.Node, mut entry: LibSymbol):
    mut cl = ast.as_list(sym)
    if cl is None:
        return
    for child in cl[1:len(cl)]:
        if ast.is_form(child, b"pin_numbers"):
            entry.show_numbers = not hidden(child)
        if not ast.is_form(child, b"pin_names"):
            continue
        entry.show_names = not hidden(child)
        entry.name_offset = number_child(child, b"offset").unwrap_or(0)


func read_lib_unit(sub: ast.Node, mut entry: LibSymbol):
    if not ast.is_form(sub, b"symbol"):
        return
    mut l = ast.as_list(sub)
    if l is None:
        return
    if len(l) < 2:
        return
    mut unit = sub_unit(ast.as_text(l[1]).unwrap_or(b""))
    if unit is None:
        return
    for item in l[2:len(l)]:
        if not ast.is_form(item, b"pin"):
            continue
        mut pin = read_lib_pin(item, unit)
        if pin is not None:
            entry.pins.append(pin.copy())


func read_lib_pin(item: ast.Node, unit: int) -> LibPin?:
    mut at = try at_form(item)
    mut name = named_text(item, b"name")
    mut number = named_text(item, b"number")
    mut x = try coord(at[1])
    mut y = try coord(at[2])
    return Some(LibPin(unit=unit, x=x, y=y, angle=angle_at(at), len=number_child(item, b"length").unwrap_or(0), name=name.text.copy(), name_size=name.size, number=number.text.copy(), number_size=number.size))


record NamedText:
    text: bytes
    size: int = 0


func named_text(item: ast.Node, form: bytes) -> NamedText:
    mut cl = ast.as_list(item)
    if cl is None:
        return NamedText(text=b"")
    for child in cl[1:len(cl)]:
        if not ast.is_form(child, form):
            continue
        mut l = ast.as_list(child)
        if l is None:
            continue
        if len(l) < 2:
            continue
        return NamedText(text=ast.as_text(l[1]).unwrap_or(b"").copy(), size=font_size(child))
    return NamedText(text=b"")


func font_size(node: ast.Node) -> int:
    mut cl = ast.as_list(node)
    if cl is None:
        return 0
    for child in cl[1:len(cl)]:
        if not ast.is_form(child, b"effects"):
            continue
        if hidden(child):
            return 0
        mut el = ast.as_list(child)
        if el is None:
            continue
        for f in el[1:len(el)]:
            if ast.is_form(f, b"font"):
                return number_child(f, b"size").unwrap_or(0)
    return 0


func read_top(node: ast.Node, libs: LibSymbol[], mut items: Item[]):
    if ast.is_form(node, b"text"):
        append_caption(node, mut items)
    elif ast.is_form(node, b"global_label"):
        append_label(node, mut items)
    elif ast.is_form(node, b"symbol"):
        append_symbol(node, libs, mut items)


func append_caption(node: ast.Node, mut items: Item[]):
    mut cl = ast.as_list(node)
    if cl is None:
        return
    if len(cl) < 2:
        return
    mut text = ast.as_text(cl[1])
    mut at = at_form(node)
    if text is None or at is None:
        return
    mut size = font_size(node)
    mut x = coord(at[1])
    mut y = coord(at[2])
    if size == 0 or x is None or y is None:
        return
    mut p = Placement(x=x, y=y, dir=angle_at(at), w=advance(text, size), h=size, just=Just.start, cross=Cross.above)
    items.append(Item(kind=Kind.caption, text=text.copy(), box=box_of(p)))


func append_label(node: ast.Node, mut items: Item[]):
    mut cl = ast.as_list(node)
    if cl is None:
        return
    if len(cl) < 2:
        return
    mut text = ast.as_text(cl[1])
    mut at = at_form(node)
    if text is None or at is None:
        return
    mut size = font_size(node)
    mut x = coord(at[1])
    mut y = coord(at[2])
    if size == 0 or x is None or y is None:
        return
    mut p = Placement(x=x, y=y, dir=angle_at(at), w=advance(text, size), h=size, lead=label_lead(size), just=Just.start, cross=Cross.center)
    items.append(Item(kind=Kind.label, text=text.copy(), box=box_of(p)))


record Pose:
    x: int
    y: int
    angle: int


func append_symbol(node: ast.Node, libs: LibSymbol[], mut items: Item[]):
    mut at = at_form(node)
    if at is None:
        return
    mut x = coord(at[1])
    mut y = coord(at[2])
    if x is None or y is None:
        return
    mut origin = Pose(x=x, y=y, angle=angle_at(at))
    append_fields(node, origin, mut items)
    mut id_ = form_text(node, b"lib_id")
    if id_ is None:
        return
    mut entry = libraries_find(libs, id_)
    if entry is None:
        return
    mut unit = unit_of(node)
    for pin in entry.pins:
        if pin.unit == unit or pin.unit == 0:
            append_pin_texts(entry, pin, origin, mut items)


func append_fields(node: ast.Node, origin: Pose, mut items: Item[]):
    mut cl = ast.as_list(node)
    if cl is None:
        return
    for child in cl[1:len(cl)]:
        if not ast.is_form(child, b"property") or hidden(child):
            continue
        mut l = ast.as_list(child)
        if l is None:
            continue
        if len(l) < 3:
            continue
        mut text = ast.as_text(l[2])
        if text is None:
            continue
        if len(text) == 0:
            continue
        mut size = font_size(child)
        mut at = at_form(child)
        if size == 0 or at is None:
            continue
        mut x = coord(at[1])
        mut y = coord(at[2])
        if x is None or y is None:
            continue
        mut just = Just.middle
        if justified_left(child):
            just = Just.start
        mut p = Placement(x=x, y=y, dir=drawn_field_angle(angle_at(at), origin.angle), w=advance(text, size), h=size, just=just, cross=Cross.center)
        items.append(Item(kind=Kind.field, text=text.copy(), box=box_of(p)))


func drawn_field_angle(field: int, parent: int) -> int:
    if parent == 90 or parent == 270:
        return (field + 270) % 360
    return field


func append_pin_texts(entry: LibSymbol, pin: LibPin, origin: Pose, mut items: Item[]):
    mut at = on_sheet(pin.x, pin.y, origin)
    mut dir_ = (pin.angle + origin.angle) % 360
    mut body = along(at, dir_, pin.len)
    if entry.show_names and pin.name_size > 0 and len(pin.name) > 0:
        mut p = Placement(x=body.x, y=body.y, dir=dir_, w=advance(pin.name, pin.name_size), h=pin.name_size, lead=entry.name_offset, just=Just.start, cross=Cross.center)
        items.append(Item(kind=Kind.pin_name, text=pin.name.copy(), box=box_of(p)))
    if not entry.show_numbers or pin.number_size == 0 or len(pin.number) == 0:
        return
    mut mid = along(at, dir_, divtrunc(pin.len, 2))
    mut p2 = Placement(x=mid.x, y=mid.y, dir=dir_, w=advance(pin.number, pin.number_size), h=pin.number_size, just=Just.middle, cross=Cross.above)
    items.append(Item(kind=Kind.pin_number, text=pin.number.copy(), box=box_of(p2)))


record Sheet2:
    x: int
    y: int


func on_sheet(x: int, y: int, origin: Pose) -> Sheet2:
    mut r = turn(x, y, origin.angle)
    return Sheet2(x=origin.x + r[0], y=origin.y - r[1])


func turn(x: int, y: int, angle: int) -> FixedArray[int, 2]:
    mut a = angle % 360
    if a == 90:
        return FixedArray[int, 2]([-y, x])
    if a == 180:
        return FixedArray[int, 2]([-x, -y])
    if a == 270:
        return FixedArray[int, 2]([y, -x])
    return FixedArray[int, 2]([x, y])


func along(p: Sheet2, dir_: int, d: int) -> Sheet2:
    mut a = dir_ % 360
    if a == 90:
        return Sheet2(x=p.x, y=p.y - d)
    if a == 180:
        return Sheet2(x=p.x - d, y=p.y)
    if a == 270:
        return Sheet2(x=p.x, y=p.y + d)
    return Sheet2(x=p.x + d, y=p.y)


func coord(node: ast.Node) -> int?:
    mut v = try ast.as_number(node)
    mut value = try numeric.checked_i64(math.round(v * 100.0))
    return Some(int(value))


func at_form(node: ast.Node) -> ast.Node[]?:
    mut cl = try ast.as_list(node)
    for child in cl[1:len(cl)]:
        if not ast.is_form(child, b"at"):
            continue
        mut l = ast.as_list(child)
        if l is not None and len(l) >= 3:
            return Some(l.copy())
    return None


func angle_at(at: ast.Node[]) -> int:
    if len(at) < 4:
        return 0
    mut deg = numeric.checked_i64(math.round(ast.as_number(at[3]).unwrap_or(0.0)))
    if deg is None:
        return 0
    return int(deg) % 360


func number_child(node: ast.Node, form: bytes) -> int?:
    mut cl = try ast.as_list(node)
    for child in cl[1:len(cl)]:
        if not ast.is_form(child, form):
            continue
        mut l = ast.as_list(child)
        if l is not None and len(l) >= 2:
            return coord(l[1])
    return None


func form_text(node: ast.Node, form: bytes) -> bytes?:
    mut cl = try ast.as_list(node)
    for child in cl[1:len(cl)]:
        if not ast.is_form(child, form):
            continue
        mut l = ast.as_list(child)
        if l is not None and len(l) >= 2:
            return ast.as_text(l[1])
    return None


func hidden(node: ast.Node) -> bool:
    mut cl = ast.as_list(node)
    if cl is None:
        return False
    for child in cl[1:len(cl)]:
        if ast.is_form(child, b"hide"):
            mut l = ast.as_list(child)
            if l is not None and len(l) >= 2:
                return ast.as_atom(l[1]).unwrap_or(b"") == b"yes"
    return False


func justified_left(node: ast.Node) -> bool:
    mut cl = ast.as_list(node)
    if cl is None:
        return False
    for child in cl[1:len(cl)]:
        if not ast.is_form(child, b"effects"):
            continue
        mut el = ast.as_list(child)
        if el is None:
            continue
        for j in el[1:len(el)]:
            if not ast.is_form(j, b"justify"):
                continue
            mut jl = ast.as_list(j)
            if jl is None:
                continue
            for word in jl[1:len(jl)]:
                if ast.as_atom(word).unwrap_or(b"") == b"left":
                    return True
    return False


func unit_of(node: ast.Node) -> int:
    mut cl = ast.as_list(node)
    if cl is None:
        return 1
    for child in cl[1:len(cl)]:
        if not ast.is_form(child, b"unit"):
            continue
        mut l = ast.as_list(child)
        if l is not None and len(l) >= 2:
            mut n = numeric.checked_i64(math.round(ast.as_number(l[1]).unwrap_or(1.0)))
            if n is None:
                return 1
            return max(int(n), 0)
    return 1


func sub_unit(name: bytes) -> int?:
    mut style = -1
    mut i = len(name) - 1
    while i >= 0:
        if name[i] == 95:
            style = i
            break
        i -= 1
    if style < 0:
        return None
    mut unit = -1
    mut j = style - 1
    while j >= 0:
        if name[j] == 95:
            unit = j
            break
        j -= 1
    if unit < 0:
        return None
    mut number = try parse_mod.parse_u32(strs.text(name[unit + 1:style]))
    return Some(int(number))

import kicad_sch_textbox as m
import sexpr_parser as parser
import support_expect as ex
import byte_builder

func replace_bytes(src: bytes, old: bytes, new: bytes) -> bytes:
    mut w = byte_builder.create()
    mut pos = 0
    while pos < len(src):
        if src[pos:pos + len(old)] == old:
            byte_builder.append(mut w, new)
            pos += len(old)
        else:
            _ = byte_builder.append_byte(mut w, src[pos])
            pos += 1
    return byte_builder.finish(w)


func scan_text(src: bytes) -> m.Report?:
    match parser.parse(src):
        case Err(_):
            return None
        case Ok(nodes):
            if len(nodes) == 0:
                return None
            return Some(m.scan(nodes[0]))


# test "kicad-sch: text boxes follow justification and orientation"
public func test_kicad_sch_text_boxes_follow_justification_and_orientation(out: Stream) -> bool:
    mut right = m.box_of(m.Placement(x=0, y=0, dir=0, w=400, h=100, just=m.Just.start, cross=m.Cross.below))
    if not ex.eq_int(out, "right x0", right.x0, 0):
        return False
    if not ex.eq_int(out, "right x1", right.x1, 400):
        return False
    if not ex.eq_int(out, "right y0", right.y0, 0):
        return False
    if not ex.eq_int(out, "right y1", right.y1, 100):
        return False
    mut left = m.box_of(m.Placement(x=0, y=0, dir=180, w=400, h=100, just=m.Just.start, cross=m.Cross.below))
    if not ex.eq_int(out, "left x0", left.x0, -400):
        return False
    if not ex.eq_int(out, "left x1", left.x1, 0):
        return False
    mut up = m.box_of(m.Placement(x=0, y=0, dir=90, w=400, h=100, just=m.Just.start, cross=m.Cross.center))
    if not ex.eq_int(out, "up y0", up.y0, -400):
        return False
    if not ex.eq_int(out, "up y1", up.y1, 0):
        return False
    if not ex.eq_int(out, "up x0", up.x0, -50):
        return False
    if not ex.eq_int(out, "up x1", up.x1, 50):
        return False
    mut down = m.box_of(m.Placement(x=0, y=0, dir=270, w=400, h=100, just=m.Just.start, cross=m.Cross.center))
    if not ex.eq_int(out, "down y0", down.y0, 0):
        return False
    return ex.eq_int(out, "down y1", down.y1, 400)


# test "kicad-sch: the scan finds an overlapping label pair and clears a tidy sheet"
public func test_kicad_sch_the_scan_finds_an_overlapping_label_pair_and_clears_a_tidy_sheet(out: Stream) -> bool:
    mut clash = b"".join([b"(kicad_sch (lib_symbols)\n", b"(global_label \"VDD3V3\" (at 50 50 0) (effects (font (size 1.27 1.27)) (justify left)))\n", b"(global_label \"VDD3V3\" (at 50 50.5 0) (effects (font (size 1.27 1.27)) (justify left)))\n)\n"])
    mut hit = scan_text(clash)
    if hit is None:
        return False
    if not ex.eq_int(out, "texts", hit.texts, 2):
        return False
    if not ex.eq_int(out, "overlap", hit.overlaps, 1):
        return False
    mut first = hit.first.copy()
    if first is None:
        return False
    if not ex.eq_bytes(out, "first party", first.a, b"VDD3V3"):
        return False
    if not ex.ok(out, "label kind", first.kind_a == m.Kind.label):
        return False
    mut clear = replace_bytes(clash, b"(at 50 50.5 0)", b"(at 50 55 0)")
    mut ok = scan_text(clear)
    if ok is None:
        return False
    if not ex.eq_int(out, "clear texts", ok.texts, 2):
        return False
    if not ex.eq_int(out, "clear overlap", ok.overlaps, 0):
        return False
    return ex.ok(out, "no first collision", ok.first.is_none())


# test "kicad-sch: a zero-size pin name is not measured while its number still is"
public func test_kicad_sch_a_zero_size_pin_name_is_not_measured_while_its_number_still_is(out: Stream) -> bool:
    mut doc = b"".join([b"(kicad_sch (lib_symbols (symbol \"netlisp:BOX\" (pin_names (offset 0.254))\n", b"(symbol \"BOX_1_1\" (pin passive line (at -15.24 0 0) (length 2.54)\n", b"(name \"VSSAPM_U\" (effects (font (size 1.27 1.27))))\n", b"(number \"H14\" (effects (font (size 1.27 1.27))))))))\n", b"(symbol (lib_id \"netlisp:BOX\") (at 63.5 38.1 0) (unit 1)))\n"])
    mut shown = scan_text(doc)
    if shown is None:
        return False
    if not ex.eq_int(out, "name and number", shown.texts, 2):
        return False
    mut drawn = b"(name \"VSSAPM_U\" (effects (font (size 1.27 1.27))))"
    mut muted = b"(name \"VSSAPM_U\" (effects (font (size 0 0))))"
    mut quiet = replace_bytes(doc, drawn, muted)
    mut after = scan_text(quiet)
    if after is None:
        return False
    if not ex.eq_int(out, "number remains", after.texts, 1):
        return False
    return ex.eq_int(out, "no collision", after.overlaps, 0)

import kicad_sym_library as library
import kicad_sch_shape as shape
import kicad_sym_reader as kicad_sym
import kicad_sch_sheet as sheet
import infra_log as log
import support_strs as strs

public func synth(fs: Filesystem, err: Stream, lib: library.Library?, req: shape.Request) -> shape.Shape:
    if lib is not None:
        mut sym = resolve(lib, req.names)
        if sym is not None:
            mut s = build(fs, err, sym, req)
            if s is not None:
                return s.copy()
    return shape.synth(fs, req)


func resolve(lib: library.Library, names: shape.Names) -> kicad_sym.Symbol?:
    mut first = library.library_find(lib, names.component)
    if first is not None:
        return first
    mut second = library.library_find(lib, names.symbol)
    if second is not None:
        return second
    return library.library_find(lib, names.pinout)


func build(fs: Filesystem, err: Stream, sym: kicad_sym.Symbol, req: shape.Request) -> shape.Shape?:
    mut merged = merge_units(sym)
    if len(merged) == 0 or count_pins(merged) == 0:
        return None
    mut duplicate = repeated_pad(merged)
    if duplicate is not None:
        log.warn(err, b"export-kicad-sch: vendor symbol '" + sym.name + b"' draws pad " + duplicate + b" twice \xe2\x80\x94 synthesising a box instead")
        return None
    mut ctx = Ctx(fallback={})
    ctx_index_names(fs, mut ctx, req)
    mut units: shape.ShapeUnit[] = []
    for i in range(len(merged)):
        mut adapted = adapt_unit(ctx, merged[i], i + 1)
        if adapted is None:
            log.warn(err, b"export-kicad-sch: vendor symbol '" + sym.name + b"' has pins that collide on the connection grid \xe2\x80\x94 synthesising a box instead")
            return None
        units.append(adapted.copy())
    append_missing(fs, err, mut units, req, merged, sym.name)
    return Some(shape.Shape(lib_name=shape.lib_name_for(req), units=units, vendor=True))


func append_missing(fs: Filesystem, err: Stream, mut units: shape.ShapeUnit[], req: shape.Request, drawn: kicad_sym.SymbolUnit[], name: bytes):
    mut extra = missing_pads(fs, req, drawn)
    if len(extra) == 0:
        return
    mut msg = b"export-kicad-sch: vendor symbol '" + name + b"' does not draw " + str(len(extra)).encode() + b" pad(s) the design uses \xe2\x80\x94 adding them as unit " + str(len(units) + 1).encode()
    log.warn(err, msg)
    units.append(shape.box_unit(extra, len(units) + 1))


# Common graphics appear on every unit, common pins only on the first.
func merge_units(sym: kicad_sym.Symbol) -> kicad_sym.SymbolUnit[]:
    mut common: kicad_sym.SymbolUnit? = None
    mut real: kicad_sym.SymbolUnit[] = []
    for u in sym.units:
        if u.number == 0:
            common = Some(u.copy())
        else:
            real.append(u.copy())
    if common is None:
        return real
    if len(real) == 0:
        return [common.copy()]
    mut out: kicad_sym.SymbolUnit[] = []
    for i in range(len(real)):
        mut unit = real[i].copy()
        mut pins = unit.pins.copy()
        if i == 0:
            pins = common.pins.copy()
            pins.extend(unit.pins)
        mut graphics = common.graphics.copy()
        graphics.extend(unit.graphics)
        out.append(kicad_sym.SymbolUnit(number=unit.number, pins=pins, graphics=graphics))
    return out


func count_pins(units: kicad_sym.SymbolUnit[]) -> int:
    mut n = 0
    for u in units:
        n += len(u.pins)
    return n


func repeated_pad(units: kicad_sym.SymbolUnit[]) -> bytes?:
    mut seen: set[str] = set()
    for u in units:
        for p in u.pins:
            mut key = strs.text(p.pad)
            if key in seen:
                return Some(p.pad.copy())
            seen.add(key)
    return None


func missing_pads(fs: Filesystem, req: shape.Request, units: kicad_sym.SymbolUnit[]) -> shape.PadName[]:
    mut drawn: set[str] = set()
    for u in units:
        for p in u.pins:
            drawn.add(strs.text(p.pad))
    mut out: shape.PadName[] = []
    for pn in shape.required_pads(fs, req):
        if strs.text(pn.pad) not in drawn:
            out.append(pn.copy())
    return out


record Ctx:
    fallback: dict[str, bytes]


func ctx_index_names(fs: Filesystem, mut self: Ctx, req: shape.Request):
    for pn in shape.required_pads(fs, req):
        self.fallback[strs.text(pn.pad)] = pn.name.copy()


func ctx_name_of(self: Ctx, pin: kicad_sym.Pin) -> bytes:
    if len(pin.name) > 0 and pin.name != b"~":
        return pin.name.copy()
    return self.fallback.get(strs.text(pin.pad), pin.pad).copy()


record Box:
    min: kicad_sym.Point
    max: kicad_sym.Point


func box_add(mut self: Box, p: kicad_sym.Point, pad: int):
    self.min = kicad_sym.Point(x=min(self.min.x, p.x - pad), y=min(self.min.y, p.y - pad))
    self.max = kicad_sym.Point(x=max(self.max.x, p.x + pad), y=max(self.max.y, p.y + pad))


func adapt_unit(ctx: Ctx, u: kicad_sym.SymbolUnit, number: int) -> shape.ShapeUnit?:
    mut pins = snap_pins(u.pins)
    mut box = try extents(pins, u.graphics)
    mut shift = kicad_sym.Point(x=-snap_nearest((box.min.x + box.max.x) // 2), y=-snap_nearest((box.min.y + box.max.y) // 2))
    mut out: shape.Pin[] = []
    mut seen: set[int] = set()
    for p in pins:
        mut at = kicad_sym.Point(x=p.at.x + shift.x, y=p.at.y + shift.y)
        mut key = point_key(at)
        if key in seen:
            return None
        seen.add(key)
        mut name = ctx_name_of(ctx, p)
        out.append(shape.Pin(pad=p.pad.copy(), name=name.copy(), side=side_of(p.angle), show_name=not shape.names_pad(shape.PadName(pad=p.pad.copy(), name=name)), x=int(at.x / 100), y=int(at.y / 100), len=int(p.length / 100)))
    return Some(shape.ShapeUnit(number=number, title=b"", pins=out, half_w=half_abs(box.min.x + shift.x, box.max.x + shift.x), half_h=half_abs(box.min.y + shift.y, box.max.y + shift.y), graphics=body(u.graphics, box, shift), stubs=[]))


func body(graphics: kicad_sym.Graphic[], box: Box, shift: kicad_sym.Point) -> kicad_sym.Graphic[]:
    if len(graphics) == 0:
        return [inset(box, shift)]
    mut out: kicad_sym.Graphic[] = []
    for g in graphics:
        out.append(translate(g, shift))
    return out


func inset(box: Box, shift: kicad_sym.Point) -> kicad_sym.Graphic:
    mut dx = min(12700, (box.max.x - box.min.x) // 4)
    mut dy = min(12700, (box.max.y - box.min.y) // 4)
    mut pts = [kicad_sym.Point(x=box.min.x + dx + shift.x, y=box.max.y - dy + shift.y), kicad_sym.Point(x=box.max.x - dx + shift.x, y=box.min.y + dy + shift.y)]
    return kicad_sym.Graphic(kind=kicad_sym.Kind.rectangle, pts=pts, text=b"", style=kicad_sym.Style(width=254, fill=kicad_sym.Fill.background))


func translate(g: kicad_sym.Graphic, shift: kicad_sym.Point) -> kicad_sym.Graphic:
    mut pts: kicad_sym.Point[] = []
    for p in g.pts:
        mut moved = kicad_sym.Point(x=p.x + shift.x, y=p.y + shift.y)
        if g.kind == kicad_sym.Kind.text:
            moved = kicad_sym.Point(x=snap_nearest(moved.x), y=snap_nearest(moved.y))
        pts.append(moved)
    mut out = g.copy()
    out.pts = pts
    return out


func snap_pins(pins: kicad_sym.Pin[]) -> kicad_sym.Pin[]:
    mut out: kicad_sym.Pin[] = []
    for p in pins:
        mut snapped = p.copy()
        snapped.at = kicad_sym.Point(x=snap_nearest(p.at.x), y=snap_nearest(p.at.y))
        out.append(snapped)
    return out


func extents(pins: kicad_sym.Pin[], graphics: kicad_sym.Graphic[]) -> Box?:
    mut box: Box? = None
    for p in pins:
        box = Some(grow(box, p.at, 0))
    for g in graphics:
        for point in g.pts:
            box = Some(grow(box, point, g.radius))
    return box


func grow(box: Box?, p: kicad_sym.Point, pad: int) -> Box:
    mut out = box.unwrap_or(Box(min=p.copy(), max=p.copy()))
    box_add(mut out, p, pad)
    return out


func half_abs(lo: int, hi: int) -> int:
    mut widest = max(abs(lo), abs(hi))
    mut hundredths = (widest + 99) // 100
    return sheet.snap_up(max(hundredths, shape.pitch))


# Private Zig functions made public for split tests.
public func snap_nearest(v: int) -> int:
    return ((v + 6350) // 12700) * 12700


func point_key(p: kicad_sym.Point) -> int:
    mut span_ = 2 * kicad_sym.max_coord + 1
    return (p.x + kicad_sym.max_coord) * span_ + p.y + kicad_sym.max_coord


public func side_of(angle: int) -> shape.Side:
    mut quarter = ((angle + 45) // 90) % 4
    if quarter == 1:
        return shape.Side.bottom
    if quarter == 2:
        return shape.Side.right
    if quarter == 3:
        return shape.Side.top
    return shape.Side.left

import kicad_sch_vendor as m
