import kicad_sch_textbox as textbox
import sexpr_ast as ast
import sexpr_parser as parser
import numeric
import support_parse as parse_mod
import support_strs as strs

public const err_not_schematic: str = "NotSchematic"


public const err_symbol_count_mismatch: str = "SymbolCountMismatch"


public const err_symbol_uuid_mismatch: str = "SymbolUuidMismatch"


public const err_unknown_lib_id: str = "UnknownLibId"


public const err_duplicate_pad: str = "DuplicatePad"


public const err_label_count_mismatch: str = "LabelCountMismatch"


public const err_missing_net_label: str = "MissingNetLabel"


public const err_no_connect_count_mismatch: str = "NoConnectCountMismatch"


public const err_sheet_link_mismatch: str = "SheetLinkMismatch"


public const err_off_grid: str = "OffGrid"


public const err_wire_count_mismatch: str = "WireCountMismatch"


public const err_wire_not_orthogonal: str = "WireNotOrthogonal"


public const err_wire_through_pin: str = "WireThroughPin"


public const err_label_on_wire_interior: str = "LabelOnWireInterior"


public const err_missing_junction: str = "MissingJunction"


public const err_stray_junction: str = "StrayJunction"


public record Expect:
    uuids: bytes[]
    lib_ids: bytes[]
    labels: bytes[]
    rail_values: bytes[]
    no_connects: int
    sheets: bytes[]
    wires: int = 0


public func check(source: bytes, want: Expect) -> Result[textbox.Report, str]:
    mut nodes: ast.Node[] = []
    match parser.parse(source):
        case Err(e):
            return Err(parser.error_name(e))
        case Ok(parsed):
            nodes = parsed
    if len(nodes) == 0 or not ast.is_form(nodes[0], b"kicad_sch"):
        return Err(err_not_schematic)
    mut root = ast.as_list(nodes[0])
    if root is None:
        return Err(err_not_schematic)
    try grid_scan(nodes[0])
    mut found = found_init()
    for child in root[1:]:
        try scan_top(child, mut found)
    if len(found.uuids) != len(want.uuids) or len(found.lib_ids) != len(want.lib_ids):
        return Err(err_symbol_count_mismatch)
    for i in range(len(found.uuids)):
        if found.uuids[i] != want.uuids[i]:
            return Err(err_symbol_uuid_mismatch)
    for j in range(len(found.lib_ids)):
        mut got = found.lib_ids[j].copy()
        if got != want.lib_ids[j] or strs.text(got) not in found.lib_names:
            return Err(err_unknown_lib_id)
    if found.no_connects != want.no_connects:
        return Err(err_no_connect_count_mismatch)
    try check_sheets(found, want)
    try compare(found.labels, want.labels)
    try compare(found.rail_values, want.rail_values)
    try check_wires(found.geom, want)
    return Ok(textbox.scan(nodes[0]))


record Pt:
    x: int
    y: int


record Seg:
    a: Pt
    b: Pt


record LibPin:
    lib: bytes
    unit: int
    at: Pt


record Placed:
    lib: bytes
    unit: int
    at: Pt
    angle: int


record Geometry:
    segs: Seg[]
    dots: Pt[]
    placed: Placed[]
    lib_pins: LibPin[]
    label_pts: Pt[]


record Multiset:
    counts: dict[str, int]
    total: int = 0


record Found:
    lib_names: set[str]
    uuids: bytes[]
    lib_ids: bytes[]
    labels: Multiset
    rail_values: Multiset
    sheets: bytes[]
    geom: Geometry
    no_connects: int = 0


func found_init() -> Found:
    mut g = Geometry(segs=[], dots=[], placed=[], lib_pins=[], label_pts=[])
    return Found(lib_names=set(), uuids=[], lib_ids=[], labels=Multiset(counts={}), rail_values=Multiset(counts={}), sheets=[], geom=g)


func multiset_add(mut self: Multiset, value: bytes):
    mut key = strs.text(value)
    self.counts[key] = self.counts.get(key, 0) + 1
    self.total += 1


func check_wires(g: Geometry, want: Expect) -> Result[Unit, str]:
    if len(g.segs) != want.wires:
        return Err(err_wire_count_mismatch)
    try check_orthogonal(g.segs)
    try check_pin_touch(g.segs, pin_points(g))
    try check_label_touch(g.segs, g.label_pts)
    return check_junctions(g)


func check_orthogonal(segs: Seg[]) -> Result[Unit, str]:
    for s in segs:
        if s.a.x == s.b.x and s.a.y == s.b.y:
            return Err(err_wire_not_orthogonal)
        if s.a.x != s.b.x and s.a.y != s.b.y:
            return Err(err_wire_not_orthogonal)
    return Ok(())


# Pins and labels must attach at actual wire ends; an interior touch lies.
func check_pin_touch(segs: Seg[], pins: Pt[]) -> Result[Unit, str]:
    for s in segs:
        for p in pins:
            if on_seg(p, s) and not end_of(s, p):
                return Err(err_wire_through_pin)
    return Ok(())


func check_label_touch(segs: Seg[], labels: Pt[]) -> Result[Unit, str]:
    for s in segs:
        for p in labels:
            if on_seg(p, s) and not end_of(s, p):
                return Err(err_label_on_wire_interior)
    return Ok(())


func check_junctions(g: Geometry) -> Result[Unit, str]:
    mut ends: dict[int, int] = {}
    for s in g.segs:
        tally(mut ends, s.a)
        tally(mut ends, s.b)
    mut dots: set[int] = set()
    for p in g.dots:
        mut key = pt_key(p)
        if ends.get(key, 0) < 2:
            return Err(err_stray_junction)
        dots.add(key)
    for k in ends:
        if ends[k] >= 3 and k not in dots:
            return Err(err_missing_junction)
    return Ok(())


func tally(mut ends: dict[int, int], p: Pt):
    mut key = pt_key(p)
    ends[key] = ends.get(key, 0) + 1


func pt_key(p: Pt) -> int:
    return (p.x + 1048576) * 2097152 + p.y + 1048576


# Re-derive pin positions from the emitted library and placed symbols.
func pin_points(g: Geometry) -> Pt[]:
    mut out: Pt[] = []
    for s in g.placed:
        for lp in g.lib_pins:
            if lp.lib != s.lib or (lp.unit != s.unit and lp.unit != 0):
                continue
            mut r = rotate(lp.at, s.angle)
            out.append(Pt(x=s.at.x + r.x, y=s.at.y - r.y))
    return out


func rotate(p: Pt, angle: int) -> Pt:
    mut turn = angle % 360
    if turn == 90:
        return Pt(x=-p.y, y=p.x)
    if turn == 180:
        return Pt(x=-p.x, y=-p.y)
    if turn == 270:
        return Pt(x=p.y, y=-p.x)
    return p.copy()


func on_seg(p: Pt, s: Seg) -> bool:
    return p.x >= min(s.a.x, s.b.x) and p.x <= max(s.a.x, s.b.x) and p.y >= min(s.a.y, s.b.y) and p.y <= max(s.a.y, s.b.y)


func end_of(s: Seg, p: Pt) -> bool:
    return (s.a.x == p.x and s.a.y == p.y) or (s.b.x == p.x and s.b.y == p.y)


func check_sheets(found: Found, want: Expect) -> Result[Unit, str]:
    if found.sheets != want.sheets:
        return Err(err_sheet_link_mismatch)
    return Ok(())


func compare(found: Multiset, want: bytes[]) -> Result[Unit, str]:
    if found.total != len(want):
        return Err(err_label_count_mismatch)
    mut expected = Multiset(counts={})
    for l in want:
        multiset_add(mut expected, l)
    if len(expected.counts) != len(found.counts):
        return Err(err_label_count_mismatch)
    for key in expected.counts:
        if key not in found.counts:
            return Err(err_missing_net_label)
        if found.counts[key] != expected.counts[key]:
            return Err(err_label_count_mismatch)
    return Ok(())


func scan_top(node: ast.Node, mut found: Found) -> Result[Unit, str]:
    if ast.is_form(node, b"lib_symbols"):
        return scan_lib_symbols(node, mut found)
    if ast.is_form(node, b"no_connect"):
        found.no_connects += 1
    elif ast.is_form(node, b"global_label"):
        scan_label(node, mut found)
    elif ast.is_form(node, b"symbol"):
        scan_placed(node, mut found)
    elif ast.is_form(node, b"sheet"):
        scan_sheet(node, mut found)
    elif ast.is_form(node, b"wire"):
        scan_wire(node, mut found)
    elif ast.is_form(node, b"junction"):
        scan_junction(node, mut found)
    return Ok(())


func scan_wire(node: ast.Node, mut found: Found):
    mut cl = ast.as_list(node)
    if cl is None:
        return
    for child in cl[1:]:
        if not ast.is_form(child, b"pts"):
            continue
        mut l = ast.as_list(child)
        if l is None or len(l) < 3:
            continue
        mut a = xy_of(l[1])
        mut b = xy_of(l[2])
        if a is not None and b is not None:
            found.geom.segs.append(Seg(a=a, b=b))


func scan_junction(node: ast.Node, mut found: Found):
    mut p = point_of(node)
    if p is not None:
        found.geom.dots.append(p)


func coord(node: ast.Node) -> int?:
    mut v = try ast.as_number(node)
    return numeric.checked_i64(round(v * 100.0))


func xy_of(node: ast.Node) -> Pt?:
    if not ast.is_form(node, b"xy"):
        return None
    mut l = try ast.as_list(node)
    if len(l) < 3:
        return None
    mut x = try coord(l[1])
    mut y = try coord(l[2])
    return Some(Pt(x=x, y=y))


func at_form(node: ast.Node) -> ast.Node[]?:
    mut cl = try ast.as_list(node)
    for child in cl[1:]:
        if not ast.is_form(child, b"at"):
            continue
        mut l = ast.as_list(child)
        if l is not None and len(l) >= 3:
            return Some(l.copy())
    return None


func point_of(node: ast.Node) -> Pt?:
    mut l = try at_form(node)
    mut x = try coord(l[1])
    mut y = try coord(l[2])
    return Some(Pt(x=x, y=y))


func angle_of(node: ast.Node) -> int:
    mut l = at_form(node)
    if l is None or len(l) < 4:
        return 0
    mut deg = numeric.checked_i64(round(ast.as_number(l[3]).unwrap_or(0.0)))
    if deg is None:
        return 0
    return deg % 360


func unit_of(node: ast.Node) -> int:
    mut cl = ast.as_list(node)
    if cl is None:
        return 1
    for child in cl[1:]:
        if not ast.is_form(child, b"unit"):
            continue
        mut l = ast.as_list(child)
        if l is None or len(l) < 2:
            continue
        mut n = numeric.checked_i64(round(ast.as_number(l[1]).unwrap_or(1.0)))
        if n is None:
            return 1
        return max(n, 0)
    return 1


func sub_unit(name: bytes) -> int?:
    mut style = name.rfind(b"_")
    if style < 0:
        return None
    mut unit = name[0:style].rfind(b"_")
    if unit < 0:
        return None
    return parse_mod.parse_u32(strs.text(name[unit + 1:style]))


func scan_label(node: ast.Node, mut found: Found):
    mut cl = ast.as_list(node)
    if cl is None or len(cl) < 2:
        return
    mut label = ast.as_text(cl[1])
    if label is None:
        return
    mut labels = found.labels.copy()
    multiset_add(mut labels, label)
    found.labels = labels
    mut p = point_of(node)
    if p is not None:
        found.geom.label_pts.append(p)


func scan_sheet(node: ast.Node, mut found: Found):
    mut file = property(node, b"Sheetfile")
    if file is not None:
        found.sheets.append(file.copy())


func property(node: ast.Node, name: bytes) -> bytes?:
    mut cl = try ast.as_list(node)
    for child in cl[1:]:
        if not ast.is_form(child, b"property"):
            continue
        mut l = ast.as_list(child)
        if l is not None and len(l) >= 3 and ast.as_text(l[1]).unwrap_or(b"") == name:
            return ast.as_text(l[2])
    return None


func scan_lib_symbols(node: ast.Node, mut found: Found) -> Result[Unit, str]:
    mut cl = ast.as_list(node)
    if cl is None:
        return Ok(())
    for sym in cl[1:]:
        mut sl = ast.as_list(sym)
        if sl is None or len(sl) < 2 or not ast.is_form(sym, b"symbol"):
            continue
        mut name = ast.as_text(sl[1])
        if name is None:
            continue
        found.lib_names.add(strs.text(name))
        mut pads: set[str] = set()
        try unique_pads(sym, mut pads)
        scan_lib_units(sl[2:], name, mut found)
    return Ok(())


func scan_lib_units(children: ast.Node[], lib: bytes, mut found: Found):
    for sub in children:
        if not ast.is_form(sub, b"symbol"):
            continue
        mut l = ast.as_list(sub)
        if l is None or len(l) < 2:
            continue
        mut unit = sub_unit(ast.as_text(l[1]).unwrap_or(b""))
        if unit is None:
            continue
        for item in l[2:]:
            if not ast.is_form(item, b"pin"):
                continue
            mut at = point_of(item)
            if at is not None:
                found.geom.lib_pins.append(LibPin(lib=lib.copy(), unit=unit, at=at))


func unique_pads(node: ast.Node, mut pads: set[str]) -> Result[Unit, str]:
    mut cl = ast.as_list(node)
    if cl is None:
        return Ok(())
    for child in cl:
        if ast.is_form(child, b"number"):
            mut l = ast.as_list(child)
            if l is None or len(l) < 2:
                continue
            mut pad = ast.as_text(l[1])
            if pad is None:
                continue
            mut key = strs.text(pad)
            if key in pads:
                return Err(err_duplicate_pad)
            pads.add(key)
            continue
        if ast.as_list(child).is_some():
            try unique_pads(child, mut pads)
    return Ok(())


func scan_placed(node: ast.Node, mut found: Found):
    mut cl = ast.as_list(node)
    if cl is None:
        return
    mut lib_id: bytes? = None
    mut uuid: bytes? = None
    for child in cl[1:]:
        mut l = ast.as_list(child)
        if l is None or len(l) < 2:
            continue
        if ast.is_form(child, b"lib_id"):
            lib_id = ast.as_text(l[1])
        if ast.is_form(child, b"uuid"):
            uuid = ast.as_text(l[1])
    if lib_id is None:
        return
    found.lib_ids.append(lib_id.copy())
    found.uuids.append(uuid.unwrap_or(b"").copy())
    mut at = point_of(node)
    if at is not None:
        found.geom.placed.append(Placed(lib=lib_id.copy(), unit=unit_of(node), at=at, angle=angle_of(node)))
    mut ref = property(node, b"Reference")
    if ref is not None and ref.startswith(b"#PWR"):
        mut rails = found.rail_values.copy()
        multiset_add(mut rails, property(node, b"Value").unwrap_or(b""))
        found.rail_values = rails


# Drawing-only body art is exempt; text and every connection anchor are not.
func grid_scan(node: ast.Node) -> Result[Unit, str]:
    if is_graphic_form(node):
        return Ok(())
    mut cl = ast.as_list(node)
    if cl is None:
        return Ok(())
    if len(cl) >= 3 and is_point_form(node):
        try on_grid(cl[1])
        try on_grid(cl[2])
    for child in cl:
        try grid_scan(child)
    return Ok(())


func is_point_form(node: ast.Node) -> bool:
    return ast.is_form(node, b"at") or ast.is_form(node, b"xy") or ast.is_form(node, b"start") or ast.is_form(node, b"end")


func is_graphic_form(node: ast.Node) -> bool:
    return ast.is_form(node, b"rectangle") or ast.is_form(node, b"polyline") or ast.is_form(node, b"circle") or ast.is_form(node, b"arc") or ast.is_form(node, b"bezier")


func on_grid(node: ast.Node) -> Result[Unit, str]:
    mut v = ast.as_number(node)
    if v is None:
        return Ok(())
    mut scaled = v * 100.0
    mut hundredths = numeric.checked_i64(round(scaled))
    if hundredths is None or abs(scaled - float(hundredths)) > 0.01 or hundredths % 127 != 0:
        return Err(err_off_grid)
    return Ok(())

import kicad_sch_verify as m
import support_expect as ex

# std.mem.replaceOwned for byte fixtures; bytes has no replace method.
func replace_owned(source: bytes, old: bytes, new: bytes) -> bytes:
    mut parts: bytes[] = []
    mut cursor = 0
    while cursor < len(source):
        mut relative = source[cursor:len(source)].find(old)
        if relative < 0:
            break
        mut index = cursor + relative
        parts.append(source[cursor:index])
        parts.append(new.copy())
        cursor = index + len(old)
    parts.append(source[cursor:])
    return b"".join(parts)


func minimal_doc() -> bytes:
    mut parts = [b"(kicad_sch\n  (version 20260306)\n  (lib_symbols\n    (symbol \"netlisp:BOX\"\n      (symbol \"BOX_1_1\"\n", b"        (pin passive line (at -15.24 1.27 0) (length 2.54)\n          (name \"A\" (effects)) (number \"1\" (effects)))\n", b"        (pin passive line (at 15.24 1.27 180) (length 2.54)\n          (name \"B\" (effects)) (number \"2\" (effects))))))\n", b"  (symbol (lib_id \"netlisp:BOX\") (at 63.5 38.1 0)\n    (uuid \"aaaa\"))\n  (global_label \"NETA\" (at 43.18 36.83 180))\n  (no_connect (at 78.74 36.83))\n)"]
    return b"".join(parts)


func minimal_expect() -> m.Expect:
    return m.Expect(uuids=[b"aaaa"], lib_ids=[b"netlisp:BOX"], labels=[b"NETA"], rail_values=[], no_connects=1, sheets=[])


func wired_doc() -> bytes:
    mut base = minimal_doc()
    mut start = base.find(b"  (symbol (lib_id")
    mut parts = [base[0:start], b"  (symbol (lib_id \"netlisp:BOX\") (at 63.5 38.1 0) (unit 1)\n    (uuid \"aaaa\"))\n", b"  (wire (pts (xy 48.26 36.83) (xy 43.18 36.83)))\n  (wire (pts (xy 43.18 36.83) (xy 43.18 27.94)))\n", b"  (wire (pts (xy 43.18 36.83) (xy 43.18 46.99)))\n  (wire (pts (xy 78.74 36.83) (xy 83.82 36.83)))\n", b"  (junction (at 43.18 36.83))\n  (global_label \"NETA\" (at 43.18 46.99 180))\n  (global_label \"NETB\" (at 83.82 36.83 0))\n)"]
    return b"".join(parts)


func wired_expect() -> m.Expect:
    return m.Expect(uuids=[b"aaaa"], lib_ids=[b"netlisp:BOX"], labels=[b"NETA", b"NETB"], rail_values=[], no_connects=0, sheets=[], wires=4)


func hier_doc() -> bytes:
    mut parts = [b"(kicad_sch\n  (version 20260306)\n  (lib_symbols\n    (symbol \"netlisp:PWR_GND\"\n      (symbol \"PWR_GND_1_1\"\n", b"        (pin power_in line (at 0 0 270) (length 0)\n          (name \"\" (effects)) (number \"1\" (effects))))))\n", b"  (symbol (lib_id \"netlisp:PWR_GND\") (at 63.5 38.1 0)\n    (uuid \"pwr-1\")\n    (property \"Reference\" \"#PWR01\" (at 63.5 31.75 0))\n    (property \"Value\" \"GND\" (at 63.5 44.45 0)))\n", b"  (sheet (at 25.4 25.4 0) (size 63.5 25.4)\n    (uuid \"sheet-1\")\n    (property \"Sheetname\" \"Core\" (at 25.4 24.13 0))\n    (property \"Sheetfile\" \"board-core.kicad_sch\" (at 25.4 52.07 0)))\n)"]
    return b"".join(parts)


func hier_expect() -> m.Expect:
    return m.Expect(uuids=[b"pwr-1"], lib_ids=[b"netlisp:PWR_GND"], labels=[], rail_values=[b"GND"], no_connects=0, sheets=[b"board-core.kicad_sch"])


func passes(out: Stream, source: bytes, want: m.Expect) -> bool:
    match m.check(source, want):
        case Ok(_):
            return True
        case Err(e):
            return ex.eq_str(out, "good document", e, "")


func fails(out: Stream, source: bytes, want: m.Expect, error: str) -> bool:
    match m.check(source, want):
        case Err(e):
            return ex.eq_str(out, "specific verifier error", e, error)
        case Ok(_):
            return ex.ok(out, "damaged document fails", False)


# test "kicad-sch: verify passes a good document and catches a dropped symbol"
public func test_kicad_sch_verify_passes_a_good_document_and_catches_a_dropped_symbol(out: Stream) -> bool:
    mut source = minimal_doc()
    mut want = minimal_expect()
    if not passes(out, source, want):
        return False
    mut cut_start = source.find(b"  (symbol (lib_id")
    mut cut_end = source.find(b"  (global_label")
    mut damaged = source[0:cut_start] + source[cut_end:]
    return fails(out, damaged, want, m.err_symbol_count_mismatch)


# test "kicad-sch: verify catches label, no-connect, and lib_id damage"
public func test_kicad_sch_verify_catches_label_no_connect_and_lib_id_damage(out: Stream) -> bool:
    mut source = minimal_doc()
    mut want = minimal_expect()
    return fails(out, replace_owned(source, b"  (global_label \"NETA\" (at 43.18 36.83 180))\n", b""), want, m.err_label_count_mismatch) and fails(out, replace_owned(source, b"(global_label \"NETA\"", b"(global_label \"NETB\""), want, m.err_missing_net_label) and fails(out, replace_owned(source, b"  (no_connect (at 78.74 36.83))\n", b""), want, m.err_no_connect_count_mismatch) and fails(out, replace_owned(source, b"(symbol \"netlisp:BOX\"", b"(symbol \"netlisp:OTHER\""), want, m.err_unknown_lib_id)


# test "kicad-sch: verify catches off-grid coordinates and duplicate pads"
public func test_kicad_sch_verify_catches_off_grid_coordinates_and_duplicate_pads(out: Stream) -> bool:
    mut source = minimal_doc()
    mut want = minimal_expect()
    return fails(out, replace_owned(source, b"(at 63.5 38.1 0)", b"(at 63.4 38.1 0)"), want, m.err_off_grid) and fails(out, replace_owned(source, b"(number \"2\"", b"(number \"1\""), want, m.err_duplicate_pad)


# test "kicad-sch: verify passes off-grid body art but not an off-grid pin"
public func test_kicad_sch_verify_passes_off_grid_body_art_but_not_an_off_grid_pin(out: Stream) -> bool:
    mut source = minimal_doc()
    mut parts = [b"      (symbol \"BOX_1_1\"\n", b"        (polyline (pts (xy -15.239 1.219) (xy -1.1 2.2))\n          (stroke (width 0.254) (type default)) (fill (type none)))\n", b"        (arc (start 7.62 0) (mid 6.35 1.219) (end 5.08 0)\n          (stroke (width 0.254) (type default)) (fill (type none)))\n"]
    mut art = replace_owned(source, b"      (symbol \"BOX_1_1\"\n", b"".join(parts))
    if not passes(out, art, minimal_expect()):
        return False
    return fails(out, replace_owned(source, b"(at -15.24 1.27 0)", b"(at -15.239 1.27 0)"), minimal_expect(), m.err_off_grid)


# test "kicad-sch: verify catches a wire through a pin, a diagonal, and a missing segment"
public func test_kicad_sch_verify_catches_a_wire_through_a_pin_a_diagonal_and_a_missing_segment(out: Stream) -> bool:
    mut source = wired_doc()
    mut want = wired_expect()
    return passes(out, source, want) and fails(out, replace_owned(source, b"(xy 78.74 36.83)", b"(xy 73.66 36.83)"), want, m.err_wire_through_pin) and fails(out, replace_owned(source, b"(xy 43.18 27.94)", b"(xy 40.64 27.94)"), want, m.err_wire_not_orthogonal) and fails(out, replace_owned(source, b"  (wire (pts (xy 43.18 36.83) (xy 43.18 46.99)))\n", b""), want, m.err_wire_count_mismatch)


# test "kicad-sch: verify catches a label caught mid-wire"
public func test_kicad_sch_verify_catches_a_label_caught_mid_wire(out: Stream) -> bool:
    mut inside = replace_owned(wired_doc(), b"(global_label \"NETB\" (at 83.82 36.83 0))", b"(global_label \"NETB\" (at 81.28 36.83 0))")
    return fails(out, inside, wired_expect(), m.err_label_on_wire_interior)


# test "kicad-sch: verify matches junction dots to the points wire ends actually meet at"
public func test_kicad_sch_verify_matches_junction_dots_to_the_points_wire_ends_actually_meet_at(out: Stream) -> bool:
    mut source = wired_doc()
    mut want = wired_expect()
    return fails(out, replace_owned(source, b"  (junction (at 43.18 36.83))\n", b""), want, m.err_missing_junction) and fails(out, replace_owned(source, b"(junction (at 43.18 36.83))", b"(junction (at 43.18 27.94))"), want, m.err_stray_junction)


# test "kicad-sch: verify matches child sheet files and rail symbol values"
public func test_kicad_sch_verify_matches_child_sheet_files_and_rail_symbol_values(out: Stream) -> bool:
    mut source = hier_doc()
    mut want = hier_expect()
    return passes(out, source, want) and fails(out, replace_owned(source, b"board-core.kicad_sch", b"board-other.kicad_sch"), want, m.err_sheet_link_mismatch) and fails(out, replace_owned(source, b"(property \"Sheetfile\"", b"(property \"Other\""), want, m.err_sheet_link_mismatch) and fails(out, replace_owned(source, b"\"Value\" \"GND\"", b"\"Value\" \"AGND\""), want, m.err_missing_net_label)

import kicad_sch_shape as shape_mod
import support_sort as srt

public const grid: int = 127


public const max_span: int = 12700


public record Point:
    x: int
    y: int


public record Seg:
    a: Point
    b: Point


public record Box:
    x0: int
    y0: int
    x1: int
    y1: int


public record End:
    at: Point
    side: shape_mod.Side


public record Path:
    key: bytes
    pts: Point[]


public record Field:
    stops: Point[]
    bodies: Box[]
    segs: Seg[]


public func same_point(a: Point, b: Point) -> bool:
    return a.x == b.x and a.y == b.y


public func span(a: Point, b: Point) -> int:
    return abs(a.x - b.x) + abs(a.y - b.y)


public func route(a: End, b: End, field: Field, key: bytes) -> Path?:
    mut distance = span(a.at, b.at)
    if distance > max_span or distance == 0:
        return None
    for i in range(30):
        mut pts = compact(candidate(i, a, b))
        if clean(pts, a.at, b.at, field):
            return Some(Path(key=key.copy(), pts=pts))
    return None


public func junctions(segs: Seg[]) -> Point[]:
    mut counts: dict[int, int] = {}
    for s in segs:
        bump(mut counts, s.a)
        bump(mut counts, s.b)
    mut out: Point[] = []
    for k in counts:
        if counts[k] >= 3:
            out.append(unkey(k))
    srt.sort_by(mut out, less_point)
    return out


public func append_segs(mut out: Seg[], pts: Point[]):
    for i in range(len(pts) - 1):
        out.append(Seg(a=pts[i], b=pts[i + 1]))


# Straight, the two L routes, two jogs, then progressively wider escape lanes.
func candidate(i: int, a: End, b: End) -> Point[]:
    if i < 5:
        return basic(i, a.at, b.at)
    mut k = i - 5
    mut steps = [2, 4, 6, 8, 12]
    return escaped(k % 5, a, b, steps[k // 5] * grid)


func escaped(join: int, a: End, b: End, step: int) -> Point[]:
    mut a2 = outward(a, step)
    mut b2 = outward(b, step)
    mut pts = [a.at, a2]
    pts.extend(join_lane(join, a2, b2))
    pts.append(b2)
    pts.append(b.at)
    return pts


func join_lane(join: int, a2: Point, b2: Point) -> Point[]:
    if join == 0:
        return []
    if join == 1:
        return [Point(x=b2.x, y=a2.y)]
    if join == 2:
        return [Point(x=a2.x, y=b2.y)]
    if join == 3:
        mut m = mid(a2.x, b2.x)
        return [Point(x=m, y=a2.y), Point(x=m, y=b2.y)]
    mut n = mid(a2.y, b2.y)
    return [Point(x=a2.x, y=n), Point(x=b2.x, y=n)]


func outward(e: End, step: int) -> Point:
    match e.side:
        case shape_mod.Side.left:
            return Point(x=e.at.x - step, y=e.at.y)
        case shape_mod.Side.right:
            return Point(x=e.at.x + step, y=e.at.y)
        case shape_mod.Side.top:
            return Point(x=e.at.x, y=e.at.y - step)
        case shape_mod.Side.bottom:
            return Point(x=e.at.x, y=e.at.y + step)


func basic(i: int, a: Point, b: Point) -> Point[]:
    if i == 0:
        return [a, b]
    if i == 1:
        return [a, Point(x=b.x, y=a.y), b]
    if i == 2:
        return [a, Point(x=a.x, y=b.y), b]
    if i == 3:
        mut m = mid(a.x, b.x)
        return [a, Point(x=m, y=a.y), Point(x=m, y=b.y), b]
    mut n = mid(a.y, b.y)
    return [a, Point(x=a.x, y=n), Point(x=b.x, y=n), b]


func point_count(i: int) -> int:
    if i == 0:
        return 2
    if i == 1 or i == 2:
        return 3
    return 4


func mid(u: int, v: int) -> int:
    return ((u + v) // 2 // grid) * grid


func compact(pts: Point[]) -> Point[]:
    mut out = [pts[0]]
    for p in pts[1:]:
        if not same_point(out[len(out) - 1], p):
            out.append(p)
    return out


func clean(pts: Point[], a: Point, b: Point, field: Field) -> bool:
    if len(pts) < 2:
        return False
    for i in range(len(pts) - 1):
        mut s = Seg(a=pts[i], b=pts[i + 1])
        if not legal(s) or hits_stop(s, field.stops, a, b) or hits_body(s, field.bodies) or hits_wire(s, field.segs, a, b):
            return False
    return True


func legal(s: Seg) -> bool:
    return not same_point(s.a, s.b) and (horizontal(s) or vertical(s)) and on_grid(s.a) and on_grid(s.b)


func horizontal(s: Seg) -> bool:
    return s.a.y == s.b.y


func vertical(s: Seg) -> bool:
    return s.a.x == s.b.x


func on_grid(p: Point) -> bool:
    return p.x % grid == 0 and p.y % grid == 0


func hits_stop(s: Seg, stops: Point[], a: Point, b: Point) -> bool:
    for p in stops:
        if same_point(p, a) or same_point(p, b):
            continue
        if on_seg(p, s):
            return True
    return False


func on_seg(p: Point, s: Seg) -> bool:
    return within(p.x, s.a.x, s.b.x) and within(p.y, s.a.y, s.b.y)


func within(v: int, lo: int, hi: int) -> bool:
    return v >= min(lo, hi) and v <= max(lo, hi)


func hits_body(s: Seg, bodies: Box[]) -> bool:
    for box in bodies:
        if enters_box(s, box):
            return True
    return False


func enters_box(s: Seg, box: Box) -> bool:
    if horizontal(s):
        return strictly(s.a.y, box.y0, box.y1) and crosses_x(s, box)
    return strictly(s.a.x, box.x0, box.x1) and crosses_y(s, box)


func crosses_x(s: Seg, box: Box) -> bool:
    return max(min(s.a.x, s.b.x), box.x0) < min(max(s.a.x, s.b.x), box.x1)


func crosses_y(s: Seg, box: Box) -> bool:
    return max(min(s.a.y, s.b.y), box.y0) < min(max(s.a.y, s.b.y), box.y1)


func strictly(v: int, lo: int, hi: int) -> bool:
    return v > lo and v < hi


func hits_wire(s: Seg, segs: Seg[], a: Point, b: Point) -> bool:
    for o in segs:
        if conflict(s, o, a, b):
            return True
    return False


func conflict(s: Seg, o: Seg, a: Point, b: Point) -> bool:
    if collinear(s, o):
        return overlaps(s, o, a, b)
    return touches(s, o, a, b)


func collinear(s: Seg, o: Seg) -> bool:
    if horizontal(s) and horizontal(o):
        return s.a.y == o.a.y
    return vertical(s) and vertical(o) and s.a.x == o.a.x


func overlaps(s: Seg, o: Seg, a: Point, b: Point) -> bool:
    mut es = axis_span(s)
    mut eo = axis_span(o)
    mut lo = max(es[0], eo[0])
    mut hi = min(es[1], eo[1])
    if lo > hi:
        return False
    if lo < hi:
        return True
    return not shared_end(s, o, point_at(s, lo), a, b)


func axis_span(s: Seg) -> int[]:
    if horizontal(s):
        return [min(s.a.x, s.b.x), max(s.a.x, s.b.x)]
    return [min(s.a.y, s.b.y), max(s.a.y, s.b.y)]


func point_at(s: Seg, v: int) -> Point:
    if horizontal(s):
        return Point(x=v, y=s.a.y)
    return Point(x=s.a.x, y=v)


# Interior crossings are legal; a tee or a foreign end meeting is not.
func touches(s: Seg, o: Seg, a: Point, b: Point) -> bool:
    mut p = cross_point(s, o)
    if p is None:
        return False
    if not is_end(s, p) and not is_end(o, p):
        return False
    return not shared_end(s, o, p, a, b)


func shared_end(s: Seg, o: Seg, p: Point, a: Point, b: Point) -> bool:
    return (same_point(p, a) or same_point(p, b)) and is_end(s, p) and is_end(o, p)


func cross_point(s: Seg, o: Seg) -> Point?:
    mut p = try meet(s, o)
    if not on_seg(p, s) or not on_seg(p, o):
        return None
    return Some(p)


func meet(s: Seg, o: Seg) -> Point?:
    if horizontal(s) and vertical(o):
        return Some(Point(x=o.a.x, y=s.a.y))
    if vertical(s) and horizontal(o):
        return Some(Point(x=s.a.x, y=o.a.y))
    return None


func is_end(s: Seg, p: Point) -> bool:
    return same_point(p, s.a) or same_point(p, s.b)


func bump(mut counts: dict[int, int], p: Point):
    mut k = point_key(p)
    counts[k] = counts.get(k, 0) + 1


# Private in Zig; exposed for the split sign-round-trip test.
public func point_key(p: Point) -> int:
    return (p.x + 1048576) * 2097152 + p.y + 1048576


public func unkey(k: int) -> Point:
    return Point(x=k // 2097152 - 1048576, y=k % 2097152 - 1048576)


func less_point(a: Point, b: Point) -> bool:
    if a.x != b.x:
        return a.x < b.x
    return a.y < b.y

import kicad_sch_wire as m
import kicad_sch_shape as shape
import support_expect as ex

const g: int = 127


func pt(x: int, y: int) -> m.Point:
    return m.Point(x=x, y=y)


func rightward(x: int, y: int) -> m.End:
    return m.End(at=pt(x, y), side=shape.Side.right)


func leftward(x: int, y: int) -> m.End:
    return m.End(at=pt(x, y), side=shape.Side.left)


func field() -> m.Field:
    return m.Field(stops=[], bodies=[], segs=[])


# test "kicad-sch: route prefers the straight run, then one bend"
public func test_kicad_sch_route_prefers_the_straight_run_then_one_bend(out: Stream) -> bool:
    mut straight = m.route(rightward(0, 0), leftward(10 * g, 0), field(), b"k")
    if straight is None:
        return ex.ok(out, "straight route", False)
    if not ex.eq_int(out, "straight points", len(straight.pts), 2) or not ex.eq_bytes(out, "stable key", straight.key, b"k"):
        return False
    mut bent = m.route(rightward(0, 0), leftward(10 * g, 4 * g), field(), b"k")
    if bent is None:
        return ex.ok(out, "bent route", False)
    if not ex.ok(out, "one horizontal-first bend", len(bent.pts) == 3 and bent.pts[1].x == 10 * g and bent.pts[1].y == 0):
        return False
    for p in bent.pts:
        if not ex.ok(out, "grid", p.x % g == 0 and p.y % g == 0):
            return False
    return True


# test "kicad-sch: route refuses a path that would run over a pin"
public func test_kicad_sch_route_refuses_a_path_that_would_run_over_a_pin(out: Stream) -> bool:
    mut from_ = rightward(0, 0)
    mut to = leftward(10 * g, 0)
    mut blocked = m.Field(stops=[pt(5 * g, 0)], bodies=[], segs=[])
    if not ex.ok(out, "foreign pin blocks", m.route(from_, to, blocked, b"k").is_none()):
        return False
    mut ends = m.Field(stops=[from_.at, to.at], bodies=[], segs=[])
    return ex.ok(out, "own endpoints exempt", m.route(from_, to, ends, b"k").is_some())


# test "kicad-sch: route crosses foreign wire but avoids tees, overlaps, and bodies"
public func test_kicad_sch_route_crosses_foreign_wire_but_avoids_tees_overlaps_and_bodies(out: Stream) -> bool:
    mut from_ = rightward(0, 0)
    mut to = leftward(10 * g, 0)
    mut crossing = m.Field(stops=[], bodies=[], segs=[m.Seg(a=pt(5 * g, -2 * g), b=pt(5 * g, 2 * g))])
    mut over = m.route(from_, to, crossing, b"k")
    if over is None:
        return ex.ok(out, "crossing route", False)
    if not ex.eq_int(out, "crossing straight", len(over.pts), 2):
        return False
    mut tee = m.Field(stops=[], bodies=[], segs=[m.Seg(a=pt(5 * g, 0), b=pt(5 * g, 2 * g))])
    if not ex.ok(out, "tee refused", m.route(from_, to, tee, b"k").is_none()):
        return False
    mut along = m.Field(stops=[], bodies=[], segs=[m.Seg(a=pt(3 * g, 0), b=pt(7 * g, 0))])
    if not ex.ok(out, "overlap refused", m.route(from_, to, along, b"k").is_none()):
        return False
    mut across = m.Field(stops=[], bodies=[m.Box(x0=4 * g, y0=-g, x1=6 * g, y1=g)], segs=[])
    if not ex.ok(out, "body refused", m.route(from_, to, across, b"k").is_none()):
        return False
    mut edge = m.Field(stops=[], bodies=[m.Box(x0=4 * g, y0=0, x1=6 * g, y1=2 * g)], segs=[])
    return ex.ok(out, "body edge allowed", m.route(from_, to, edge, b"k").is_some())


# test "kicad-sch: route gives up beyond the maximum span"
public func test_kicad_sch_route_gives_up_beyond_the_maximum_span(out: Stream) -> bool:
    if not ex.ok(out, "far refused", m.route(rightward(0, 0), leftward(m.max_span + g, 0), field(), b"k").is_none()):
        return False
    return ex.ok(out, "zero length refused", m.route(rightward(0, 0), leftward(0, 0), field(), b"k").is_none())


# test "kicad-sch: junctions names the three-way meeting points only"
public func test_kicad_sch_junctions_names_the_three_way_meeting_points_only(out: Stream) -> bool:
    mut hub = pt(4 * g, 4 * g)
    mut segs = [m.Seg(a=pt(0, 4 * g), b=hub), m.Seg(a=pt(8 * g, 4 * g), b=hub), m.Seg(a=pt(4 * g, 0), b=hub), m.Seg(a=pt(0, 0), b=pt(0, -2 * g)), m.Seg(a=pt(0, -2 * g), b=pt(2 * g, -2 * g))]
    mut dots = m.junctions(segs)
    if not ex.eq_int(out, "three-way only", len(dots), 1):
        return False
    if not ex.ok(out, "dot at hub", dots[0].x == hub.x and dots[0].y == hub.y):
        return False
    return ex.eq_int(out, "empty dots", len(m.junctions([])), 0)


# test "kicad-sch: the junction point key round-trips both signs"
public func test_kicad_sch_the_junction_point_key_round_trips_both_signs(out: Stream) -> bool:
    for p in [pt(0, 0), pt(12700, -6350), pt(-6350, 279400)]:
        mut back = m.unkey(m.point_key(p))
        if not ex.ok(out, "point key inverse", back.x == p.x and back.y == p.y):
            return False
    return True

import kicad_sym_library as m
import kicad_sym_testdata as data
import infra_fs as fsx
import support_expect as ex

func temp_project(fs: Filesystem, file_name: str) -> Result[str, str]:
    try fsx.make_path(fs, "project/lib/sources")
    try fs.write_file("project/lib/sources/" + file_name, data.vendor_flat())
    return Ok("project")


# test "kicad-sym: the vendor index matches names case-insensitively across _ and -"
public func test_kicad_sym_the_vendor_index_matches_names_case_insensitively_across_and(fs: Filesystem, out: Stream) -> bool:
    match temp_project(fs, "Acme_3.kicad_sym"):
        case Err(_):
            return False
        case Ok(dir_):
            mut lib = m.load(fs, out, dir_)
            if not ex.eq_int(out, "files", lib.files, 1):
                return False
            for name in [b"acme-3", b"ACME-3", b"acme_3"]:
                if not ex.ok(out, "name matches", m.library_find(lib, name).is_some()):
                    return False
            mut sym = m.library_find(lib, b"ACME_3")
            if sym is None:
                return False
            if not ex.eq_bytes(out, "symbol name", sym.name, b"ACME-3"):
                return False
            if not ex.ok(out, "empty misses", m.library_find(lib, b"").is_none()):
                return False
            return ex.ok(out, "unknown misses", m.library_find(lib, b"no-such-part").is_none())


# test "kicad-sym: the vendor index tolerates a missing directory and a junk library"
public func test_kicad_sym_the_vendor_index_tolerates_a_missing_directory_and_a_junk_library(fs: Filesystem, out: Stream) -> bool:
    mut missing = m.load(fs, out, "/nonexistent-project")
    if not ex.eq_int(out, "missing files", missing.files, 0):
        return False
    if not ex.ok(out, "missing index", m.library_find(missing, b"acme-3").is_none()):
        return False
    match temp_project(fs, "good.kicad_sym"):
        case Err(_):
            return False
        case Ok(dir_):
            match fs.write_file("project/lib/sources/junk.kicad_sym", b"((((not a library"):
                case Err(_):
                    return False
                case Ok(_):
                    pass
            mut lib = m.load(fs, out, dir_)
            if not ex.eq_int(out, "only good file", lib.files, 1):
                return False
            if not ex.ok(out, "good indexed", m.library_find(lib, b"acme-3").is_some()):
                return False
            return ex.ok(out, "junk skipped", m.library_find(lib, b"junk").is_none())

import sexpr_ast as ast
import sexpr_parser as parser
import numeric
import math
import support_sort as srt
import support_strs as strs
import support_parse as parse_mod

public const per_mm: int = 10000


public const max_coord: int = 100000000


public const err_not_symbol_lib: str = "NotSymbolLib"


public record Point:
    x: int = 0
    y: int = 0


public enum Fill:
    none
    outline
    background


public record Style:
    fill: Fill
    width: int = 0


public enum Kind:
    rectangle
    polyline
    circle
    arc
    text


public record Graphic:
    kind: Kind
    pts: Point[]
    text: bytes
    style: Style
    radius: int = 0
    angle: int = 0


public record Pin:
    pad: bytes
    name: bytes
    at: Point
    angle: int = 0
    length: int = 0
    hidden: bool = False


public record SymbolUnit:
    number: int
    pins: Pin[]
    graphics: Graphic[]


public record Symbol:
    name: bytes
    units: SymbolUnit[]


public func parse_library(source: bytes) -> Result[Symbol[], str]:
    mut nodes: ast.Node[] = []
    match parser.parse(source):
        case Err(e):
            return Err(parser.error_name(e))
        case Ok(parsed):
            nodes = parsed
    if len(nodes) == 0 or not ast.is_form(nodes[0], b"kicad_symbol_lib"):
        return Err(err_not_symbol_lib)
    mut root = ast.as_list(nodes[0])
    if root is None:
        return Err(err_not_symbol_lib)
    mut out: Symbol[] = []
    for child in root[1:len(root)]:
        if not ast.is_form(child, b"symbol"):
            continue
        mut sym = read_symbol(child)
        if sym is not None:
            out.append(sym.copy())
    return Ok(out)


# Private in Zig; public here for the split-file unitId test.
public record UnitId:
    unit: int
    style: int


record Acc:
    pins: Pin[]
    graphics: Graphic[]


# SymbolUnit contents accumulate in first-seen order; read_symbol sorts final units.
func read_symbol(node: ast.Node) -> Symbol?:
    mut cl = try ast.as_list(node)
    if len(cl) < 2:
        return None
    mut name = try ast.as_text(cl[1])
    mut units: dict[int, Acc] = {}
    collect(cl[2:len(cl)], 0, mut units)
    if len(units) == 0:
        return None
    mut out: SymbolUnit[] = []
    for number in units:
        mut acc = units[number].copy()
        out.append(SymbolUnit(number=number, pins=acc.pins.copy(), graphics=acc.graphics.copy()))
    srt.sort_by(mut out, less_unit)
    return Some(Symbol(name=name, units=out))


func less_unit(x: SymbolUnit, y: SymbolUnit) -> bool:
    return x.number < y.number


# Walk normal body children and per-unit sub-symbols. Electrical type and
# shape are deliberately ignored: the exporter writes every pin as passive.
func collect(children: ast.Node[], unit: int, mut units: dict[int, Acc]):
    for child in children:
        if ast.is_form(child, b"symbol"):
            collect_sub(child, mut units)
        elif ast.is_form(child, b"pin"):
            mut pin = read_pin(child)
            if pin is not None:
                acc_for(mut units, unit)
                units[unit].pins.append(pin.copy())
        else:
            mut graphic = read_graphic(child)
            if graphic is not None:
                acc_for(mut units, unit)
                units[unit].graphics.append(graphic.copy())


func collect_sub(node: ast.Node, mut units: dict[int, Acc]):
    mut sub = ast.as_list(node)
    if sub is None:
        return
    if len(sub) < 2:
        return
    mut name = ast.as_text(sub[1])
    if name is None:
        return
    mut id_ = unit_id(name)
    if id_ is None:
        return
    if id_.style > 1:
        return
    collect(sub[2:len(sub)], id_.unit, mut units)


func acc_for(mut units: dict[int, Acc], unit: int):
    if unit not in units:
        units[unit] = Acc(pins=[], graphics=[])


# The trailing <unit>_<style> numbers, allowing underscores in the base name.
# private in Zig
public func unit_id(name: bytes) -> UnitId?:
    mut cut = -1
    mut i = len(name) - 1
    while i >= 0:
        if name[i] == 95:
            cut = i
            break
        i -= 1
    if cut < 0:
        return None
    mut split = -1
    mut j = cut - 1
    while j >= 0:
        if name[j] == 95:
            split = j
            break
        j -= 1
    if split < 0:
        return None
    mut number = try parse_mod.parse_u32(strs.text(name[split + 1:cut]))
    mut style = try parse_mod.parse_u32(strs.text(name[cut + 1:len(name)]))
    return Some(UnitId(unit=int(number), style=int(style)))


func read_pin(node: ast.Node) -> Pin?:
    mut cl = try ast.as_list(node)
    mut p = Pin(pad=b"", name=b"", at=Point())
    for child in cl[1:len(cl)]:
        mut atom = ast.as_atom(child)
        if atom is not None:
            if atom == b"hide":
                p.hidden = True
        elif ast.is_form(child, b"at"):
            p.at = point_at(child, 1).unwrap_or(p.at)
            p.angle = degrees(scalar_at(child, 3).unwrap_or(0.0))
        elif ast.is_form(child, b"length"):
            p.length = unit_at(child, 1)
        elif ast.is_form(child, b"hide"):
            p.hidden = text_at(child, 1).unwrap_or(b"") == b"yes"
        elif ast.is_form(child, b"name"):
            p.name = text_at(child, 1).unwrap_or(b"").copy()
        elif ast.is_form(child, b"number"):
            p.pad = token_at(child, 1).unwrap_or(b"").copy()
    if len(p.pad) == 0:
        return None
    return Some(p)


func read_graphic(node: ast.Node) -> Graphic?:
    if ast.is_form(node, b"rectangle"):
        return corners(node, [b"start", b"end"], Kind.rectangle)
    if ast.is_form(node, b"arc"):
        return corners(node, [b"start", b"mid", b"end"], Kind.arc)
    if ast.is_form(node, b"polyline"):
        return vertices(node)
    if ast.is_form(node, b"circle"):
        return disc(node)
    if ast.is_form(node, b"text"):
        return label(node)
    return None


# Missing any named point makes a rectangle or arc malformed.
func corners(node: ast.Node, names: bytes[], kind: Kind) -> Graphic?:
    mut pts: Point[] = []
    for name in names:
        mut form = try find_form(node, name)
        mut pt = try point_at(form, 1)
        pts.append(pt)
    return Some(Graphic(kind=kind.copy(), pts=pts, text=b"", style=read_style(node)))


func vertices(node: ast.Node) -> Graphic?:
    mut form = try find_form(node, b"pts")
    mut cl = try ast.as_list(form)
    mut out: Point[] = []
    for child in cl[1:len(cl)]:
        if not ast.is_form(child, b"xy"):
            continue
        mut pt = point_at(child, 1)
        if pt is not None:
            out.append(pt)
    if len(out) < 2:
        return None
    return Some(Graphic(kind=Kind.polyline, pts=out, text=b"", style=read_style(node)))


func disc(node: ast.Node) -> Graphic?:
    mut centre_form = try find_form(node, b"center")
    mut centre = try point_at(centre_form, 1)
    mut radius_form = try find_form(node, b"radius")
    mut radius = unit_at(radius_form, 1)
    if radius <= 0:
        return None
    return Some(Graphic(kind=Kind.circle, pts=[centre], radius=radius, text=b"", style=read_style(node)))


func label(node: ast.Node) -> Graphic?:
    mut body = try text_at(node, 1)
    if len(body) == 0:
        return None
    mut anchor = try find_form(node, b"at")
    mut pt = try point_at(anchor, 1)
    return Some(Graphic(kind=Kind.text, pts=[pt], angle=degrees(scalar_at(anchor, 3).unwrap_or(0.0)), text=body, style=Style(fill=Fill.none)))


func read_style(node: ast.Node) -> Style:
    mut st = Style(fill=Fill.none)
    mut stroke = find_form(node, b"stroke")
    if stroke is not None:
        mut width = find_form(stroke, b"width")
        if width is not None:
            st.width = unit_at(width, 1)
    mut fill = find_form(node, b"fill")
    if fill is not None:
        mut type_form = find_form(fill, b"type")
        if type_form is not None:
            st.fill = fill_of(text_at(type_form, 1).unwrap_or(b""))
    return st


func fill_of(name: bytes) -> Fill:
    if name == b"background":
        return Fill.background
    if name == b"outline" or name == b"color":
        return Fill.outline
    return Fill.none


func find_form(node: ast.Node, name: bytes) -> ast.Node?:
    mut cl = try ast.as_list(node)
    for child in cl[1:len(cl)]:
        if ast.is_form(child, name):
            return Some(child.copy())
    return None


func text_at(node: ast.Node, i: int) -> bytes?:
    mut cl = try ast.as_list(node)
    if len(cl) <= i:
        return None
    return ast.as_text(cl[i])


func token_at(node: ast.Node, i: int) -> bytes?:
    mut cl = try ast.as_list(node)
    if len(cl) <= i:
        return None
    return ast.token_text(cl[i])


func scalar_at(node: ast.Node, i: int) -> float?:
    mut cl = try ast.as_list(node)
    if len(cl) <= i:
        return None
    return ast.as_number(cl[i])


func unit_at(node: ast.Node, i: int) -> int:
    return to_unit(scalar_at(node, i).unwrap_or(0.0))


func point_at(node: ast.Node, i: int) -> Point?:
    mut x = try scalar_at(node, i)
    mut y = try scalar_at(node, i + 1)
    return Some(Point(x=to_unit(x), y=to_unit(y)))


func to_unit(mm: float) -> int:
    mut v = int(numeric.checked_i32(math.round(mm * float(per_mm))).unwrap_or(0i32))
    return min(max(v, -max_coord), max_coord)


func degrees(v: float) -> int:
    return int(numeric.checked_i32(math.round(v)).unwrap_or(0i32))

import kicad_sym_reader as m
import kicad_sym_testdata as data
import support_expect as ex

func parsed(src: bytes) -> m.Symbol[]:
    match m.parse_library(src):
        case Ok(syms):
            return syms
        case Err(_):
            return []


# test "kicad-sym: reader parses a flat vendor symbol's pins and body graphics"
public func test_kicad_sym_reader_parses_a_flat_vendor_symbol_s_pins_and_body_graphics(out: Stream) -> bool:
    mut syms = parsed(data.vendor_flat())
    if not ex.eq_int(out, "symbols", len(syms), 1):
        return False
    if not ex.eq_bytes(out, "name", syms[0].name, b"ACME-3"):
        return False
    if not ex.eq_int(out, "units", len(syms[0].units), 1):
        return False
    mut u = syms[0].units[0].copy()
    if not ex.eq_int(out, "common", u.number, 0):
        return False
    if not ex.eq_int(out, "pins", len(u.pins), 3):
        return False
    if not ex.eq_bytes(out, "pad", u.pins[0].pad, b"1"):
        return False
    if not ex.eq_bytes(out, "function", u.pins[0].name, b"G"):
        return False
    if not ex.eq_int(out, "endpoint", u.pins[0].at.x, 0):
        return False
    if not ex.eq_int(out, "left pin angle", u.pins[0].angle, 0):
        return False
