public func draw_block_icon(mut w: byte_builder.Builder, icon_name: bytes, cx: float, cy: float, color: bytes):
    mut stroke = b"stroke=\"" + color + b"\" stroke-width=\"1.5\" opacity=\"0.5\""
    if icon_name == b"amplifier":
        mut size = 28.0
        mut half_h = size * 0.6
        mut lx = cx - size / 2.0
        mut rx = cx + size / 2.0
        mut ty = cy - half_h
        mut by = cy + half_h
        byte_builder.append(mut w, b"<polygon points=\"" + point_pair(lx, ty) + b" " + point_pair(lx, by) + b" " + point_pair(rx, cy) + b"\" fill=\"none\" " + stroke + b"/>\n")
        icon_text(mut w, cx, by + 14.0, 10, color, b"Amplifier")
    elif icon_name == b"ldo":
        mut icon_w = 36.0
        mut icon_h = 24.0
        mut ldo_lx = cx - icon_w / 2.0
        mut ldo_ty = cy - icon_h / 2.0
        mut ldo_rx = ldo_lx + icon_w
        byte_builder.append(mut w, b"<rect x=\"" + f1(ldo_lx) + b"\" y=\"" + f1(ldo_ty) + b"\" width=\"" + f1(icon_w) + b"\" height=\"" + f1(icon_h) + b"\" fill=\"none\" " + stroke + b" rx=\"2\"/>\n")
        svg_line(mut w, ldo_lx - 8.0, cy, ldo_lx, cy, stroke, True)
        icon_arrow(mut w, ldo_lx - 4.0, cy - 3.0, ldo_lx, cy, ldo_lx - 4.0, cy + 3.0, color)
        svg_line(mut w, ldo_rx, cy, ldo_rx + 8.0, cy, stroke, True)
        icon_arrow(mut w, ldo_rx + 4.0, cy - 3.0, ldo_rx + 8.0, cy, ldo_rx + 4.0, cy + 3.0, color)
        icon_text(mut w, cx, cy + 4.0, 9, color, b"LDO")
        icon_text(mut w, cx, ldo_ty + icon_h + 14.0, 10, color, b"Linear Regulator")
    elif icon_name == b"transistor":
        mut half = 24.0 / 2.0
        mut ch_x = cx + 4.0
        mut ch_top = cy - half
        mut ch_bot = cy + half
        mut gp_x = ch_x - 4.0
        svg_line(mut w, ch_x, ch_top, ch_x, ch_bot, b"stroke=\"" + color + b"\" stroke-width=\"2\" opacity=\"0.5\"", True)
        svg_line(mut w, cx - half, cy, gp_x, cy, stroke, True)
        svg_line(mut w, gp_x, ch_top + 3.0, gp_x, ch_bot - 3.0, stroke, True)
        svg_line(mut w, ch_x, ch_top, ch_x + 8.0, ch_top, stroke, True)
        svg_line(mut w, ch_x, ch_bot, ch_x + 8.0, ch_bot, stroke, True)
        icon_text(mut w, cx, ch_bot + 14.0, 10, color, b"Transistor")


# Zig's writer.print formatting factored into byte-exact attribute helpers.
func f1(v: float) -> bytes:
    return ff.fmt_float_prec(v, 1).encode()


func point_pair(x: float, y: float) -> bytes:
    return f1(x) + b"," + f1(y)


func svg_line(mut w: byte_builder.Builder, x1: float, y1: float, x2: float, y2: float, attrs: bytes, newline: bool):
    byte_builder.append(mut w, b"<line x1=\"" + f1(x1) + b"\" y1=\"" + f1(y1) + b"\" x2=\"" + f1(x2) + b"\" y2=\"" + f1(y2) + b"\" " + attrs + b"/>")
    if newline:
        byte_builder.append(mut w, b"\n")


func icon_arrow(mut w: byte_builder.Builder, x1: float, y1: float, x2: float, y2: float, x3: float, y3: float, color: bytes):
    byte_builder.append(mut w, b"<polygon points=\"" + point_pair(x1, y1) + b" " + point_pair(x2, y2) + b" " + point_pair(x3, y3) + b"\" fill=\"" + color + b"\" opacity=\"0.5\"/>\n")


func icon_text(mut w: byte_builder.Builder, x: float, y: float, size: int, color: bytes, text: bytes):
    byte_builder.append(mut w, b"<text x=\"" + f1(x) + b"\" y=\"" + f1(y) + b"\" text-anchor=\"middle\" font-size=\"" + str(size).encode() + b"\" fill=\"" + color + b"\" opacity=\"0.5\">" + text + b"</text>\n")


public func is_hub(inst: FlatInst) -> bool:
    return is_hub_ref(inst.ref_des)


public func is_hub_ref(ref_des: bytes) -> bool:
    mut rd = short_ref(ref_des)
    if len(rd) == 0:
        return True
    return rd[0]not in b"RCLFD"


public func is_ground_net(name: bytes) -> bool:
    for g in na.schematic_ground_names():
        if name == g:
            return True
    return name.startswith(b"VSS")


public func is_functional_signal_net(net: bytes) -> bool:
    return len(net_name.leaf(net)) != 0 and not is_supply_like_net(net)


public func is_supply_like_net(net: bytes) -> bool:
    mut local = net_name.leaf(net)
    if is_ground_net(local):
        return True
    for prefix in rails_mod.schematic_supply_prefixes():
        if strs.starts_with_ignore_case(local, prefix):
            return True
    return False


public func is_rail_output_pin_label(label: bytes) -> bool:
    mut buf: int[] = []
    for c in label:
        if c in b"_-/ .#":
            continue
        if len(buf) >= 32:
            return False
        buf.append(strs.to_upper(c))
    mut s = bytes(buf)
    while len(s) > 0 and strs.is_digit(s[len(s) - 1]):
        s = s[0:len(s) - 1]
    mut rest = b""
    if s.startswith(b"VOUT"):
        rest = s[4:]
    elif s.startswith(b"OUT"):
        rest = s[3:]
    else:
        return False
    return len(rest) == 0 or rest == b"PUT" or (len(rest) == 1 and strs.is_alphabetic(rest[0]))


public func short_ref(ref: bytes) -> bytes:
    return net_name.leaf(ref)


public func short_net_name(name: bytes) -> bytes:
    return net_name.leaf(name)


public func base_net_name(name: bytes) -> bytes:
    return na.base_net_name(name)


public func display_value(inst: FlatInst) -> bytes:
    if len(inst.value) > 0:
        return inst.value.copy()
    return inst.component.copy()


public func format_short(inst: FlatInst) -> bytes:
    if len(inst.value) > 0:
        return inst.value.copy()
    return inst.component.copy()


public func endpoint_eql(a: Endpoint, b: Endpoint) -> bool:
    match a:
        case Endpoint.net(value=an):
            match b:
                case Endpoint.net(value=bn):
                    return an == bn
                case _:
                    return False
        case Endpoint.pin(ref_des=ar, pin=ap):
            match b:
                case Endpoint.pin(ref_des=br, pin=bp):
                    return ar == br and ap == bp
                case _:
                    return False


public func classify_component(inst: FlatInst) -> bytes?:
    mut name_lower = inst.component.copy()
    if render_block_types.contains_ci(name_lower, b"pma") or render_block_types.contains_ci(name_lower, b"lna") or render_block_types.contains_ci(name_lower, b"mmic"):
        return Some(b"amplifier")
    if render_block_types.contains_ci(name_lower, b"tpsm") or render_block_types.contains_ci(name_lower, b"tps5") or render_block_types.contains_ci(name_lower, b"lm267"):
        return Some(b"buck")
    if render_block_types.contains_ci(name_lower, b"lt3045") or render_block_types.contains_ci(name_lower, b"lt3042") or render_block_types.contains_ci(name_lower, b"lp5907") or render_block_types.contains_ci(name_lower, b"ams1117"):
        return Some(b"ldo")
    mut ref = short_ref(inst.ref_des)
    if len(ref) > 0 and ref[0] == 81:
        return Some(b"transistor")
    if len(ref) > 0 and ref[0] == 68:
        return Some(b"led")
    return None


public func pin_order(a: bytes, b: bytes) -> bool:
    mut a_num = parse_mod.parse_int(strs.text(a))
    mut b_num = parse_mod.parse_int(strs.text(b))
    if a_num is not None and b_num is not None:
        return a_num < b_num
    if a_num is not None:
        return True
    if b_num is not None:
        return False
    return strs.bytes_less(a, b)

# The draw production module is merged into render_svg_context; tests stay
# separate so each mapped Zig file has exactly its original counterparts.
import byte_builder
import render_svg_context as m
import support_expect as ex

# test "rail output pin labels"
public func test_rail_output_pin_labels(out: Stream) -> bool:
    for label in [b"OUT", b"OUTS", b"VOUT", b"VOUT_2", b"out_1", b"OUTPUT", b"OUTA", b"Vout"]:
        if not ex.ok(out, "rail-producing label", m.is_rail_output_pin_label(label)):
            return False
    for other in [b"OUT_EN", b"VDD", b"VIN", b"SW", b"PGOOD", b"FB", b"PG", b"OUTFB", b""]:
        if not ex.ok(out, "other label", not m.is_rail_output_pin_label(other)):
            return False
    return True


# test "functional signal classification sees through a sub-block path"
public func test_functional_signal_classification_sees_through_a_sub_block_path(out: Stream) -> bool:
    for signal in [b"PAR_CTRL", b"dsa/PAR_CTRL", b"LMX_VTUNE"]:
        if not ex.ok(out, "functional signal", m.is_functional_signal_net(signal)):
            return False
    for rail in [b"VDD_F", b"dsa/VDD_F", b"ldo/V_3V3", b"dsa/GND", b"", b"dsa/"]:
        if not ex.ok(out, "no functional return", not m.is_functional_signal_net(rail)):
            return False
    return ex.ok(out, "path-qualified VCC", m.is_supply_like_net(b"mix/VCC")) and ex.ok(out, "path-qualified ground", m.is_supply_like_net(b"amp1/GND")) and ex.ok(out, "OUTP signal", not m.is_supply_like_net(b"mix/OUTP")) and ex.ok(out, "SW signal", not m.is_supply_like_net(b"boost5/SW"))


# test "drawNetWire escapes a quote/angle-bracket in the net name"
public func test_drawnetwire_escapes_a_quote_angle_bracket_in_the_net_name(out: Stream) -> bool:
    mut w = byte_builder.create()
    m.draw_net_wire(mut w, 0.0, 0.0, 10.0, 0.0, b"\"><script>alert(1)</script>")
    mut written = byte_builder.finish(w)
    return ex.ok(out, "raw script rejected", written.find(b"<script>") < 0) and ex.ok(out, "attribute XML escaping", written.find(b"data-net=\"&quot;&gt;&lt;script&gt;") >= 0)


# test "drawWire emits a straight line for a horizontal (y1==y2) wire"
public func test_drawwire_emits_a_straight_line_for_a_horizontal_y1_y2_wire(out: Stream) -> bool:
    mut w = byte_builder.create()
    m.draw_wire(mut w, 0.0, 5.0, 10.0, 5.0)
    mut written = byte_builder.finish(w)
    return ex.ok(out, "straight line", written.find(b"<line ") >= 0) and ex.ok(out, "no bend", written.find(b"<polyline") < 0)

# Port of zig/src/sexpr/ast.zig: the typed AST for S-expressions.
# Zig `[]const u8` is `bytes` here. Checked ownership returns independent copies;
# Zig `?T` is an optional type, and `Tag` is a mylang enum.
# Source location for error reporting. `offset` is the byte offset into source.
public record Span:
    line: int
    col: int
    offset: int


# Span.zero
public func span_zero() -> Span:
    return Span(line=1, col=1, offset=0)


public enum Tag:
    list(value: Node[])
    atom(value: bytes)
    string(value: bytes)
    int(value: int)
    float(value: float)
    unit_val(value: float)


# AST node. `literal` is the verbatim source spelling of a numeric literal that
# carried a unit or scale suffix (`100nF`, `4.7k`, `10%`), else None.
public record Node:
    tag: Tag
    span: Span
    literal: bytes?


public func node_list(span: Span, children: Node[]) -> Node:
    return Node(tag=Tag.list(value=children.copy()), span=span, literal=None)


public func node_atom(span: Span, name: bytes) -> Node:
    return Node(tag=Tag.atom(value=name.copy()), span=span, literal=None)


public func node_string(span: Span, value: bytes) -> Node:
    return Node(tag=Tag.string(value=value.copy()), span=span, literal=None)


public func node_int(span: Span, value: int) -> Node:
    return Node(tag=Tag.int(value=value), span=span, literal=None)


public func node_float(span: Span, value: float) -> Node:
    return Node(tag=Tag.float(value=value), span=span, literal=None)


# A numeric literal that keeps its source spelling: the same float node plus
# the `literal` text a value renderer prefers.
public func node_suffixed_float(span: Span, value: float, text: bytes) -> Node:
    return Node(tag=Tag.float(value=value), span=span, literal=Some(text.copy()))


public func node_unit_val(span: Span, mm_value: float) -> Node:
    return Node(tag=Tag.unit_val(value=mm_value), span=span, literal=None)


# Whether this node is a list whose first element is the given atom.
public func is_form(n: Node, name: bytes) -> bool:
    match n.tag:
        case Tag.list(value=children):
            if len(children) == 0:
                return False
            match children[0].tag:
                case Tag.atom(value=a):
                    return a == name
                case _:
                    return False
        case _:
            return False


# An independently owned copy of list children, or None if not a list.
public func as_list(n: Node) -> Node[]?:
    match n.tag:
        case Tag.list(value=children):
            return Some(children.copy())
        case _:
            return None


# Atom value, or None if not an atom.
public func as_atom(n: Node) -> bytes?:
    match n.tag:
        case Tag.atom(value=a):
            return Some(a.copy())
        case _:
            return None


# String value, or None if not a string.
public func as_string(n: Node) -> bytes?:
    match n.tag:
        case Tag.string(value=s):
            return Some(s.copy())
        case _:
            return None


# Literal text of a node (a quoted string or a bare atom) without evaluating it.
public func as_text(n: Node) -> bytes?:
    match n.tag:
        case Tag.string(value=s):
            return Some(s.copy())
        case Tag.atom(value=a):
            return Some(a.copy())
        case _:
            return None


# Like as_text, but also renders an integer node (`1` -> "1").
public func token_text(n: Node) -> bytes?:
    match n.tag:
        case Tag.atom(value=a):
            return Some(a.copy())
        case Tag.string(value=s):
            return Some(s.copy())
        case Tag.int(value=v):
            return Some(str(v).encode())
        case _:
            return None


# The source spelling of a suffixed numeric literal (`100nF`), else the node's
# own text (a string or atom).
public func value_text(n: Node) -> bytes?:
    match n.literal:
        case Some(text):
            return Some(text.copy())
        case None:
            return as_text(n)


# Numeric value as float (works for int, float and unit_val).
public func as_number(n: Node) -> float?:
    match n.tag:
        case Tag.int(value=i):
            return Some(float(i))
        case Tag.float(value=f):
            return Some(f)
        case Tag.unit_val(value=u):
            return Some(u)
        case _:
            return None

# Port of zig/src/sexpr/sexpr_paren_span.zig: balanced-paren matching over raw
# s-expression TEXT, for callers that splice bytes rather than re-print an AST.
# Quoted strings (and their `\` escapes) are skipped; `;` line comments are
# skipped only in the netlisp dialect.
# Whether the dialect being scanned has `;` line comments. KiCad's s-expressions
# do not, so a `;` there is an ordinary atom character.
public enum Comments:
    none
    line_semicolon


# Byte offset of the `)` that closes the form opening at `open`. None when
# `open` does not open a form and when the form is unterminated.
public func matching_close(source: bytes, open: int, comments: Comments) -> int?:
    if open >= len(source) or source[open] != ord("("):
        return None
    mut depth = 0
    mut in_string = False
    mut i = open
    mut n = len(source)
    while i < n:
        mut c = source[i]
        if in_string:
            if c == ord("\\") and i + 1 < n:
                i += 1
            elif c == ord("\""):
                in_string = False
            i += 1
            continue
        if c == ord("\""):
            in_string = True
        elif c == ord("("):
            depth += 1
        elif c == ord(")"):
            depth -= 1
            if depth == 0:
                return Some(i)
        elif c == ord(";") and comments == Comments.line_semicolon:
            while i < n and source[i] != ord("\n"):
                i += 1
        i += 1
    return None


# One past `matching_close` — the exclusive end offset a slice-and-splice
# caller wants.
public func end_index(source: bytes, open: int, comments: Comments) -> int?:
    match matching_close(source, open, comments):
        case Some(close):
            return Some(close + 1)
        case None:
            return None

# Port of zig/src/sexpr/tokenizer.zig: the S-expression lexer feeding the parser.
# Classifies atoms, strings and numeric literals (including SI-scaled electrical
# values like `220k`, `100nF`, `3.3V`, and dimension units `mm`/`mil`).
#
# Zig's optional byte `?u8` is an int here: -1 stands for "no byte" (end of
# input), so `peek(src, t) == -1` replaces `peek() == null`.
import sexpr_ast as ast

public enum TokenTag:
    lparen
    rparen
    atom
    string
    int
    float
    unit_val
    si_val
    eof


# One lexed token: classification, the verbatim source slice, and its span.
public record Token:
    tag: TokenTag
    text: bytes
    span: ast.Span


# One SI scale suffix: the letter (as a byte) and its multiplier. `bare` means
# the letter is a scale even with no unit letter following (`m` is not).
public record SiScale:
    letter: int
    multiplier: float
    bare: bool


public func si_scales() -> SiScale[]:
    return [SiScale(letter=ord("k"), multiplier=1e3, bare=True), SiScale(letter=ord("M"), multiplier=1e6, bare=True), SiScale(letter=ord("G"), multiplier=1e9, bare=True), SiScale(letter=ord("m"), multiplier=1e-3, bare=False), SiScale(letter=ord("u"), multiplier=1e-6, bare=True), SiScale(letter=ord("n"), multiplier=1e-9, bare=True), SiScale(letter=ord("p"), multiplier=1e-12, bare=True)]


# Unit letters accepted after a scale letter (or alone): "VAFHR".
public func si_unit_letters() -> bytes:
    return b"VAFHR"


# The percent sign closing a numeric literal (`10%`). Carries no scale.
public const PERCENT_SIGN: int = 37


public enum LexError:
    unexpected_character
    unterminated_string


# Mutable scan state, scalars only. It is kept apart from the source bytes
# because a `mut` argument whose record holds a `bytes` field costs about 5x per
# call in the pinned compiler (probes/gaps/g20_record_arg_cost.my); the helpers
# take `src` by value and the cursor by `mut`.
public record Cursor:
    pos: int
    line: int
    col: int
    # Span of the byte that triggered the most recent `next` error.
    error_span: ast.Span


public record Tokenizer:
    source: bytes
    cur: Cursor


public func tokenizer_init(source: bytes) -> Tokenizer:
    return Tokenizer(source=source.copy(), cur=Cursor(pos=0, line=1, col=1, error_span=ast.span_zero()))


# The byte at the cursor, or -1 at end of input.
func peek(src: bytes, t: Cursor) -> int:
    if t.pos >= len(src):
        return -1
    return src[t.pos]


func peek_at(src: bytes, t: Cursor, offset: int) -> int:
    mut idx = t.pos + offset
    if idx >= len(src):
        return -1
    return src[idx]


func advance(src: bytes, mut t: Cursor):
    if t.pos < len(src):
        if src[t.pos] == ord("\n"):
            t.line += 1
            t.col = 1
        else:
            t.col += 1
        t.pos += 1


func span_here(t: Cursor) -> ast.Span:
    return ast.Span(line=t.line, col=t.col, offset=t.pos)


func skip_whitespace_and_comments(src: bytes, mut t: Cursor):
    while True:
        mut c = peek(src, t)
        while c == ord(" ") or c == ord("\t") or c == ord("\n") or c == ord("\r"):
            advance(src, mut t)
            c = peek(src, t)
        if c == ord(";"):
            while peek(src, t) != -1 and peek(src, t) != ord("\n"):
                advance(src, mut t)
            continue
        break


func is_digit(c: int) -> bool:
    return c >= ord("0") and c <= ord("9")


func is_atom_start(c: int) -> bool:
    if c < 0:
        return False
    return (c >= ord("a") and c <= ord("z")) or (c >= ord("A") and c <= ord("Z")) or c == ord("_") or c == ord("~") or c == ord("*")


# `+`, `,` and `$` are included so vendor KiCad exports tokenize as a single atom.
func is_atom_continue(c: int) -> bool:
    if c < 0:
        return False
    return is_atom_start(c) or is_digit(c) or c == ord("-") or c == ord("/") or c == ord(".") or c == ord("*") or c == ord("#") or c == ord("@") or c == ord(":") or c == ord("+") or c == ord(",") or c == ord("$")


func is_operator_char(c: int) -> bool:
    return c == ord("+") or c == ord("-") or c == ord("/") or c == ord("%") or c == ord(">") or c == ord("<") or c == ord("=") or c == ord("!")


func is_unit_letter(c: int) -> bool:
    return c >= 0 and si_unit_letters().find(bytes([c])) >= 0


# Scale letters that stand on their own (`4.7k`).
func is_scale_letter(c: int) -> bool:
    for s in si_scales():
        if s.bare and s.letter == c:
            return True
    return False


# Scale letters that are only a scale when a unit letter follows (`10mA`).
func is_unit_required_scale(c: int) -> bool:
    for s in si_scales():
        if not s.bare and s.letter == c:
            return True
    return False


func make_token(src: bytes, tag: TokenTag, start: int, end: int, s: ast.Span) -> Token:
    return Token(tag=tag, text=src[start:end], span=s)


# Length (1 or 2) of an SI value suffix starting at the cursor, or 0 when the
# upcoming bytes are not one.
func si_suffix_len(src: bytes, t: Cursor) -> int:
    mut c0 = peek(src, t)
    if c0 < 0:
        return 0
    if is_scale_letter(c0):
        mut c1 = peek_at(src, t, 1)
        if not is_atom_continue(c1):
            return 1
        if c1 >= 0:
            if is_unit_letter(c1) and not is_atom_continue(peek_at(src, t, 2)):
                return 2
        return 0
    if is_unit_required_scale(c0):
        mut u = peek_at(src, t, 1)
        if u >= 0:
            if is_unit_letter(u) and not is_atom_continue(peek_at(src, t, 2)):
                return 2
        return 0
    if is_unit_letter(c0) and not is_atom_continue(peek_at(src, t, 1)):
        return 1
    return 0


func read_string(src: bytes, mut t: Cursor, s: ast.Span) -> Result[Token, LexError]:
    advance(src, mut t)
    mut start = t.pos
    while peek(src, t) != -1:
        mut ch = peek(src, t)
        if ch == ord("\\"):
            advance(src, mut t)
            advance(src, mut t)
            continue
        if ch == ord("\""):
            mut end = t.pos
            advance(src, mut t)
            return Ok(make_token(src, TokenTag.string, start, end, s))
        advance(src, mut t)
    t.error_span = s
    return Err(LexError.unterminated_string)


func read_number(src: bytes, mut t: Cursor, s: ast.Span) -> Token:
    mut start = t.pos
    if peek(src, t) == ord("-"):
        advance(src, mut t)
    while is_digit(peek(src, t)):
        advance(src, mut t)
    mut is_float = False
    if peek(src, t) == ord(".") and is_digit(peek_at(src, t, 1)):
        is_float = True
        advance(src, mut t)
        while is_digit(peek(src, t)):
            advance(src, mut t)
    mut num_end = t.pos
    if peek(src, t) == ord("m"):
        mut ch2 = peek_at(src, t, 1)
        if ch2 == ord("m") and not is_atom_continue(peek_at(src, t, 2)):
            advance(src, mut t)
            advance(src, mut t)
            return make_token(src, TokenTag.unit_val, start, num_end, s)
        if ch2 == ord("i"):
            mut ch3 = peek_at(src, t, 2)
            if ch3 == ord("l") and not is_atom_continue(peek_at(src, t, 3)):
                advance(src, mut t)
                advance(src, mut t)
                advance(src, mut t)
                return make_token(src, TokenTag.unit_val, start, num_end, s)
    mut suffix_len = si_suffix_len(src, t)
    if suffix_len > 0:
        for _ in range(suffix_len):
            advance(src, mut t)
        return make_token(src, TokenTag.si_val, start, t.pos, s)
    if peek(src, t) == PERCENT_SIGN and not is_atom_continue(peek_at(src, t, 1)):
        advance(src, mut t)
        return make_token(src, TokenTag.si_val, start, t.pos, s)
    if is_atom_continue(peek(src, t)):
        while is_atom_continue(peek(src, t)):
            advance(src, mut t)
        return make_token(src, TokenTag.atom, start, t.pos, s)
    if is_float:
        return make_token(src, TokenTag.float, start, t.pos, s)
    return make_token(src, TokenTag.int, start, t.pos, s)


func read_atom(src: bytes, mut t: Cursor, s: ast.Span) -> Token:
    mut start = t.pos
    while is_atom_continue(peek(src, t)):
        advance(src, mut t)
    return make_token(src, TokenTag.atom, start, t.pos, s)


func read_operator(src: bytes, mut t: Cursor, s: ast.Span) -> Token:
    mut start = t.pos
    advance(src, mut t)
    if peek(src, t) == ord("="):
        advance(src, mut t)
    return make_token(src, TokenTag.atom, start, t.pos, s)


# The next token, or a LexError (with `t.cur.error_span` set) for a bad
# character or an unterminated string.
public func next(mut t: Tokenizer) -> Result[Token, LexError]:
    mut cur = t.cur
    mut r = next_in(t.source, mut cur)
    t.cur = cur
    return r


func next_in(src: bytes, mut t: Cursor) -> Result[Token, LexError]:
    skip_whitespace_and_comments(src, mut t)
    mut s = span_here(t)
    mut c = peek(src, t)
    if c < 0:
        return Ok(Token(tag=TokenTag.eof, text=b"", span=s))
    if c == ord("("):
        advance(src, mut t)
        return Ok(make_token(src, TokenTag.lparen, s.offset, t.pos, s))
    if c == ord(")"):
        advance(src, mut t)
        return Ok(make_token(src, TokenTag.rparen, s.offset, t.pos, s))
    if c == ord("\""):
        return read_string(src, mut t, s)
    if is_digit(c) or (c == ord("-") and is_digit(peek_at(src, t, 1))):
        return Ok(read_number(src, mut t, s))
    if is_atom_start(c):
        return Ok(read_atom(src, mut t, s))
    if is_operator_char(c):
        return Ok(read_operator(src, mut t, s))
    t.error_span = s
    return Err(LexError.unexpected_character)

import stdlib_embed as embed
import infra_fs as fsx

# D9: roots are explicit values, never process-global state. Ordinary readers
# use no_roots(); open_with_roots serves clients with configured override roots.
# Project library, shared library, stdlib override, then bundle: first hit wins.
public const bundled_prefix: str = "netlisp:stdlib/"


public const max_stems_prefix: int = 37


public record Roots:
    lib: str = ""
    stdlib: str = ""


public record Found:
    path: str
    bytes: bytes
    bundled: bool


public record StemIterator:
    prefix: str
    index: int = 0


public func no_roots() -> Roots:
    return Roots()


public func set_roots(mut roots: Roots, lib: str?, stdlib: str?):
    roots.lib = lib.unwrap_or("").copy()
    roots.stdlib = stdlib.unwrap_or("").copy()


public func lib_root(roots: Roots) -> str?:
    if len(roots.lib) > 0:
        return Some(roots.lib.copy())
    return None


public func open(fs: Filesystem, project_dir: str, sub_path: str, max_bytes: int) -> Found?:
    return open_with_roots(fs, no_roots(), project_dir, sub_path, max_bytes)


public func open_with_roots(fs: Filesystem, roots: Roots, project_dir: str, sub_path: str, max_bytes: int) -> Found?:
    mut local = open_under(fs, project_dir, sub_path, max_bytes)
    if local.is_some():
        return local
    mut root = lib_root(roots)
    if root is not None and root != project_dir:
        mut shared = open_under(fs, root, sub_path, max_bytes)
        if shared.is_some():
            return shared
    return standard_with_roots(fs, roots, sub_path, max_bytes)


public func read(fs: Filesystem, project_dir: str, sub_path: str, max_bytes: int) -> bytes?:
    mut found = try open(fs, project_dir, sub_path, max_bytes)
    return Some(found.bytes.copy())


public func resolve_path(fs: Filesystem, project_dir: str, sub_path: str) -> str?:
    return resolve_path_with_roots(fs, no_roots(), project_dir, sub_path)


public func resolve_path_with_roots(fs: Filesystem, roots: Roots, project_dir: str, sub_path: str) -> str?:
    mut local = path_under(fs, project_dir, sub_path)
    if local.is_some():
        return local
    mut root = lib_root(roots)
    if root is not None and root != project_dir:
        mut shared = path_under(fs, root, sub_path)
        if shared.is_some():
            return shared
    if len(roots.stdlib) > 0:
        mut override = path_under(fs, roots.stdlib, strip_lib_prefix(sub_path))
        if override.is_some():
            return override
    if bundled(sub_path).is_none():
        return None
    return Some(bundled_path(sub_path))


public func exists(fs: Filesystem, project_dir: str, sub_path: str) -> bool:
    return resolve_path(fs, project_dir, sub_path).is_some()


public func standard(fs: Filesystem, sub_path: str, max_bytes: int) -> Found?:
    return standard_with_roots(fs, no_roots(), sub_path, max_bytes)


public func standard_with_roots(fs: Filesystem, roots: Roots, sub_path: str, max_bytes: int) -> Found?:
    if len(roots.stdlib) > 0:
        mut override = open_under(fs, roots.stdlib, strip_lib_prefix(sub_path), max_bytes)
        if override.is_some():
            return override
    mut data = try bundled(sub_path)
    if len(data) > max_bytes:
        return None
    return Some(Found(path=bundled_path(sub_path), bytes=data, bundled=True))


public func bundled(sub_path: str) -> bytes?:
    for entry in embed.entries():
        if entry.path == sub_path:
            return Some(entry.bytes.copy())
    return None


public func bundled_path(sub_path: str) -> str:
    return bundled_prefix + sub_path.copy()


public func is_bundled_path(path: str) -> bool:
    return path.startswith(bundled_prefix)


public func display_path(path: str) -> str:
    if is_bundled_path(path):
        return path[8:len(path)]
    return path.copy()


public func read_path(fs: Filesystem, path: str, max_bytes: int) -> bytes?:
    if is_bundled_path(path):
        mut data = try bundled(path[len(bundled_prefix):len(path)])
        if len(data) > max_bytes:
            return None
        return Some(data)
    match fsx.read_file_alloc(fs, path, max_bytes):
        case Ok(bytes_):
            return Some(bytes_.copy())
        case Err(_):
            return None


public func stem_iterator_next(mut self: StemIterator) -> str?:
    mut rows = embed.entries()
    while self.index < len(rows):
        mut entry_path = rows[self.index].path.copy()
        self.index += 1
        if not entry_path.startswith(self.prefix):
            continue
        mut rest = entry_path[len(self.prefix):len(entry_path)]
        if rest.find("/") >= 0 or not rest.endswith(".sexp"):
            continue
        return Some(rest[0:len(rest) - 5])
    return None


public func list_dirs(project_dir: str, sub: str, mut out: str[]):
    list_dirs_with_roots(no_roots(), project_dir, sub, mut out)


public func list_dirs_with_roots(roots: Roots, project_dir: str, sub: str, mut out: str[]):
    out.append(project_dir.copy() + "/lib/" + sub.copy())
    mut root = lib_root(roots)
    if root is not None and root != project_dir:
        out.append(root.copy() + "/lib/" + sub.copy())
    if len(roots.stdlib) > 0:
        out.append(roots.stdlib.copy() + "/" + sub.copy())


public func stems(prefix: str) -> StemIterator:
    return StemIterator(prefix=prefix.copy())


public func stems_in(sub: str) -> StemIterator:
    mut prefix = "lib/" + sub.copy() + "/"
    if len(prefix.encode()) > max_stems_prefix:
        return StemIterator(prefix="\x00")
    return StemIterator(prefix=prefix)


# The real filename under a root, and its whole bytes under the shared cap.
func open_under(fs: Filesystem, root: str, sub_path: str, max_bytes: int) -> Found?:
    mut path = root.copy() + "/" + sub_path.copy()
    match fsx.read_file_alloc(fs, path, max_bytes):
        case Err(_):
            return None
        case Ok(data):
            return Some(Found(path=path, bytes=data.copy(), bundled=False))


func path_under(fs: Filesystem, root: str, sub_path: str) -> str?:
    mut path = root.copy() + "/" + sub_path.copy()
    if fs.exists(path):
        return Some(path)
    return None


func strip_lib_prefix(sub_path: str) -> str:
    if sub_path.startswith("lib/"):
        return sub_path[4:len(sub_path)]
    return sub_path.copy()

import stdlib as m
import infra_fs as fsx
import support_strs as strs
import support_expect as ex

# test "the bundle carries the whole passives prelude"
public func test_the_bundle_carries_the_whole_passives_prelude(out: Stream) -> bool:
    mut prelude = ["cap-0201", "cap-0402", "cap-0603", "cap-0805", "res-0201", "res-0402", "res-0603", "res-0805", "ind-0201", "ind-0402", "ind-0603", "ind-0805", "ind-1616", "ind-2016", "ferrite-0402", "led-0402"]
    for name in prelude:
        if not expect_family_bundled(out, name):
            return False
    return True


func expect_family_bundled(out: Stream, name: str) -> bool:
    mut data = m.bundled("lib/components/" + name + ".sexp")
    if data is None:
        return ex.ok(out, "family bundled", False)
    return ex.ok(out, "footprint declared", data.find(b"(footprint ") >= 0)


# test "every bundled component's footprint and pinout is bundled too"
public func test_every_bundled_component_s_footprint_and_pinout_is_bundled_too(out: Stream) -> bool:
    mut comps = m.stems("lib/components/")
    while True:
        mut name = m.stem_iterator_next(mut comps)
        if name is None:
            break
        mut data = m.bundled("lib/components/" + name + ".sexp")
        if data is None:
            return False
        if not expect_referenced_file_bundled(out, data, b"(footprint ", "lib/footprints/"):
            return False
        if not expect_referenced_file_bundled(out, data, b"(pinout ", "lib/pinouts/"):
            return False
    return True


func expect_referenced_file_bundled(out: Stream, data: bytes, form: bytes, dir_: str) -> bool:
    mut at = data.find(form)
    if at < 0:
        return True
    mut rest = strs.trim_start(data[at + len(form):len(data)], b" \t\"")
    mut end = strs.index_of_any(rest, b" \t\")\n")
    if end < 0:
        return False
    return ex.ok(out, "referenced file bundled", m.bundled(dir_ + strs.text(rest[0:end]) + ".sexp").is_some())


# test "a project file overrides the bundle, and a missing one falls through to it"
public func test_a_project_file_overrides_the_bundle_and_a_missing_one_falls_through_to_it(fs: Filesystem, out: Stream) -> bool:
    match fsx.make_path(fs, "project/lib/components"):
        case Err(_):
            return False
        case Ok(_):
            pass
    mut local_src = b"(component-family \"cap-0402\" (symbol generic-cap) (footprint local-0402) (parameter \"value\" capacitance))"
    match fs.write_file("project/lib/components/cap-0402.sexp", local_src):
        case Err(_):
            return False
        case Ok(_):
            pass
    mut local = m.open(fs, "project", "lib/components/cap-0402.sexp", 1048576)
    if local is None:
        return False
    if not ex.ok(out, "project wins", not local.bundled):
        return False
    if not ex.ok(out, "project bytes", local.bytes.find(b"local-0402") >= 0):
        return False
    mut fell_through = m.open(fs, "project", "lib/components/res-0402.sexp", 1048576)
    if fell_through is None:
        return False
    if not ex.ok(out, "bundle fallback", fell_through.bundled):
        return False
    if not ex.ok(out, "synthetic path", m.is_bundled_path(fell_through.path)):
        return False
    return ex.eq_str(out, "path", fell_through.path, "netlisp:stdlib/lib/components/res-0402.sexp")


# test "a bundled path reads back by path"
public func test_a_bundled_path_reads_back_by_path(fs: Filesystem, out: Stream) -> bool:
    mut found = m.standard(fs, "lib/footprints/c-0402.sexp", 1048576)
    if found is None:
        return False
    mut again = m.read_path(fs, found.path, 1048576)
    if again is None:
        return False
    if not ex.eq_bytes(out, "reads by path", again, found.bytes):
        return False
    return ex.ok(out, "missing real file", m.read_path(fs, "/definitely/not/here.sexp", 1048576).is_none())


# test "a stdlib root overrides the embedded table"
public func test_a_stdlib_root_overrides_the_embedded_table(fs: Filesystem, out: Stream) -> bool:
    match fsx.make_path(fs, "override/components"):
        case Err(_):
            return False
        case Ok(_):
            pass
    mut src = b"(component-family \"res-0402\" (symbol generic-res) (footprint override-0402) (parameter \"value\" resistance))"
    match fs.write_file("override/components/res-0402.sexp", src):
        case Err(_):
            return False
        case Ok(_):
            pass
    mut roots = m.no_roots()
    m.set_roots(mut roots, None, Some("override"))
    mut found = m.open_with_roots(fs, roots, "/no/such/project", "lib/components/res-0402.sexp", 1048576)
    if found is None:
        return False
    if not ex.ok(out, "override beats bundle", not found.bundled):
        return False
    if not ex.ok(out, "override bytes", found.bytes.find(b"override-0402") >= 0):
        return False
    return ex.ok(out, "override adds without removing", m.resolve_path_with_roots(fs, roots, "/no/such/project", "lib/components/cap-0402.sexp").is_some())


# test "bundled stems list one sub-directory at a time"
public func test_bundled_stems_list_one_sub_directory_at_a_time(out: Stream) -> bool:
    mut comps = m.stems("lib/components/")
    if not lists_stem(out, mut comps, "cap-0402"):
        return False
    mut fps = m.stems_in("footprints")
    if not lists_stem(out, mut fps, "c-0402"):
        return False
    mut none = m.stems_in("datasheets")
    return ex.ok(out, "unknown dir empty", m.stem_iterator_next(mut none).is_none())


func lists_stem(out: Stream, mut it: m.StemIterator, want: str) -> bool:
    mut found = False
    while True:
        mut name = m.stem_iterator_next(mut it)
        if name is None:
            break
        if name == want:
            found = True
        if not ex.ok(out, "bare basename", name.find("/") < 0):
            return False
        if not ex.ok(out, "no suffix", not name.endswith(".sexp")):
            return False
    return found

import support_crc32 as crc
import support_expect as ex

# Expected values come from Python's `zlib.crc32`; 3421780262 (0xCBF43926) is the standard
# check value of "123456789".
public func test_empty_and_check_value(out: Stream) -> bool:
    if not ex.eq_int(out, "empty", crc.crc32(b""), 0):
        return False
    return ex.eq_int(out, "123456789", crc.crc32(b"123456789"), 3421780262)


public func test_text_and_binary(out: Stream) -> bool:
    if not ex.eq_int(out, "hello world", crc.crc32(b"hello world"), 222957957):
        return False
    mut ramp: int[] = []
    mut i = 0
    while i < 256:
        ramp.append(i)
        i += 1
    return ex.eq_int(out, "0..255", crc.crc32(bytes(ramp)), 688229491)


public func test_running_value_continues(out: Stream) -> bool:
    mut first = crc.crc32(b"hello ")
    if not ex.eq_int(out, "hello ", first, 3984718326):
        return False
    return ex.eq_int(out, "continued", crc.crc32_update(first, b"world"), crc.crc32(b"hello world"))

import support_expect as ex

# test "support_expect: passing checks return True and stay silent"
public func test_support_expect_passing_checks_return_true_and_stay_silent(out: Stream) -> bool:
    if not ex.ok(out, "one", 1 == 1):
        return False
    if not ex.eq_int(out, "n", 3, 3):
        return False
    if not ex.eq_str(out, "s", "a", "a"):
        return False
    if not ex.eq_bytes(out, "b", b"ab", b"ab"):
        return False
    if not ex.near(out, "f", 0.1 + 0.2, 0.3, 1e-9):
        return False
