# test "support_expect: failing checks return False"
public func test_support_expect_failing_checks_return_false(out: Stream) -> bool:
    mut quiet = out
    if ex.eq_int(quiet, "n", 3, 4):
        return False
    if ex.eq_bytes(quiet, "b", b"ab", b"ac"):
        return False
    if ex.near(quiet, "f", 1.0, 2.0, 0.5):
        return False
    return not ex.eq_strs(quiet, "l", ["a"], ["b"])

import support_float_fmt as ff

# The float table of PORTING.md ("Float formatting"): Zig rounds the shortest
# digits half up, exact-binary rounding (Go, Rust, strings.format_float) does not.
public func test_prec_rounds_the_shortest_digits_half_up() -> bool:
    if ff.fmt_float_prec(0.15, 1) != "0.2" or ff.fmt_float_prec(0.15, 2) != "0.15":
        return False
    if ff.fmt_float_prec(0.25, 1) != "0.3" or ff.fmt_float_prec(0.25, 2) != "0.25":
        return False
    if ff.fmt_float_prec(1.005, 1) != "1.0" or ff.fmt_float_prec(1.005, 2) != "1.01":
        return False
    if ff.fmt_float_prec(2.675, 1) != "2.7" or ff.fmt_float_prec(2.675, 2) != "2.68":
        return False
    if ff.fmt_float_prec(-1.25, 1) != "-1.3" or ff.fmt_float_prec(-1.25, 2) != "-1.25":
        return False
    return ff.fmt_float_prec(2.5, 0) == "3"


public func test_prec_pads_carries_and_keeps_the_sign_of_zero() -> bool:
    if ff.fmt_float_prec(-0.0, 1) != "-0.0" or ff.fmt_float_prec(-0.0, 2) != "-0.00":
        return False
    if ff.fmt_float_prec(1.0, 4) != "1.0000" or ff.fmt_float_prec(9.99, 1) != "10.0":
        return False
    if ff.fmt_float_prec(99.96, 1) != "100.0" or ff.fmt_float_prec(0.0004, 3) != "0.000":
        return False
    return ff.fmt_float_prec(0.0005, 3) == "0.001"


public func test_plain_d_is_shortest_digits_without_an_exponent() -> bool:
    if ff.fmt_float(1.0) != "1" or ff.fmt_float(-0.0) != "-0":
        return False
    if ff.fmt_float(0.5) != "0.5" or ff.fmt_float(1.5e-7) != "0.00000015":
        return False
    return ff.fmt_float(1000000.0) == "1000000"

import support_parse as sp

# `Some(x)` needs an expected Option type (E_OPTION_INFERENCE), so compare through these.
func is_int(v: int?, want: int) -> bool:
    if v is None:
        return False
    return v == want


func is_float(v: float?, want: float) -> bool:
    if v is None:
        return False
    return v == want


public func test_parse_int_accepts_what_zig_accepts() -> bool:
    if not is_int(sp.parse_int("5"), 5) or not is_int(sp.parse_int("+5"), 5) or not is_int(sp.parse_int("-5"), -5):
        return False
    if not is_int(sp.parse_int("1_0"), 10) or not is_int(sp.parse_int("010"), 10) or not is_int(sp.parse_int("-0"), 0):
        return False
    return is_int(sp.parse_int("-9223372036854775808"), -9223372036854775807 - 1)


public func test_parse_int_rejects_what_zig_rejects() -> bool:
    mut bad = [" 5", "5 ", "\t5", "5\n", "_1", "1_", "", "-", "+", "0x10", "1e3", "+-1", "1.0", "9223372036854775808", "-9223372036854775809"]
    for s in bad:
        if sp.parse_int(s) is not None:
            return False
    return True


public func test_parse_u32_range() -> bool:
    if not is_int(sp.parse_u32("4294967295"), 4294967295) or not is_int(sp.parse_u32("0"), 0) or not is_int(sp.parse_u32("+5"), 5):
        return False
    return sp.parse_u32("4294967296") is None and sp.parse_u32("-5") is None and is_int(sp.parse_u32("-0"), 0)


public func test_parse_float_accepts_what_zig_accepts() -> bool:
    if not is_float(sp.parse_float(".5"), 0.5) or not is_float(sp.parse_float("5."), 5.0) or not is_float(sp.parse_float("1e+3"), 1000.0):
        return False
    if not is_float(sp.parse_float("1_0.5"), 10.5) or not is_float(sp.parse_float("2.5e-7"), 0.00000025):
        return False
    mut inf = sp.parse_float("inf")
    if inf is None:
        return False
    return inf > 1e308 and sp.parse_float("nan") is not None


public func test_parse_float_rejects_what_zig_rejects() -> bool:
    mut bad = [" 1", "1 ", "\t1", "", "-", ".", "e3", "1e", "1d3", "1f"]
    for s in bad:
        if sp.parse_float(s) is not None:
            return False
    return True

