# flat_netlist.zig's frozen `uuidFromId` test hashes "canopy:" ++ id, and stamps the first
# 16 bytes as a v5 UUID; the digest half of that test is here.
public func test_canopy_id_digest(out: Stream) -> bool:
    return ex.eq_str(out, "canopy:aa000001", hex_of(b"canopy:aa000001"), "11d1e8b6ab30661ddee48da03a84febbaf746021b438fb3e69b3b447f8eb6cae")

# Byte-wise text helpers: the `std.mem`, `std.ascii` and `std.fs.path` calls that
# mylang's `str`/`bytes` methods lack or spell differently (the counterpart of Go's
# support/{ascii,strs,path}.go).
#
# Text rule of the port (see PORTING-MYLANG.md, "Text: bytes or str"): model and file
# text, tokens, AST atoms and everything emitted byte-for-byte are `bytes`; a `str`
# is for dict and set keys and short labels. Everything here takes a `bytes` unless
# the name or comment says `str`. Characters are `int` byte values (`ord("a")` is 97).
#
# Every function is ASCII-only or byte-wise, like Zig's: mylang's own `str.lower()`,
# `str.upper()`, `isalpha()` and `isdigit()` are ASCII-only too, so they agree, but
# `len(str)` counts Unicode scalars where Zig's `.len` counts bytes: use `byte_len`.
# Zig `s.len` of text held as a `str`: the UTF-8 byte count, not the scalar count.
public func byte_len(s: str) -> int:
    return len(s.encode())


# A `str` from `bytes` that must be UTF-8 (every model and golden file is). Traps
# `R_ASSERT` on invalid UTF-8 instead of returning a Result: nothing in the slice can
# recover from it, and Zig would have copied the bytes through unchecked.
public func text(b: bytes) -> str:
    match b.decode():
        case Ok(s):
            return s
        case Err(_):
            assert False, "invalid UTF-8 in text"
    return ""


# --- std.ascii ----------------------------------------------------------------
# `std.ascii.isDigit`.
public func is_digit(c: int) -> bool:
    return c >= 48 and c <= 57


# `std.ascii.isAlphabetic`.
public func is_alphabetic(c: int) -> bool:
    return (c >= 97 and c <= 122) or (c >= 65 and c <= 90)


# `std.ascii.isAlphanumeric`.
public func is_alphanumeric(c: int) -> bool:
    return is_alphabetic(c) or is_digit(c)


# `std.ascii.isUpper`.
public func is_upper(c: int) -> bool:
    return c >= 65 and c <= 90


# `std.ascii.isLower`.
public func is_lower(c: int) -> bool:
    return c >= 97 and c <= 122


# `std.ascii.isWhitespace`: space, \t, \n, \v, \f, \r.
public func is_whitespace(c: int) -> bool:
    return c == 32 or (c >= 9 and c <= 13)


# `std.ascii.toUpper`.
public func to_upper(c: int) -> int:
    if is_lower(c):
        return c - 32
    return c


# `std.ascii.toLower`.
public func to_lower(c: int) -> int:
    if is_upper(c):
        return c + 32
    return c


# `std.ascii.lowerString` / `allocLowerString`.
public func lower_bytes(s: bytes) -> bytes:
    mut out: int[] = []
    for c in s:
        out.append(to_lower(c))
    return bytes(out)


# `std.ascii.upperString` / `allocUpperString`.
public func upper_bytes(s: bytes) -> bytes:
    mut out: int[] = []
    for c in s:
        out.append(to_upper(c))
    return bytes(out)


# `std.ascii.eqlIgnoreCase`.
public func eql_ignore_case(a: bytes, b: bytes) -> bool:
    if len(a) != len(b):
        return False
    mut i = 0
    while i < len(a):
        if to_lower(a[i]) != to_lower(b[i]):
            return False
        i += 1
    return True


# `std.ascii.startsWithIgnoreCase`.
public func starts_with_ignore_case(haystack: bytes, needle: bytes) -> bool:
    if len(needle) > len(haystack):
        return False
    return eql_ignore_case(haystack[0:len(needle)], needle)


# `std.ascii.endsWithIgnoreCase`.
public func ends_with_ignore_case(haystack: bytes, needle: bytes) -> bool:
    if len(needle) > len(haystack):
        return False
    return eql_ignore_case(haystack[len(haystack) - len(needle):len(haystack)], needle)


# `std.ascii.indexOfIgnoreCase`: the first index of `needle` under ASCII case folding, or -1.
public func index_of_ignore_case(haystack: bytes, needle: bytes) -> int:
    mut i = 0
    while i + len(needle) <= len(haystack):
        if eql_ignore_case(haystack[i:i + len(needle)], needle):
            return i
        i += 1
    return -1


# --- std.mem ------------------------------------------------------------------
# `std.mem.order(u8, a, b)` as -1 (`.lt`), 0 (`.eq`) or 1 (`.gt`): bytewise, then by length.
public func bytes_order(a: bytes, b: bytes) -> int:
    mut n = len(a)
    if len(b) < n:
        n = len(b)
    mut i = 0
    while i < n:
        if a[i] != b[i]:
            if a[i] < b[i]:
                return -1
            return 1
        i += 1
    if len(a) < len(b):
        return -1
    if len(a) > len(b):
        return 1
    return 0


# `std.mem.lessThan(u8, a, b)`.
public func bytes_less(a: bytes, b: bytes) -> bool:
    return bytes_order(a, b) < 0


# `std.mem.order(u8, a, b)` for text held as `str` (mylang has no `<` on `str`).
# Unicode scalar order equals UTF-8 byte order, so this agrees with the byte compare.
public func str_order(a: str, b: str) -> int:
    return bytes_order(a.encode(), b.encode())


# `std.mem.lessThan(u8, a, b)` for `str`.
public func str_less(a: str, b: str) -> bool:
    return str_order(a, b) < 0


# `std.mem.indexOfPos`: the first index >= `start` of `needle` in `haystack`, or -1
# (an empty needle is found at `start`; a `start` past the end finds nothing).
public func index_of_pos(haystack: bytes, start: int, needle: bytes) -> int:
    if start > len(haystack):
        return -1
    mut r = haystack[start:len(haystack)].find(needle)
    if r < 0:
        return -1
    return start + r


# `std.mem.indexOfScalarPos`.
public func index_of_scalar_pos(haystack: bytes, start: int, c: int) -> int:
    if start >= len(haystack):
        return -1
    return haystack.find_any(bytes([c]), start)


# `std.mem.indexOfAny`: the first index of any byte of `values`, or -1.
public func index_of_any(s: bytes, values: bytes) -> int:
    return s.find_any(values, 0)


# `std.mem.lastIndexOfAny`.
public func last_index_of_any(s: bytes, values: bytes) -> int:
    mut i = len(s) - 1
    while i >= 0:
        if s[i] in values:
            return i
        i -= 1
    return -1


# `std.mem.trimStart` (`trimLeft`): drop any byte of `cutset` from the front.
public func trim_start(s: bytes, cutset: bytes) -> bytes:
    mut i = 0
    while i < len(s) and s[i] in cutset:
        i += 1
    return s[i:]


# `std.mem.trimEnd` (`trimRight`).
public func trim_end(s: bytes, cutset: bytes) -> bytes:
    mut i = len(s)
    while i > 0 and s[i - 1] in cutset:
        i -= 1
    return s[:i]


# `std.mem.trim`: drop any byte of `cutset` from both ends (mylang's `strip()` takes no set).
public func trim(s: bytes, cutset: bytes) -> bytes:
    return trim_end(trim_start(s, cutset), cutset)


# `std.mem.tokenizeAny` collected into a list: the non-empty runs between delimiter bytes.
public func tokenize_any(s: bytes, delimiters: bytes) -> bytes[]:
    mut out: bytes[] = []
    mut i = 0
    while i < len(s):
        while i < len(s) and s[i] in delimiters:
            i += 1
        mut start = i
        while i < len(s) and s[i]not in delimiters:
            i += 1
        if i > start:
            out.append(s[start:i])
    return out


# `std.mem.tokenizeScalar` collected into a list.
public func tokenize_scalar(s: bytes, delimiter: int) -> bytes[]:
    return tokenize_any(s, bytes([delimiter]))


# --- std.fs.path (POSIX), over `str` paths --------------------------------------
# Number of leading characters of `path` left after dropping trailing `/`.
func strip_trailing_slashes(path: str) -> int:
    mut end = len(path)
    while end > 0 and path[end - 1] == "/":
        end -= 1
    return end


# `std.fs.path.join`: naive `/` join of the non-empty parts, one separator where both
# sides carry one. It never cleans `.` or `..` and never collapses other separators.
public func path_join(parts: str[]) -> str:
    mut out = ""
    for p in parts:
        if len(p) == 0:
            continue
        if len(out) == 0:
            out = p.copy()
            continue
        mut prev_sep = out[len(out) - 1] == "/"
        mut this_sep = p[0] == "/"
        if not prev_sep and not this_sep:
            out = out + "/" + p.copy()
        elif prev_sep and this_sep:
            out = out + p[1:]
        else:
            out = out + p.copy()
    return out


# `std.fs.path.dirname`: the path up to its last component, `/` for a top-level absolute
# path, None for a path with no parent (`a`, `/`, empty).
public func path_dirname(path: str) -> str?:
    mut end = strip_trailing_slashes(path)
    if end == 0:
        return None
    mut i = end - 1
    while i >= 0 and path[i] != "/":
        i -= 1
    if i < 0:
        return None
    mut j = i
    while j > 0 and path[j - 1] == "/":
        j -= 1
    if j == 0:
        return Some(path[0:1])
    return Some(path[0:j])


# `std.fs.path.basename`: the last component, trailing `/` ignored; empty for an empty or root path.
public func path_basename(path: str) -> str:
    mut end = strip_trailing_slashes(path)
    if end == 0:
        return ""
    mut i = end - 1
    while i >= 0 and path[i] != "/":
        i -= 1
    return path[i + 1:end]


# --- integer formatting ----------------------------------------------------------
# Zig `{x:0>W}` of a non-negative integer: lower-case hex, zero-padded to `width` (never cut).
public func hex_pad(value: int, width: int) -> str:
    assert value >= 0, "hex_pad takes a non-negative value"
    mut digits = "0123456789abcdef"
    mut out = ""
    mut v = value
    while v > 0:
        out = digits[v % 16] + out
        v = v // 16
    while len(out) < width:
        out = "0" + out
    return out


# Zig `{d:0>W}` of a non-negative integer: decimal, zero-padded to `width` (never cut).
public func zero_pad(value: int, width: int) -> str:
    assert value >= 0, "zero_pad takes a non-negative value"
    mut out = str(value)
    while len(out) < width:
        out = "0" + out
    return out

import support_expect as ex
import support_strs as ss

# The expected values are Zig's (`std.mem`, `std.ascii`, `std.fs.path`) and the same
# cases the Go port's support tests assert.
public func test_text_and_byte_len_count_bytes_not_scalars(out: Stream) -> bool:
    if not ex.eq_int(out, "len of é as str", len("é"), 1):
        return False
    if not ex.eq_int(out, "byte_len of é", ss.byte_len("é"), 2):
        return False
    if not ex.eq_str(out, "text", ss.text(b"caf\xc3\xa9"), "café"):
        return False
    return ex.eq_bytes(out, "round trip", ss.text(b"caf\xc3\xa9").encode(), b"caf\xc3\xa9")


public func test_ascii_classes_and_case_are_byte_wise(out: Stream) -> bool:
    if not ex.ok(out, "Power == POWER", ss.eql_ignore_case(b"Power", b"POWER")):
        return False
    if not ex.ok(out, "é != É byte-wise", not ss.eql_ignore_case(b"\xc3\xa9", b"\xc3\x89")):
        return False
    if not ex.eq_bytes(out, "upper keeps non-ASCII", ss.upper_bytes(b"abc\xc3\xa9"), b"ABC\xc3\xa9"):
        return False
    if not ex.eq_bytes(out, "lower", ss.lower_bytes(b"AbC-1"), b"abc-1"):
        return False
    if not ex.ok(out, "starts", ss.starts_with_ignore_case(b"GNDA", b"gnd")):
        return False
    if not ex.ok(out, "starts, needle longer", not ss.starts_with_ignore_case(b"GN", b"gnd")):
        return False
    if not ex.ok(out, "ends", ss.ends_with_ignore_case(b"VCC_3V3", b"_3v3")):
        return False
    if not ex.eq_int(out, "indexOfIgnoreCase", ss.index_of_ignore_case(b"xxVccyy", b"VCC"), 2):
        return False
    if not ex.eq_int(out, "indexOfIgnoreCase miss", ss.index_of_ignore_case(b"ab", b"abc"), -1):
        return False
    return ex.ok(out, "classes", ss.is_digit(53) and not ss.is_digit(65) and ss.is_alphanumeric(122) and ss.is_whitespace(11) and not ss.is_whitespace(160))


public func test_order_is_bytewise_then_length(out: Stream) -> bool:
    if not ex.eq_int(out, "lt", ss.bytes_order(b"abc", b"abd"), -1):
        return False
    if not ex.eq_int(out, "prefix is lt", ss.bytes_order(b"ab", b"abc"), -1):
        return False
    if not ex.eq_int(out, "gt", ss.bytes_order(b"b", b"abc"), 1):
        return False
    if not ex.eq_int(out, "eq", ss.bytes_order(b"", b""), 0):
        return False
    if not ex.eq_int(out, "high byte sorts last", ss.bytes_order(b"z", b"\xc3\xa9"), -1):
        return False
    if not ex.ok(out, "str_less", ss.str_less("Zed", "abc") and not ss.str_less("é", "z")):
        return False
    return ex.ok(out, "bytes_less", ss.bytes_less(b"a", b"b") and not ss.bytes_less(b"a", b"a"))


public func test_search_from_an_offset(out: Stream) -> bool:
    if not ex.eq_int(out, "indexOfPos", ss.index_of_pos(b"abcabc", 2, b"bc"), 4):
        return False
    if not ex.eq_int(out, "start past end", ss.index_of_pos(b"abc", 4, b"a"), -1):
        return False
    if not ex.eq_int(out, "start at end, empty needle", ss.index_of_pos(b"abc", 3, b""), 3):
        return False
    if not ex.eq_int(out, "indexOfScalarPos", ss.index_of_scalar_pos(b"a,b,c", 2, 44), 3):
        return False
    if not ex.eq_int(out, "indexOfScalarPos at end", ss.index_of_scalar_pos(b"a,b", 3, 44), -1):
        return False
    if not ex.eq_int(out, "indexOfAny", ss.index_of_any(b"a\xffb", b"\xff"), 1):
        return False
    if not ex.eq_int(out, "indexOfAny miss", ss.index_of_any(b"abc", b"xyz"), -1):
        return False
    return ex.eq_int(out, "lastIndexOfAny", ss.last_index_of_any(b"a.b.c", b".,"), 3)


public func test_trim_and_tokenize_take_a_byte_set(out: Stream) -> bool:
    if not ex.eq_bytes(out, "trim", ss.trim(b" \tx y\n", b" \t\n"), b"x y"):
        return False
    if not ex.eq_bytes(out, "trim_start", ss.trim_start(b"--a--", b"-"), b"a--"):
        return False
    if not ex.eq_bytes(out, "trim_end", ss.trim_end(b"--a--", b"-"), b"--a"):
        return False
    if not ex.eq_bytes(out, "all trimmed", ss.trim(b"---", b"-"), b""):
        return False
    if not ex.ok(out, "tokenizeAny", ss.tokenize_any(b"  a,b ,,c ", b" ,") == [b"a", b"b", b"c"]):
        return False
    if not ex.eq_int(out, "only delimiters", len(ss.tokenize_any(b" ,", b" ,")), 0):
        return False
    return ex.ok(out, "tokenizeScalar", ss.tokenize_scalar(b"1.2.3", 46) == [b"1", b"2", b"3"])


func dirname_or(path: str, absent: str) -> str:
    match ss.path_dirname(path):
        case Some(d):
            return d
        case None:
            return absent.copy()


public func test_path_helpers_match_zig(out: Stream) -> bool:
    if not ex.eq_str(out, "join", ss.path_join(["a", "b"]), "a/b"):
        return False
    if not ex.eq_str(out, "join, both separators", ss.path_join(["a/", "/b"]), "a/b"):
        return False
    if not ex.eq_str(out, "join keeps ./", ss.path_join(["./lib", "x"]), "./lib/x"):
        return False
    if not ex.eq_str(out, "join skips empties", ss.path_join(["", "a", "", "b"]), "a/b"):
        return False
    if not ex.eq_str(out, "dirname", dirname_or("/a/b/c///", "-"), "/a/b"):
        return False
    if not ex.eq_str(out, "dirname of a top-level path", dirname_or("/a", "-"), "/"):
        return False
    if not ex.eq_str(out, "dirname of a bare name", dirname_or("a/", "-"), "-"):
        return False
    if not ex.eq_str(out, "basename", ss.path_basename("/dir/basename.ext//"), "basename.ext"):
        return False
    return ex.eq_str(out, "basename of /", ss.path_basename("/"), "")


public func test_integer_padding_matches_zig_format(out: Stream) -> bool:
    if not ex.eq_str(out, "{x:0>2} of 10", ss.hex_pad(10, 2), "0a"):
        return False
    if not ex.eq_str(out, "{x:0>2} of 255", ss.hex_pad(255, 2), "ff"):
        return False
    if not ex.eq_str(out, "{x:0>8} of 0", ss.hex_pad(0, 8), "00000000"):
        return False
    if not ex.eq_str(out, "{x:0>2} is never cut", ss.hex_pad(4096, 2), "1000"):
        return False
    if not ex.eq_str(out, "{d:0>2}", ss.zero_pad(7, 2), "07"):
        return False
    return ex.eq_str(out, "{d:0>2} is never cut", ss.zero_pad(123, 2), "123")

import zipfile as m
import byte_builder
import strings
import support_expect as ex
import support_crc32 as crc_mod

# Independent store-method reader: follow the central-directory local offsets
# and lengths, verify CRC and recover each name/content. The evidence driver
# additionally checks the archive with Python's standard zipfile extractor.
func read_int(data: bytes, start: int, width: int) -> int:
    mut value = 0
    mut multiplier = 1
    for i in range(width):
        value += data[start + i] * multiplier
        multiplier *= 256
    return value


func count(data: bytes, needle: bytes) -> int:
    mut n = 0
    mut pos = 0
    while pos + len(needle) <= len(data):
        if data[pos:pos + len(needle)] == needle:
            n += 1
        pos += 1
    return n


func error_of(result: Result[Unit, str]) -> str:
    match result:
        case Ok(_):
            return ""
        case Err(e):
            return e.copy()


# test "write produces an archive std.zip can extract"
public func test_write_produces_an_archive_std_zip_can_extract(out: Stream) -> bool:
    mut entries = [m.Entry(name=b"a-F_Cu.gtl", data=b"G04 top*\nM02*\n"), m.Entry(name=b"a-PTH.drl", data=b"M48\nM30\n")]
    mut w = byte_builder.create()
    if not ex.eq_str(out, "write", error_of(m.write(mut w, entries)), ""):
        return False
    mut data = byte_builder.finish(w)
    if not ex.ok(out, "local header", data.startswith(b"PK\x03\x04")):
        return False
    if not ex.eq_int(out, "local headers", count(data, b"PK\x03\x04"), 2):
        return False
    if not ex.eq_int(out, "central headers", count(data, b"PK\x01\x02"), 2):
        return False
    if not ex.eq_int(out, "end record", count(data, b"PK\x05\x06"), 1):
        return False
    mut eocd = len(data) - 22
    if not ex.eq_int(out, "end entries", read_int(data, eocd + 10, 2), 2):
        return False
    mut cd_off = read_int(data, eocd + 16, 4)
    if not ex.ok(out, "central offset", data[cd_off:len(data)].startswith(b"PK\x01\x02")):
        return False
    if not ex.ok(out, "visible data", data.find(b"G04 top*") >= 0):
        return False
    mut seen = 0
    mut pos = cd_off
    while seen < read_int(data, eocd + 10, 2):
        if not ex.ok(out, "store method", read_int(data, pos + 10, 2) == 0):
            return False
        mut name_len = read_int(data, pos + 28, 2)
        mut extra_len = read_int(data, pos + 30, 2)
        mut comment_len = read_int(data, pos + 32, 2)
        mut filename = data[pos + 46:pos + 46 + name_len]
        mut local = read_int(data, pos + 42, 4)
        mut length = read_int(data, pos + 24, 4)
        mut payload_at = local + 30 + read_int(data, local + 26, 2) + read_int(data, local + 28, 2)
        mut extracted = data[payload_at:payload_at + length]
        if not ex.eq_bytes(out, "filename", filename, entries[seen].name):
            return False
        if not ex.eq_bytes(out, "extracted data", extracted, entries[seen].data):
            return False
        if not ex.eq_int(out, "CRC", crc_mod.crc32(extracted), read_int(data, pos + 16, 4)):
            return False
        if not ex.eq_int(out, "valid fixed DOS date", read_int(data, local + 12, 2), 33):
            return False
        seen += 1
        pos += 46 + name_len + extra_len + comment_len
    return ex.eq_int(out, "all entries opened", seen, len(entries))


# test "write rejects ZIP32 field overflow before producing bytes"
public func test_write_rejects_zip32_field_overflow_before_producing_bytes(out: Stream) -> bool:
    mut too_many: m.Entry[] = []
    for i in range(65536):
        too_many.append(m.Entry(name=b"a", data=b""))
    mut w = byte_builder.create()
    if not ex.eq_str(out, "too many entries", error_of(m.write(mut w, too_many)), "WriteFailed"):
        return False
    if not ex.eq_int(out, "no partial archive", len(byte_builder.finish(w)), 0):
        return False
    match strings.repeat("n", 65536):
        case Err(_):
            return False
        case Ok(long_name):
            if not ex.eq_str(out, "long name", error_of(m.write(mut w, [m.Entry(name=long_name.encode(), data=b"")])), "WriteFailed"):
                return False
    return ex.eq_int(out, "still no bytes", len(byte_builder.finish(w)), 0)


# test "encoded size predicts the complete archive before allocation"
public func test_encoded_size_predicts_the_complete_archive_before_allocation(out: Stream) -> bool:
    mut entries = [m.Entry(name=b"a.txt", data=b"abc"), m.Entry(name=b"nested/b.bin", data=b"12345")]
    mut w = byte_builder.create()
    if not ex.eq_str(out, "write", error_of(m.write(mut w, entries)), ""):
        return False
    match m.encoded_size(entries):
        case Err(_):
            return False
        case Ok(size):
            return ex.eq_int(out, "complete size", len(byte_builder.finish(w)), size)


# test "fuzz: write emits a well-formed archive for arbitrary entry bytes"
public func test_fuzz_write_emits_a_well_formed_archive_for_arbitrary_entry_bytes(out: Stream) -> bool:
    mut corpus = [b"", b"one", b"a/b/c.bin\nentry data", b"PK\x03\x04\x00\xff\x7f"]
    for input_ in corpus:
        mut split = len(input_) // 2
        mut name0 = input_[0:min(len(input_), 8)]
        if len(name0) == 0:
            name0 = b"n"
        mut entries = [m.Entry(name=name0, data=input_.copy()), m.Entry(name=b"second.bin", data=input_[split:len(input_)])]
        mut w = byte_builder.create()
        if not ex.eq_str(out, "write", error_of(m.write(mut w, entries)), ""):
            return False
        mut data = byte_builder.finish(w)
        if not ex.ok(out, "leading local header", data.startswith(b"PK\x03\x04")):
            return False
        if not ex.ok(out, "end record present", data.find(b"PK\x05\x06") >= 0):
            return False
    return True
